window.ZTOBJ={"ch01":{"mcq":[],"fill":[{"q":"1． 本规律的学科。","a":"显微；亚显微；分子水平；细胞间的相互作用关系","src":"章节题库","oe":["显微水平：用光学显微镜观察细胞的形态与结构。","亚显微水平：用电子显微镜观察细胞器的超微结构。","分子水平：研究蛋白质、核酸等生物大分子的结构与功能。","细胞间的相互作用关系：研究细胞间信号通讯与相互影响。"]},{"q":"2．","a":"从静态分析到活细胞的动态综合","src":"章节题库"},{"q":"3． 位，个体发育的基本单位，各种复杂生命活动现象的表现形式。","a":"细胞；生命活动的基本单位","src":"章节题库","oe":["细胞：细胞是构成有机体形态结构和功能的基本单位。","生命活动的基本单位：个体发育及各种复杂生命活动均以细胞为基础。"]},{"q":"4．","a":"1665；胡克；1838～1839；植物学家施莱登；动物学家施旺","src":"章节题库"},{"q":"5． ______。","a":"胡克；列文虎克","src":"章节题库","oe":["胡克首次发现并命名细胞（观察软木死细胞的细胞壁），列文虎克首次观察到活细胞。"]},{"q":"6． 学几个时期。","a":"细胞的发现；细胞学说的建立；细胞学的形成；细胞生物学兴起","src":"章节题库","oe":["细胞的发现：1665年胡克观察软木薄片发现并命名细胞。","细胞学说的建立：施莱登、施旺提出一切动植物由细胞构成。","细胞学的形成：细胞学说被广泛验证并发展为独立学科。","细胞生物学兴起：从显微、超微到分子水平研究细胞生命活动。"]}],"judge":[]},"ch02":{"mcq":[{"q":"有关原核细胞与真核细胞的比较，下列说法错误的是（          ）。","o":["A．现有资料证明真核细胞由原核细胞进化而来，自然界真核细胞的个体数量比原核细胞多","B．真核细胞内有一个较复杂的骨架体系，原核细胞内并没有明显的骨架系统","C．真核细胞基因表达具有严格的时空关系，并具有多层次的调控","D．真核细胞内膜系统分化，内部结构与功能的区域化与专一化，是进化过程的一次飞跃"],"a":"A","e":"尽管真核细胞在结构与功能上相对复杂，但在特定条件下的适应能力并不具有优越 性，几乎在地球的各个角落都有原核细胞存在，原核细胞的个体数量也远比真核多。","src":"章节题库","oe":["错误。原核细胞分布广、数量远比真核多，A说真核数量多与事实相反，故选A。","正确。真核细胞有微管、微丝等复杂骨架系统，原核细胞无明显骨架。","正确。真核基因表达具有严格时空性和多层次调控特点。","正确。内膜系统分化与结构功能区域化专一化是进化飞跃。"]},{"q":"下列有关细菌细胞壁的说法错误的是（          ）。","o":["A．肽聚糖是所有细菌细胞壁的共同组分","B．革兰阳性菌比菌阴性的壁厚，且壁酸含量较阴性菌高","C．青霉素可以抑制壁酸的合成，革兰阳性菌和阴性菌细胞壁都含有壁酸，故两者对青霉素 都具有较高的敏感性","D．细胞壁的成分与抗原性、致病性及对病毒的敏感性均有关系"],"a":"C","e":"革兰阳性菌细胞壁壁酸含量高达 90％，而革兰阴性菌细胞壁壁酸含量仅占 5％，因 而革兰阳性菌对青霉素敏感，而革兰阴性菌对青霉素不敏感。","src":"章节题库","oe":["正确。肽聚糖是细菌细胞壁的共同组分（支原体等除外）。","正确。革兰阳性菌细胞壁较厚，壁酸（磷壁酸）含量高于阴性菌。","错误。革兰阴性菌壁酸含量仅约5%，对青霉素不敏感，故选C。","正确。细胞壁成分与抗原性、致病性及对病毒的敏感性有关。"]},{"q":"指出下列哪项是原核生物（          ）。","o":["A．病毒","B．支原体","C．疟原虫","D．噬菌体"],"a":"B","e":"噬菌体为植物病毒，病毒不具有细胞形态，疟原虫属于真核生物。","src":"章节题库","oe":["错误。病毒无细胞结构，不属于细胞，不能独立进行代谢与增殖。","正确。支原体是能独立生活的最小、最简单的原核细胞。","错误。疟原虫属真核生物，有完整细胞核和细胞器。","错误。噬菌体是侵染细菌的病毒，无细胞结构，不属于细胞。"]},{"q":"支原体是最简单的细胞，下列叙述不正确的是（          ）。","o":["A．是目前发现的最小、最简单的细胞，直径一般只有 0.1～0.3μm","B．目前已经从动物、污染的环境及植物中分离出很多支原体","C．最早发现的支原体为拟胸膜肺炎病原体","D．支原体具备细胞壁，同时也具备形态的多样性"],"a":"D","e":"支原体因为没有细胞壁，形态可以随意变化，因而具有多形态性。","src":"章节题库","oe":["正确。支原体是目前发现的最小、最简单的细胞，直径约0.1～0.3μm。","正确。已从动物、污染环境及植物中分离出多种支原体。","正确。最早发现的支原体是拟胸膜肺炎病原体。","错误。支原体没有细胞壁，故形态多变，D说具细胞壁错误，故选D。"]},{"q":"细胞体积守恒定律表明（        ）。","o":["A．细胞的体积与相对表面积成反比","B．细胞体积和细胞核体积在不同物种间均相差悬殊","C．器官的大小主要取决于细胞的数量和细胞的大小两个关键因素","D．卵细胞与外界物质交换很少，同样遵守细胞体积守恒定律"],"a":"A","e":"细胞体积守恒定律的主要观点：（1）不论物种间的差异有多大，同一器官与组织 的细胞，其大小更倾向在一个恒定的范围之内。（2）细胞的体积与相对表面积成反比。（3） 细胞体积在不同物种间均相差悬殊，而细胞核体积相差不大。（4）器官的大小主要取决于 细胞的数量，与细胞的数量成正比，而与细胞的大小无关。（5）细胞内物质交流的速率与 细胞体积成反比。","src":"章节题库","oe":["正确。细胞体积越大，其相对表面积越小，二者成反比。","错误。不同物种细胞体积相差悬殊，但细胞核体积相差不大。","错误。器官大小主要取决于细胞数量，与细胞大小无关。","错误。卵细胞体积大、与外界交换少，是细胞体积定律的例外。"]},{"q":"SARS 病毒是（  ）。","o":["A．DNA 病毒","B．RNA 病毒","C．类病毒","D．朊病毒"],"a":"A","e":"SARS 病毒是一种冠状病毒，其遗传物质是 DNA，被蛋白壳体包绕。","src":"章节题库","oe":["A：题源答案为DNA病毒；但SARS冠状病毒遗传物质实为单链RNA，该答案有误。","B：按病毒学事实，SARS冠状病毒应属RNA病毒，而非题源所给A。","C：类病毒仅含裸露RNA、无蛋白外壳，与SARS病毒不同。","D：朊病毒仅由感染性蛋白质构成、不含核酸，与SARS无关。"]},{"q":"前病毒是（     ）。","o":["A．RNA 病毒","B．逆转录 RNA 病毒","C．整合到宿主 DNA 中的逆转录 DNA","D．整合到宿主 DNA 中的 DNA 病毒"],"a":"C","e":"逆转录病毒（retrovirus）又称 RNA 肿瘤病毒，其复制过程分两个阶段：第一阶段， 病毒核酸进入胞浆后，以 RNA 为模板，合成 DNA，转入细胞核内，整合成宿主 DNA，成 为前病毒。第二阶段，前病毒 DNA 转录病毒 mRNA，翻译病毒蛋白质。前病毒 DNA 还转 录病毒 RNA，在胞浆内装配，以出芽方式释放。","src":"章节题库","oe":["不准确。前病毒已整合为DNA，不再以游离RNA病毒形式存在。","不准确。逆转录RNA病毒指病毒颗粒，前病毒是其整合后的DNA形式。","正确。逆转录病毒核酸经逆转录成DNA并整合入宿主DNA，即前病毒。","错误。逆转录病毒属RNA病毒，只是复制过程中有DNA中间体。"]},{"q":"下列论据中，不支持论点“病毒是细胞的演化产物”的是（         ）。","o":["A．病毒彻底寄生于细胞中，没有细胞的存在就没有病毒的复制","B．病毒癌基因起源于细胞癌基因","C．与细胞相比，病毒的结构与功能体系相对简单，由进化观点可推知","D．细胞内的核蛋白分子与病毒有相似之处","E．真核生物中普遍存在第二类反转录转座子的两端含有长末端重复序列，其结构与整合于 基因组上的反转录病毒十分相似"],"a":"C","e":"病毒的结构与功能体系相对细胞简单，由进化观点推知：细胞是病毒的演化产物， 而与题干观点相反。","src":"章节题库","oe":["正确。病毒严格寄生于细胞内，离开细胞不能复制。","正确。病毒癌基因起源于宿主细胞的细胞癌基因。","错误。进化上细胞应先于病毒出现，病毒由细胞衍生，故选C。","正确。细胞内核蛋白复合物与病毒的核蛋白有相似之处。","正确。真核生物反转录转座子两端LTR与整合的反转录病毒相似。"]},{"q":"下列选项有关病毒增殖过程的叙述错误的是（          ）。","o":["A．病毒在宿主细胞内分别复制病毒核酸与翻译病毒蛋白，在细胞外组装成病毒颗粒","B．病毒进入细胞的主要方式是“主动吞饮”","C．逆转录病毒 RNA 可以整合到宿主细胞的染色体 DNA 上，并表达特异蛋白，使细胞转型","D．病毒自身没有独立的代谢与能量转化系统"],"a":"A","e":"病毒的组装过程是在宿主细胞内进行的，故选 A。其他选项说法正确。","src":"章节题库","oe":["错误。病毒核酸复制、蛋白翻译与颗粒组装均在宿主细胞内完成，故选A。","正确。病毒常以受体介导的吞饮/内吞方式进入宿主细胞。","正确。逆转录病毒RNA可整合到宿主染色体DNA并表达蛋白使细胞转型。","正确。病毒无独立代谢与能量转化系统，须依赖宿主。"]}],"fill":[{"q":"1． 本单位。","a":"有机体构成；代谢与功能；生长与发育；遗传","src":"章节题库","oe":["有机体构成：细胞是构成有机体形态结构的基本单位。","代谢与功能：细胞是进行物质代谢和功能活动的基本单位。","生长与发育：细胞是生物体生长与发育的基本单位。","遗传：细胞是遗传的基本单位，是基因复制与传递的载体。"]},{"q":"2． ______，原生质指的是______。","a":"质膜；含有细胞核的一团原生质；细胞内除核以外的生活物质；生活细胞中所有的 生活物质","src":"章节题库","oe":["质膜：细胞膜又称质膜，是包围在细胞质外表面的一层薄膜。","原生质：指生活细胞中所有的生活物质；含核的一团原生质称原生质体。"]},{"q":"3． ______以及______等，是一个细胞生存与增殖所必备的。","a":"支原体；细胞膜；DNA 或 RNA；一定数量的核糖体；酶促反应的酶","src":"章节题库","oe":["支原体：支原体是能独立生存的最小细胞，常作为最小细胞的例证。","细胞膜、DNA或RNA及核糖体、酶等：是细胞生存与增殖必备的基本结构。"]},{"q":"4．","a":"中膜体；荚膜；鞭毛","src":"章节题库"},{"q":"5．","a":"氨基糖与壁酸；纤维素与果胶","src":"章节题库"},{"q":"6．","a":"细胞壁成分；DNA 与基因结构；核小体结构；核糖体；5S rRNA","src":"章节题库"},{"q":"7．","a":"圆球体；糊粉粒","src":"章节题库"},{"q":"8．","a":"细胞壁；液泡；叶绿体","src":"章节题库"},{"q":"9． 还有______体系。","a":"脂质构成的磷脂双分子层并镶嵌蛋白的生物膜；核酸和蛋白质分子构成的遗传信息的复制与 表达；骨架","src":"章节题库","oe":["此处指细胞骨架体系；细胞基本结构体系含生物膜、遗传信息复制表达和细胞骨架三大体系。"]},{"q":"10．","a":"遗传信息量少；细胞内无膜性细胞器及核膜","src":"章节题库"},{"q":"11． ④______。","a":"都有 DNA；都有核糖体；都是分裂法增殖；都有细胞质膜","src":"章节题库","oe":["④都有细胞质膜；二者共同点还包括都有DNA、核糖体，均以分裂法增殖。"]},{"q":"12．","a":"细胞的核质比；细胞的相对表面积；细胞内物质的交流","src":"章节题库"},{"q":"13．","a":"核酸；蛋白壳体；包膜","src":"章节题库"},{"q":"14． 为______、______及______。","a":"双链 DNA 病毒；单链 DNA 病毒；双链 RNA 病毒；单链 RNA 病毒；侵染性 RNA 病毒； 非侵染性 RNA 病毒；带有逆转录酶的单链 RNA 病毒即肿瘤病毒","src":"章节题库","oe":["第1空：DNA病毒，包括双链DNA病毒和单链DNA病毒。","第2空：RNA病毒，包括双链、单链、侵染性及非侵染性RNA病毒。","第3空：带有逆转录酶的单链RNA病毒，即肿瘤病毒（逆转录病毒）。"]},{"q":"1． 和_________。","a":"细胞衰老；细胞死亡","src":"名校考研真题","oe":["此处指细胞衰老和细胞死亡；它们是细胞生命活动的归宿与终结。"]},{"q":"2．","a":"细胞膜内陷；起 DNA 复制的支点作用","src":"名校考研真题"}],"judge":[{"q":"1．","a":"错","src":"章节题库"},{"q":"2．","a":"错","src":"章节题库"},{"q":"3．","a":"错","src":"章节题库"},{"q":"4．","a":"错","src":"章节题库"},{"q":"5．","a":"错","src":"章节题库"},{"q":"6．","a":"错","src":"章节题库"},{"q":"7．","a":"错","src":"章节题库"},{"q":"8．","a":"错","src":"章节题库"},{"q":"9．","a":"错","src":"章节题库"},{"q":"10． 本的区别。（     ）","a":"错","src":"章节题库","oe":["选“对”：若题干把二者根本区别归于细胞壁、大小等非本质特征，则不能成立。","选“错”：原核与真核细胞的根本区别是有无核膜包被的细胞核，题干说法有误。"]},{"q":"1． 呼吸作用，具有内质网的分泌作用，具有核膜的保护遗传物质的作用。（                      ）","a":"错","src":"名校考研真题","oe":["选“对”：该说法把线粒体、内质网和核膜等真核结构误归于原核细胞，故不成立。","选“错”：原核细胞无线粒体、内质网和核膜，呼吸作用靠细胞膜，故题干错误。"]},{"q":"2． 研]","a":"对","src":"名校考研真题"},{"q":"4． 科院-中科大 2005 研]","a":"对","src":"名校考研真题","oe":["选“对”：该命题符合教材的基本结论，按题源答案应判为正确。","选“错”：若否定该命题，则与细胞生物学的基本事实不符，故不选错。"]}]},"ch03":{"mcq":[{"q":"在光学显微镜样品制备试剂中，能特异显示 DNA 所在部位的试剂是（   ）。","o":["A．伊红","B．美蓝","C．品红","D．醋酸铀"],"a":"C","e":"AB 两项，伊红与美蓝能与特殊的蛋白质结合而使蛋白质显色。D 项，醋酸铀是重 金属物质，主要用于电镜样品的制备，易染核酸。C 项，光镜下品红能特异地显示 DNA 所 在部位。","src":"章节题库","oe":["错误。伊红主要使细胞质等蛋白质成分染成粉红色，不能特异显示DNA。","错误。美蓝使蛋白质等成分染成蓝色，不能特异显示DNA。","正确。品红（福尔根反应用的Schiff试剂）可在光镜下特异显示DNA。","错误。醋酸铀是电镜用重金属染色剂，用于光镜显示DNA不合适。"]},{"q":"观察 GFP 融合蛋白在活体细胞生长过程中的动态变化，采用哪种显微镜技术最佳（ ）。","o":["A．透射电镜","B．激光共聚焦显微技术","C．普通光学显微镜","D．扫描电镜"],"a":"B","e":"AD 两项，透射电镜和扫描电镜不能观察活体细胞。C 项，普通复式光学显微镜不 能观察荧光。","src":"章节题库","oe":["错误。透射电镜样品需固定脱水、真空观察，不能观察活细胞。","正确。激光共聚焦显微技术可对活细胞进行荧光观察并断层成像。","错误。普通光学显微镜不能有效观察荧光，需用荧光显微镜。","错误。扫描电镜样品需固定、脱水、喷镀且在真空中观察，不能观察活细胞。"]},{"q":"关于相差显微镜，下列说法错误的是（        ）。","o":["A．基本原理是以样品密度差别为基础，将光程差转换成振幅差，形成明暗区别","B．样品不需要染色","C．可以观察活细胞","D．可以对细胞的生物大分子进行定位和定性分析"],"a":"D","e":"相差显微镜不能观察到大分子物质的动态变化。","src":"章节题库","oe":["正确。相差显微镜以样品密度差形成光程差，再转为振幅差形成明暗。","正确。相差显微镜利用光程差成像，样品无需染色。","正确。相差显微镜可用于观察未染色的活细胞。","错误。相差显微镜不能对生物大分子定位定性，故选D。"]},{"q":"关于荧光共振能量转移技术，下列说法错误的是（         ）。","o":["A．供体发射的荧光与受体发色团分子的吸收光谱重叠","B．两个探针的距离在 10 nm 范围以内时，产生 FRET 现象","C．可用于检测活细胞内两个蛋白分子之间的相互作用","D．两个分子距离越近，供体所发出的荧光就被受体吸收的量越多，检测器所接收到的荧光 也相应越多"],"a":"D","e":"两个分子距离越近，供体所发出的荧光被受体吸收的量越多，检测器所接收到的供 体荧光也就相应越少。其他选项均正确。","src":"章节题库","oe":["正确。FRET要求供体发射光谱与受体吸收光谱相重叠。","正确。两探针距离在约10nm以内时才可发生FRET。","正确。FRET可用于检测活细胞内两个蛋白分子的相互作用。","错误。距离越近受体吸收供体荧光越多，检测到的供体荧光越少，故选D。"]},{"q":"从电镜来看，下列各项中（        ）是不正确的。","o":["A．电镜用的是电子束，而不是可见光","B．电镜样品要在真空中观察，而不是暴露在空气中的","C．电镜和光镜的样品都需要用化学染料染色","D．用于电镜的标本要彻底脱水，光镜则不必"],"a":"C","e":"电镜需要重金属染色。","src":"章节题库","oe":["正确。电镜以电子束代替可见光作为照明源。","正确。电镜需在真空条件下观察，样品不能暴露于空气。","错误。电镜用重金属染色，光镜才用化学染料，故选C。","正确。电镜样品须彻底脱水，光镜含水的样品也可观察。"]},{"q":"电镜制样需要经过许多步骤，对这些步骤的解释错误的是（   ）。","o":["A．电子束的穿透能力有限，因而要求样品很薄，一般是数十纳米","B．包埋过程会破坏样品的结构，所以超薄切片样品制备的第一步是固定","C．包埋剂多是水不相溶的，因此在包埋前通常要经过脱水处理","D．对样品经过染色后，通过改变电磁波的波长而获得彩色图像"],"a":"D","e":"电镜样品仅用重金属盐进行染色以形成明暗反差，因此只能通过电子束振幅的改变 观察到黑白图像。它不能像光镜切片染色那样通过改变波长而获得彩色图像。","src":"章节题库","oe":["正确。电子束穿透力有限，要求样品很薄，一般仅数十纳米。","正确。包埋会破坏结构，故超薄切片制备的第一步是固定。","正确。包埋剂多与水不相溶，包埋前通常需脱水处理。","错误。电镜只经重金属染色形成黑白反差，不能改变波长获得彩色图像，故选D。"]},{"q":"分析难以形成三维晶体的膜蛋白和蛋白质-核酸复合物等大分子复合体的技术是（   ）。","o":["A．负染色技术","B．冷冻蚀刻技术","C．电镜三维重构技术","D．扫描隧道显微镜技术"],"a":"A","e":"该技术将电子显微技术、电子衍射技术和计算机图像处理技术结合起来，从而可以 展现出生物大分子及其复合物三维结构的电子密度图。","src":"章节题库","oe":["题源选A；但负染色只用于衬托颗粒轮廓，并不能给出三维电子密度图。","B：冷冻蚀刻用于观察膜断裂面，不涉及电子衍射与三维重构。","C：将电镜、电子衍射与计算机图像处理结合给出三维电子密度图的应是电镜三维重构技术。","D：扫描隧道显微镜靠隧道电流成像，用于表面原子级形貌观察。"]},{"q":"8． （   ）","o":["A．冰冻断裂显微镜","B．共聚焦扫描术","C．光学显微镜","D．扫描电子显微术"],"a":"B","e":"共聚焦扫描术其特点是：（1）物镜和聚光镜互相共焦点（即两者同时聚焦到一个 点），使得只有从标本焦面发出的光线聚焦成像，而焦面以外的漫射光不参加成像；（2） 以单色激光作为点光源并聚焦到标本焦平面上进行光点扫描，最后在荧光屏上清晰成像； （3） 改变焦平面，可获得细胞或原标本不同层次的图像，从而得到样品的三维图像。","src":"章节题库","oe":["错误。冰冻断裂（冷冻蚀刻）用于观察膜断裂面，不产生三维光学图像。","正确。共聚焦扫描术以激光逐点扫描、改变焦平面，可获得三维图像。","错误。普通光学显微镜分辨率与景深有限，不能获得三维重建图像。","错误。扫描电镜观察表面立体形貌，但需固定脱水，非此光学断层成像。"]},{"q":"扫描电子显微镜主要用于（   ）。","o":["A．获得细胞不同切面的图像","B．观察活细胞","C．定量分析细胞中的化学成分","D．观察细胞表面的立体形貌"],"a":"D","e":"A 项，获得细胞不同切面的图像——激光共焦点扫描显微镜；B 项，观察活细胞 ——相差显微镜；C 项，定量分析细胞中的化学成分——显微分光光度计以及流式细胞仪等； D 项，观察细胞表面的立体形貌——扫描电镜。","src":"章节题库","oe":["错误。获得细胞不同切面图像的是激光共聚焦扫描显微镜。","错误。观察活细胞常用相差显微镜、微分干涉显微镜等。","错误。定量分析化学成分常用显微分光光度计、流式细胞仪等。","正确。扫描电镜可观察细胞表面的立体形貌。"]},{"q":"以下关于激光扫描共焦显微镜的叙述，错误的是（   ）。","o":["A．共焦点是指物镜和聚光镜同时聚焦到一个小点","B．可以自动改变观察的焦平面而且纵向分辨率得到改善","C．可以通过光学切片观察样品的内部结构，并可重构三维图像","D．相比普通荧光显微镜分辨率提高 50 倍"],"a":"D","e":"激光扫描共聚焦显微镜的分辨率比普通荧光显微镜分辨率提高 1.4-1.7 倍。","src":"章节题库","oe":["正确。共焦点即物镜与聚光镜同时聚焦到同一个小点。","正确。共聚焦可自动改变焦平面并改善纵向分辨率。","正确。共聚焦可行光学切片观察内部结构并重构三维图像。","错误。共聚焦分辨率约比普通荧光显微镜提高1.4～1.7倍，非50倍，故选D。"]},{"q":"能特异显示 DNA 分布的方法是（             ）。","o":["A．PAS 反应","B．米伦反应","C．福尔根反应","D．格莫瑞方法"],"a":"C","e":"A 项，PAS 反应用于确定多糖的存在。B 项，米伦反应四蛋白质成分的检测方法。 C 项，福尔根反应可以特异的显示 DNA 的分布。D 项，格莫瑞方法用于检测碱性磷酸酶。","src":"章节题库","oe":["错误。PAS反应用于显示多糖（糖类）的存在。","错误。米伦反应用于检测含酪氨酸的蛋白质。","正确。福尔根反应可特异性显示DNA的分布。","错误。格莫瑞方法用于显示碱性磷酸酶。"]},{"q":"为使细胞分拆为核体和胞质体，可选用下列哪种试剂处理胞（                 ）。","o":["A．灰霉素","B．啶黄素","C．两性霉素","D．细胞松弛素"],"a":"D","e":"细胞分拆有物理法和化学法，物理法主要包括用显微操作仪对细胞核和细胞质进行 拆分和重构，化学法主要用细胞松弛素 B 处理细胞，细胞会出现排核现象。","src":"章节题库","oe":["错误。灰霉素为抗生素，不用于细胞拆合与排核。","错误。啶黄素为核酸染料/抗菌剂，不用于细胞排核。","错误。两性霉素为抗真菌药物，不用于细胞拆合。","正确。细胞松弛素B处理细胞可致排核，是细胞拆合的化学法试剂。"]},{"q":"下列不属于细胞系的特点的是（               ）。","o":["A．无限分裂","B．染色体数维持正常水平","C．染色体出现畸变","D．失去接触抑制"],"a":"B","e":"一般当细胞株传至 50 代后又不能再传下去。如有部分细胞发生了遗传突变，并带 有癌细胞的特点，可能在培养条件下无限制地传下去，这种传代细胞称为细胞系。细胞系细 胞的根本特点是染色体明显改变，一般呈亚二倍体或非整倍体，失去接触抑制的细胞，容易 传代培养。","src":"章节题库","oe":["非答案。细胞系具有无限分裂能力，可长期传代。","错误。细胞系染色体多明显改变，呈亚二倍体或非整倍体，故选B。","非答案。细胞系染色体常出现畸变，属其特点。","非答案。细胞系常失去接触抑制，易于传代培养。"]},{"q":"将染色体上基因定位的研究手段应为（                ）。","o":["A．PCR","B．Southern blot","C．Western blot","D．insitu hybridization"],"a":"D","e":"A 项，PCR 是基因体外扩增技术。BC 两项，Southern blot 即 DNA 印迹杂交，Northern blot 即 RNA 印迹杂交，两者都是一种检测已固定在滤膜上的总 DNA、RNA 或 mRNA 特定 靶序列的技术。D 项，in situ hybridization 即原位杂交技术。","src":"章节题库","oe":["错误。PCR为基因体外扩增技术，不能在细胞原位定位。","错误。Southern blot为DNA印迹杂交，检测膜上DNA，非原位。","错误。Western blot为蛋白质印迹，检测蛋白质而非核酸定位。","正确。insitu hybridization即原位杂交，可在细胞原位显示核酸序列。"]},{"q":"有关免疫荧光与免疫电镜，下列说法错误的选项是（                ）。","o":["A．两者是最常用的研究细胞内蛋白质分子定位的重要技术","B．两者也是对蛋白质进行体外定性分析最常用的技术","C．两者最关键的问题都是保持样品中蛋白质的抗原性","D．在进行实验室，都应当设立严格的对照，以检验结果的可靠性"],"a":"B","e":"对蛋白质进行体外定性分析通常采用免疫印迹和放射免疫沉淀等技术。","src":"章节题库","oe":["正确。二者是研究细胞内蛋白质分子定位的常用技术。","错误。蛋白质体外定性分析常用免疫印迹和放射免疫沉淀，故选B。","正确。二者最关键的问题都是保持样品中蛋白质的抗原性。","正确。实验均须设立严格对照以检验结果的可靠性。"]},{"q":"有关原位杂交技术，下列说法错误的是（                ）。","o":["A．被标记的“探针”，在该项技术中必不可少","B．放射性同位素标记的探针与样品中的 DNA 或 RNA 杂交后，用显微放射自显影技术显示","C．荧光素标记的探针与样品中的 DNA 或 RNA 杂交后，在荧光显微镜下直接显示","D．在电镜水平，探针可以不被标记，直接在电镜下观察杂交物的存在即可"],"a":"D","e":"原位杂交在电镜水平上与免疫胶体金技术结合，探针可用生物小分子标记，而代替 光镜水平上用同位素或荧光素标记探针。若不被标记，不能确定定位杂交物的存在。","src":"章节题库","oe":["正确。标记的探针在原位杂交中必不可少。","正确。放射性同位素标记探针杂交后可用放射自显影显示。","正确。荧光素标记探针杂交后可在荧光显微镜下直接显示。","错误。电镜水平探针也须标记，不标记无法确定杂交物位置，故选D。"]},{"q":"有关细胞周期调控的知识最初来源于对（         ）的研究。","o":["A．细菌","B．酵母","C．线虫","D．小鼠"],"a":"B","e":"芽殖酵母是研究 G1／S 期转换的好材料，裂殖酵母是研究 G2／M 期转换的理想材 料。20 世纪 60 年代，酵母遗传学家利用温度敏感突变技术筛选并分析了 200 多个与细胞分 裂及周期调控相关的基因。","src":"章节题库","oe":["错误。细菌为原核生物，不具备真核细胞周期调控的研究优势。","正确。酵母是研究细胞周期调控的经典模式生物。","错误。线虫主要用作发育与细胞凋亡研究的模式生物。","错误。小鼠为哺乳动物，成本高，非细胞周期研究的经典材料。"]},{"q":"1． 学 2011 研]","o":["A．氨基酸","B．核酸","C．生长因子","D．维生素"],"a":"C","e":"血清中含有促细胞分裂因子，以及有利于贴壁生长的黏附分子。","src":"名校考研真题","oe":["错误。氨基酸是基础营养成分，可由合成培养基提供。","错误。核酸通常不是培养液中需添加的营养成分。","正确。血清含促细胞分裂的生长因子及利于贴壁的黏附分子。","错误。维生素是培养基成分，但非血清促进细胞生长的关键。"]},{"q":"3． 南开大学 2011 研]","o":["A．细胞融合","B．核移植","C．病毒转化","D．基因转移"],"a":"A","e":"杂交瘤细胞是利用瘤细胞与特异性抗原免疫的 B 淋巴细胞进行细胞融合制得的。","src":"名校考研真题","oe":["正确。杂交瘤细胞由骨髓瘤细胞与免疫B淋巴细胞经细胞融合制得。","错误。核移植用于克隆动物等，与杂交瘤制备无关。","错误。病毒转化指病毒使细胞恶性转化，非杂交瘤制备方法。","错误。基因转移指导入外源基因，非杂交瘤制备方法。"]}],"fill":[{"q":"1． 电子显微镜可以达到______。","a":"区分两个质点间的最小距离；0.2mm；0.2μm；0.2nm","src":"章节题库","oe":["为0.2nm；分辨本领是区分两质点间的最小距离，光镜约0.2μm，电镜可达0.2nm。"]},{"q":"2．","a":"透射电镜；扫描电镜","src":"章节题库"},{"q":"3．","a":"固定；脱水；包埋；切片；染色","src":"章节题库"},{"q":"4． 性分析通常采用______和______等技术。","a":"免疫荧光；免疫电镜；免疫印迹；放射免疫沉淀","src":"章节题库","oe":["免疫印迹：用于蛋白质的体外定性（及半定量）分析。","放射免疫沉淀：同样用于蛋白质的体外定性分析。"]},{"q":"5．","a":"化学合成法；限制性内切酶核酸酶酶切法；聚合酶链反应","src":"章节题库"},{"q":"6．","a":"相差或微分干涉显微镜","src":"章节题库"},{"q":"7． 分拆为______和胞质体两部分，然后在 PEG 或仙台病毒的介导下，核体可同另一______融 合，形成重组细胞。","a":"细胞松弛素 B；排核；核体；胞质体","src":"章节题库","oe":["核体：用细胞松弛素B处理并排核后，细胞被拆分为核体与胞质体两部分。","胞质体：核体在PEG或仙台病毒介导下与另一胞质体融合形成重组细胞。"]},{"q":"8．","a":"超速离心法；层析法；电泳法","src":"章节题库"},{"q":"9． ______，亦用于细胞核的解剖和向核内注入。","a":"显微操作装置；核移植基因","src":"章节题库","oe":["显微操作装置可在显微镜下对细胞进行解剖和微量注射，亦用于核移植和向核内注入。"]},{"q":"10．","a":"光脱色恢复技术","src":"章节题库"},{"q":"11． 血红素等经紫外线照射后，能发出红色的荧光；第二种是______，即物体经荧光染料染色后 再通过紫外线照射发出荧光。","a":"自发荧光；激发荧光","src":"章节题库","oe":["物质经紫外线照射发荧光分自发荧光和激发荧光，本题空格指经荧光染料染色后再激发的荧光。"]},{"q":"12．","a":"显微分光光度分析；流式细胞仪；相差显微镜","src":"章节题库"},{"q":"13． 弱的部位______断裂，从而显示出镶嵌在膜脂中的______。","a":"膜脂双分子层的疏水端；蛋白质颗粒","src":"章节题库","oe":["冷冻断裂时膜脂双分子层的疏水端结合最弱，故样品多由此处断裂。","断裂后即显示出镶嵌在膜脂双分子层中的蛋白质颗粒。"]},{"q":"14． 手段。","a":"电镜三维重构技术；结构生物学","src":"章节题库"},{"q":"15．","a":"固定；脱水；干燥；镀膜","src":"章节题库"},{"q":"16． 良好的表面导电性，样品在观察前还需要______。","a":"样品的表面形貌；CO2 临界点干燥法；喷镀一层金膜","src":"章节题库","oe":["扫描电镜观察前需喷镀一层金膜，以获得良好的表面导电性、防止样品充电。"]},{"q":"17． 并带有一个合轴用的望远镜。","a":"环状光阑；带相差板的物镜","src":"章节题库","oe":["相差显微镜用环状光阑代替普通可变光阑，以获得环形照明光束。","用带相差板的物镜代替普通物镜，与环状光阑配合形成相位差。"]},{"q":"18．","a":"单层生长；形态变成多态性；具有接触抑制现象","src":"章节题库"},{"q":"19． ______荧光。","a":"绿色；红色","src":"章节题库","oe":["吖啶橙染色后DNA发绿色荧光、RNA发红色荧光，故本题答案涉及绿、红两色。"]},{"q":"1． 体中上述成分含量不同的细胞数量。","a":"DNA；RNA","src":"名校考研真题","oe":["流式细胞仪可定量测定细胞中的DNA含量，以及群体中含量不同的细胞数量。","第二空为RNA，流式细胞术也可测定RNA或某种特异蛋白的含量。"]},{"q":"2． 创新。","a":"切片技术；光学显微技术","src":"名校考研真题"},{"q":"3． 可以分为两种基本形态：_______与_______。","a":"成纤维样细胞；上皮样细胞","src":"名校考研真题","oe":["体外培养细胞可分为成纤维样细胞，多呈梭形或不规则形贴壁生长。","另一类为上皮样细胞，呈扁平多边形且彼此紧密相连成片。"]}],"judge":[{"q":"1．","a":"对","src":"章节题库"},{"q":"2． （     ）","a":"错","src":"章节题库"},{"q":"3．","a":"错","src":"章节题库"},{"q":"4． 行，所有的实验器械和试剂都是以相同的方式消毒灭菌。（          ）","a":"错","src":"章节题库","oe":["选“对”：若认为所有器械与试剂可用同一种方式消毒灭菌，则不成立。","选“错”：器械常用高压蒸汽灭菌，试剂需过滤除菌或紫外等，方式不同。"]},{"q":"5． 修饰变成植物的遗传修饰，从而改变整个植物的遗传特性。（   ）","a":"错","src":"章节题库","oe":["选“对”：若认为修饰单个细胞即可改变整株植物的遗传特性，则错误。","选“错”：被修饰的细胞须经组织培养再生为完整植株才形成转基因植物。"]},{"q":"6． 核酸。（   ）","a":"错","src":"章节题库"},{"q":"7． 自溶作用造成破坏。（         ）","a":"错","src":"章节题库","oe":["选“对”：该说法把损伤归于自溶作用，混淆了破坏的主要原因。","选“错”：冻存损伤主要源于冰晶形成与渗透压改变，而非自溶作用。"]},{"q":"8．","a":"错","src":"章节题库"},{"q":"2． 的极限基本相同。（        ）","a":"对","src":"名校考研真题","oe":["选“对”：符合细胞体积守恒定律，不同物种同类细胞的体积极限基本相同。","选“错”：若否定则违背同类细胞大小倾向恒定这一基本规律。"]},{"q":"4． （    ）","a":"错","src":"名校考研真题"},{"q":"5．","a":"对","src":"名校考研真题"},{"q":"6． 保留下来的细胞，可以是正常细胞与肿瘤细胞的单克隆融合细胞，还可以是多克隆杂交的细 胞的混合群体，但不可能是未融合的肿瘤细胞或正常细胞之间的混合体。（                      ）","a":"对","src":"名校考研真题","oe":["选“对”：选择培养基淘汰未融合细胞，存活的为融合细胞（单克隆或多克隆）。","选“错”：若认为未融合的正常细胞或肿瘤细胞也能存活，则不成立。"]}]},"ch04":{"mcq":[{"q":"下述有关细胞质膜结构模型的说法错误的是（                  ）。","o":["A．光学显微镜发现细胞后，人们并未同时观察到细胞质膜，直到电镜下显示出质膜的超微 结构，人们才证明了质膜的存在","B．用有机溶剂抽提人红细胞质膜的膜脂成分，并测定膜脂单层分子在水面的铺展面积，发 现它为红细胞表面积的两倍，提示质膜是由双层分子组成","C．三明治模型和单位膜模型得到了 X 射线衍射分析与电镜观察结果的支持","D．细胞膜结构模型都有相关的实验证据支持，但都不够完善、充实"],"a":"A","e":"20 世纪初，对细胞内渗透压的研究已经证明质膜的存在。","src":"章节题库","oe":["错误：20世纪初对细胞内渗透压的研究已证明质膜存在，并非电镜才证实。","正确：Gorter测膜脂单层铺展面积为红细胞表面积两倍，支持脂双层。","正确：三明治模型、单位膜模型曾获X射线衍射与电镜观察结果的支持。","正确：各细胞膜结构模型都有实验依据但均不完善，此说法无误。"]},{"q":"膜脂最基本的热运动方式是（               ）。","o":["A．沿膜平面的侧向运动","B．脂分子围绕轴心的自旋运动","C．脂分子尾部的摆动","D．双层脂分子之间的翻转运动"],"a":"A","e":"膜脂最基本的热运动方式是沿膜平面的侧向运动，这种方式的运动是完成多种生理 功能所必需的，因此具有重要的生物学意义。","src":"章节题库","oe":["正确：沿膜平面的侧向运动是膜脂最基本、最重要的热运动方式。","错误：自旋运动虽存在，但不是膜脂最基本的热运动方式。","错误：尾部摆动幅度小且局限于局部，非最基本热运动方式。","错误：翻转运动极少发生且需酶催化，不是基本热运动方式。"]},{"q":"3． 性肽段，其中 7 段各含 25 个氨基酸残基，3 段各含 16 个氨基酸残基，4 段各含 10 个氨基酸 残基。经过上述分析可知，此肽链最有可能形（                  ）个α螺旋。","o":["A．14 个","B．11 个","C．10 个","D．7 个"],"a":"D","e":"α螺旋跨膜结构域含有 20～30 个氨基酸残基。","src":"章节题库","oe":["错误：14个把全部疏水段计入，但16、10残基段不足以跨膜成螺旋。","错误：11个把16残基段也计入，跨膜α螺旋一般需20~30个残基。","错误：10个把含10残基的4段计入，同样不满足跨膜螺旋长度。","正确：仅7段25残基符合跨膜α螺旋长度，故最可能形成7个α螺旋。"]},{"q":"有关膜蛋白的流动性，下列哪项说法错误的是（      ）。","o":["A．用药物抑制细胞能量的转换，膜蛋白的扩散速率下降","B．降低温度，膜蛋白的扩散速率显著下降","C．膜蛋白在脂双层二维溶液中的运动是自发的热运动","D．用阻断微丝形成的药物细胞松弛素 B 处理细胞后，膜蛋白的流动性大大增加"],"a":"A","e":"膜蛋白的运动是自发的热运动，不需细胞代谢产物的参加，也不需要提供能量。用 药物抑制细胞的能量转换，对膜蛋的运动没有影响。","src":"章节题库","oe":["错误：膜蛋白扩散是自发热运动，抑制细胞能量转换不影响其扩散速率。","正确：降温使膜脂黏度增大，膜蛋白的扩散速率显著下降。","正确：膜蛋白在脂双层二维溶液中的运动属自发的热运动。","正确：细胞松弛素B破坏微丝束缚后，膜蛋白流动性增加。"]},{"q":"有关膜的不对称性，下列说法错误的是（     ）。","o":["A．无论是膜内在蛋白还是膜外在蛋白，在质膜上都呈不对称分布","B．膜蛋白的不对称性是指每种膜蛋白分子在细胞膜上都具有明确的方向性","C．膜蛋白和糖类在细胞内外层是不对称分布的，但膜脂是对称分布的","D．膜蛋白的不对称性是生物膜完成复杂的各种生理功能的保证"],"a":"C","e":"膜脂分子呈不对称分布，膜脂的不对称性是指同一种膜脂分子在膜的脂双层中呈不 均匀分布。","src":"章节题库","oe":["正确：无论膜内在蛋白还是膜外在蛋白，在质膜上均呈不对称分布。","正确：膜蛋白不对称性指每种膜蛋白分子在膜上具有明确方向性。","错误：膜脂在脂双层中同样呈不对称分布，并非对称分布。","正确：膜蛋白的不对称性是生物膜完成复杂生理功能的保证。"]},{"q":"下列蛋白质中，（      ）是跨膜蛋白。","o":["A．血影蛋白","B．带 4.1 蛋白","C．锚定蛋白","D．血型糖蛋白"],"a":"D","e":"锚定蛋白是一种比较大的细胞内连接蛋白，带 3 蛋白与血型糖蛋白一样都是红细胞 的膜蛋白是一种糖蛋白，因此，它是多次跨膜蛋白。","src":"章节题库","oe":["错误：血影蛋白是膜骨架外周蛋白，不属于跨膜蛋白。","错误：带4.1蛋白是膜骨架连接蛋白，不跨膜。","错误：锚定蛋白是膜骨架中的连接蛋白，不属跨膜蛋白。","正确：血型糖蛋白是红细胞膜的跨膜糖蛋白，为多次跨膜蛋白。"]},{"q":"血影蛋白（      ）。","o":["A．是红细胞质摸的结构蛋白","B．能传递阴离子","C．穿膜 12～14 次","D．是支撑红细胞质摸的膜骨架结构"],"a":"D","e":"血影蛋白在整个细胞膜的细胞质面下面形成可变形的网架结构，以维持红细胞的双 凹圆盘形状。","src":"章节题库","oe":["错误：血影蛋白属膜骨架外周蛋白，不是质膜的结构（内在）蛋白。","错误：能传递阴离子的是带3蛋白，而非血影蛋白。","错误：穿膜12~14次的是带3蛋白，血影蛋白并不跨膜。","正确：血影蛋白在胞质侧形成网架，支撑质膜并维持双凹圆盘形。"]},{"q":"1． 江师范大学 2011 研]","o":["A．膜脂的流动性","B．膜蛋白的流动性","C．膜脂的不对称性","D．膜蛋白的不对称"],"a":"B","e":"免疫荧光标记技术主要对蛋白质进行标记。在某些细胞如血液白细胞中，当荧光抗 体标记时间继续延长，已均匀分布在细胞表面的标记荧光会重新排布，聚集在细胞表面的某 些部位，即成斑现象，或聚集在细胞的一端，即成帽现象。成斑现象和成帽现象进一步证实 了膜蛋白的流动性。","src":"名校考研真题","oe":["错误：成斑成帽反映膜蛋白聚集，说明的是膜蛋白而非膜脂流动性。","正确：荧光抗体标记出现成斑成帽，证明膜蛋白能在膜平面流动聚集。","错误：该现象与膜脂不对称性无关，不反映脂双层的分布。","错误：成斑成帽体现膜蛋白的流动性，而非膜蛋白的不对称性。"]},{"q":"2． 下列推导错误的是（          ）。","o":["A．用去污剂 Triton X-100 处理后，血影脂质结构完整，因而血影维持原来形状","B．对维持细胞形态并不起决定作用","C．带 3 蛋白及血型糖蛋白是膜内在蛋白","D．带 3 蛋白及血型糖蛋白肯定存在跨膜结构域"],"a":"A","e":"用 Triton X-100 处理后可使细胞膜崩解，但对蛋白的作用比较温和，即血影脂质结 构被破坏。","src":"名校考研真题","oe":["错误：Triton X-100会溶解膜脂，血影脂质结构被破坏而崩解。","正确：膜脂对维持细胞形态不起决定作用，膜骨架才起主要作用。","正确：带3蛋白与血型糖蛋白均为红细胞膜内在蛋白。","正确：作为膜内在蛋白，二者必含跨膜结构域。"]},{"q":"不能用于研究膜蛋白流动性的方法是（              ）。[南京师范大学 2007 研]","o":["A．荧光抗体免疫标记","B．荧光能量共振转移","C．光脱色荧光恢复","D．荧光标记细胞融合"],"a":"B","e":"荧光能量共振转移（FRET）用于检测体内两种蛋白质之间是否存在直接的相互作 用。","src":"名校考研真题","oe":["错误：荧光抗体免疫标记可用于研究膜蛋白的流动性。","正确：荧光能量共振转移用于检测蛋白质间相互作用，不测流动性。","错误：光脱色荧光恢复是研究膜流动性的基本实验技术。","错误：荧光标记细胞融合可证明膜蛋白的侧向扩散流动性。"]},{"q":"4． 于下列哪一种膜？（          ）","o":["A．线粒体内膜","B．髓鞘质","C．红血细胞","D．以上都有可能"],"a":"B","e":"A 项，线粒体内膜上存在质子泵参与呼吸链的电子传递。C 项，红血细胞膜上存在 钠钾泵参与物质运输。","src":"名校考研真题","oe":["错误：线粒体内膜有质子泵参与呼吸链电子传递，并非无泵。","正确：髓鞘质以脂质为主、蛋白极少，表面几乎无孔和泵。","错误：红细胞膜上有钠钾泵参与物质运输。","错误：A、C均有转运蛋白，并非以上都可能，只有髓鞘质符合。"]}],"fill":[{"q":"1．","a":"膜的流动性；膜的不对称性","src":"章节题库"},{"q":"2． 基。","a":"脑苷脂","src":"章节题库"},{"q":"3． 页，而磷脂酰丝氨酸则主要分布在______页。","a":"质膜内小；质膜外小","src":"章节题库","oe":["红细胞质膜中磷脂酰乙醇胺主要分布在内小页，磷脂酰丝氨酸主要分布在外小页。"]},{"q":"4． 蛋白的共同特征。","a":"α螺旋","src":"章节题库","oe":["跨膜结构域含较多疏水氨基酸残基的内在膜蛋白，其二级结构多为α螺旋。"]},{"q":"5． 连接。","a":"运输；识别；酶活性；细胞连接；信号转导","src":"章节题库"},{"q":"6．","a":"糖脂","src":"章节题库"},{"q":"7． 较 O 型多一个______，B 型较 O 型仅多一个______。","a":"乙酰半乳糖胺残基；半乳糖残基。","src":"章节题库","oe":["A型血物质较O型多一个N-乙酰半乳糖胺残基，因而血型不同。","B型较O型仅多一个半乳糖残基，差异在寡糖链末端糖基。"]},{"q":"8．","a":"人、鼠细胞融合实验；抗体诱导的成帽或成斑反应；光漂白恢复技术。","src":"章节题库"},{"q":"9． 的某一个部位称为______，聚集在细胞的一端称为______。","a":"成斑现象；成帽现象","src":"章节题库","oe":["荧光抗体标记后膜蛋白聚集在细胞表面某部位，称为成斑现象。","标记物进一步聚集于细胞一端则称成帽现象，二者证明膜蛋白流动性。"]},{"q":"10． 制样中产生的面称为______和______。","a":"细胞外表面；原生质表面；细胞外小页断裂面；原生质小页断裂面","src":"章节题库","oe":["冷冻蚀刻制样中沿疏水端劈裂，产生的面之一为细胞外小页断裂面。","另一面为原生质小页断裂面，二者均属冷冻断裂面。"]},{"q":"11．","a":"极性的头和非极性的尾；脂肪酸碳链为偶数（多为 16C 和 18C）；具有饱和、不 饱和脂肪酸根。","src":"章节题库"},{"q":"12． ______；在相变温度以下，______。","a":"可以限制膜的流动性；可以增加膜的流动性","src":"章节题库","oe":["在相变温度以上，胆固醇可限制膜脂运动、降低膜的流动性。","在相变温度以下，胆固醇又可阻止脂链紧密排列、增加膜流动性。"]},{"q":"1． 活在_________环境中的动物，其细胞质膜中不饱和脂肪酸的含量高于生活在_________环境 中动物细胞质膜中不饱和脂肪酸的含量。","a":"低温；高温","src":"名校考研真题","oe":["低温环境动物质膜不饱和脂肪酸含量较高，以维持低温下的膜流动性。","高温环境动物则不饱和脂肪酸较少、饱和脂肪酸较多，使膜更稳定。"]},{"q":"2． 实验证据是______。","a":"沿膜平面侧向运动；鼠和人的细胞膜蛋白的荧光抗体标记细胞表面的细胞融合实验","src":"名校考研真题","oe":["膜脂基本热运动是沿膜平面侧向运动，膜蛋白流动性的证据是人鼠细胞融合实验。"]},{"q":"3． 术是______。","a":"越短；越高；荧光漂白恢复技术","src":"名校考研真题","oe":["脂肪酸链越短、不饱和程度越高，膜脂流动性越大；测试技术为荧光漂白恢复技术。"]}],"judge":[{"q":"1．","a":"错","src":"章节题库"},{"q":"2．","a":"错","src":"章节题库"},{"q":"3． （     ）","a":"对","src":"章节题库"},{"q":"4．","a":"错","src":"章节题库"},{"q":"5．","a":"错","src":"章节题库"},{"q":"6.","a":"错","src":"章节题库"},{"q":"7．","a":"错","src":"章节题库"}]},"ch05":{"mcq":[{"q":"人工脂双层膜对不同分子的相对通透性由大到小的排列是（      ）。","o":["A．H2O、葡萄糖、甘油、Na ＋","B．H2O、Na 、甘油、葡萄糖 ＋","C．H2O、尿素、葡萄糖、K ＋","D．H2O、甘油、K 、葡萄糖 ＋"],"a":"C","e":"人工脂双层膜对不同分子的相对通透性主要取决于分子的大小和极性。小分子比大 分子容易穿膜，非极性分子比极性分子容易穿膜，人工质双层对带电离子是高度不透的。","src":"章节题库","oe":["错误：甘油分子比葡萄糖小，应排在葡萄糖前，且Na+几乎不能通过。","错误：Na+带电，人工膜高度不透，不应排在甘油、葡萄糖之前。","正确：通透性由大到小为H2O、尿素、葡萄糖、K+，K+带电最难通过。","错误：K+带电不易透膜，不应排在葡萄糖之前。"]},{"q":"下列对协助扩散的描述，不正确的是（       ）。","o":["A．转运速率高，存在最大转运速率","B．需要膜转运蛋白的“协助”","C．对物质的转运是非特异性的","D．物质由高浓度侧向低浓度侧转运"],"a":"C","e":"比较不同分子的 KM 值，膜转运蛋白对物质的转运是特异性的。","src":"章节题库","oe":["正确：协助扩散转运速率高，且存在最大转运速率即饱和现象。","正确：协助扩散需要膜转运蛋白的协助，故又称易化扩散。","错误：膜转运蛋白对底物具有特异性，并非无特异性的转运。","正确：协助扩散顺浓度梯度，物质由高浓度侧向低浓度侧转运。"]},{"q":"下列哪种方式不消耗 ATP？（     ）","o":["A．胞吐作用","B．Na 门控通道 ＋","C．次级主动运输","D．Na -K 泵 ＋   ＋"],"a":"B","e":"主动运输消耗 ATP，被动运输不消耗 ATP；简单扩散和协助扩散是被动运输。ACD 三项，胞吐作用、次级主动运输、Na -K 泵均是主动运输。B 项，Na 门控通道是协助扩散， ＋  ＋                   ＋   不消耗 ATP。","src":"章节题库","oe":["错误：胞吐作用需要消耗ATP，属主动运输。","正确：Na+门控通道属协助扩散，顺电化学梯度，不直接消耗ATP。","错误：次级主动运输利用离子梯度，最终仍依赖ATP供能。","错误：Na+-K+泵直接水解ATP，是典型的主动运输。"]},{"q":"维持细胞内低钠高钾的蛋白分子是（         ）。","o":["A．Na -K 泵 ＋   ＋","B．Na 通道蛋白 ＋","C．K 通道蛋白 ＋","D．Na -K 通道蛋白 ＋   ＋"],"a":"A","e":"Na -K 泵每消耗一分子 ATP 泵出 3 个 Na 泵进 2 个 K ，从而维持了细胞内高钾低 ＋ ＋                  ＋        ＋   钠的细胞内环境。","src":"章节题库","oe":["正确：Na+-K+泵每水解1个ATP泵出3个Na+、泵入2个K+，维持胞内高钾低钠。","错误：Na+通道只顺梯度运输Na+，不能维持胞内高钾低钠。","错误：K+通道只顺梯度运输K+，不建立离子的浓度梯度。","错误：不存在Na+-K+通道蛋白，只有Na+-K+ ATP酶（泵）。"]},{"q":"小肠上皮吸收葡萄糖以及各种氨基酸时，主要通过（              ）达到逆浓度梯度运输。","o":["A．与 Na 相伴运输 ＋","B．与 K 相伴运输 ＋","C．与 Ca2 相伴运输 ＋","D．载体蛋白直接利用 ATP 能量"],"a":"A","e":"小肠上皮吸收葡萄糖以及各种氨基酸时，伴随着 Na 从细胞外流入细胞内，这种运 ＋   输方式称为共运输，属于协同运输方式。","src":"章节题库","oe":["正确：小肠吸收葡萄糖为共运输，伴随Na+顺梯度流入细胞提供动力。","错误：该过程与K+的相伴运输无关，属Na+驱动的协同运输。","错误：葡萄糖吸收不依赖Ca2+的相伴运输。","错误：载体蛋白间接利用Na+电化学梯度，而非直接利用ATP能量。"]},{"q":"下列哪种物质不参与胞饮泡的形成？（         ）","o":["A．网格蛋白","B．发动蛋白（dynamin）","C．接合素蛋白","D．微丝"],"a":"D","e":"微丝协助吞噬泡的形成。","src":"章节题库","oe":["错误：网格蛋白参与胞饮泡（有被小泡）的形成。","错误：发动蛋白负责有被小泡颈部的缢缩断裂，参与其形成。","错误：接合素蛋白参与有被小窝的形成，参与胞饮泡形成。","正确：微丝协助吞噬泡的形成，不参与胞饮泡的形成。"]},{"q":"细胞内铁的运输是通过（     ）。","o":["A．通道蛋白","B．吞饮作用","C．受体介导的内吞作用","D．自由扩散"],"a":"C","e":"鸟类卵细胞摄取卵黄蛋白，肝细胞摄入转铁蛋白，某些激素如胰岛素与靶细胞表面 受体结合进入细胞，巨噬细胞通过表面受体对免疫球蛋白及其复合物等的识别和摄入，以及 铁的摄取都是通过受体介导的胞吞作用进行的。","src":"章节题库","oe":["错误：通道蛋白只转运离子和小分子，不能运输铁等大分子。","错误：吞饮作用为非特异性液相内吞，不能选择性摄取铁。","正确：铁、转铁蛋白等经受体识别，通过受体介导内吞进入细胞。","错误：自由扩散只适合小分子，无法转运铁这类物质。"]},{"q":"8． （    ）。","o":["A．协助扩散","B．协同运输","C．胞吞作用","D．以上都有"],"a":"C","e":"真核细胞主要通过胞吞作用完成大分子颗粒性物质的跨膜转运。","src":"章节题库","oe":["错误：协助扩散只转运小分子，不能转运70nm的病毒颗粒。","错误：协同运输属于小分子转运方式，不适用于病毒颗粒。","正确：真核细胞以胞吞作用转运大分子及颗粒性物质如病毒。","错误：只有胞吞作用符合，并非以上都有。"]},{"q":"9． ＋   ＋ ）。","o":["A．介导主动运输","B．介导 Na 和 K 的协同运输 ＋      ＋","C．是一种整合膜蛋白","D．能够创造跨膜动力势","E．以上都正确"],"a":"E","e":"Na -K ATPase 是一个由 ATP 直接提供能量的主动运输。Na -K ATPase 每消耗一 ＋    ＋                                   ＋ ＋   个 ATP 泵出 3 个 Na 泵进 3 个 K 。Na -K ATPase 维持胞内低 Na 高 K 形成跨膜动力势。 ＋          ＋ ＋   ＋          ＋   ＋   Na -K ATPase 位于质膜上，是一种整合膜蛋白。 ＋  ＋","src":"章节题库","oe":["正确：Na+-K+ ATP酶介导主动运输，直接水解ATP提供能量。","正确：它同时泵出Na+、泵入K+，属对向协同运输。","正确：Na+-K+ ATP酶位于质膜上，是一种整合膜蛋白。","正确：它维持胞内高钾低钠，能够创造跨膜电化学动力势。","正确：以上四项均正确，故选E。"]},{"q":"关于通道蛋白介导的运输，叙述错误的是（                     ）。","o":["A．通道蛋白分子不需与转运物质结合","B．绝大多数通道蛋白形成有选择性开关的多次跨膜通道","C．通道蛋白具备离子的选择性和构象可调控性","D．配体门通道蛋白包括胞外配体门通道和胞内配体门通道"],"a":"C","e":"通道蛋白不具备构象可调控性。","src":"章节题库","oe":["正确：通道蛋白不与转运物质结合，只形成亲水性通道。","正确：多数通道蛋白形成有选择性开关的多次跨膜通道。","错误：通道蛋白只有离子选择性，不具备构象可调控性。","正确：配体门通道包括胞外配体门通道和胞内配体门通道。"]},{"q":"钙泵的主要作用是（               ）。","o":["A．降低细胞质中的 Ca2 浓度 ＋","B．提高细胞质中的 Ca2 浓度 ＋","C．帮助 Ca2 富集到内质网腔 ＋","D．降低线粒体中 Ca2 浓度 ＋"],"a":"A","e":"Ca2 泵，分布在动、植物细胞质膜、线粒体内膜、内质网样囊膜（SER-like organelle）、 ＋   动物肌肉细胞肌质网膜上，是由 1000 个氨基酸的多肽链形成的跨膜蛋白，它是 Ca2 激活的 ＋   ATP 酶，每水解一个 ATP 转运两个 Ca2 到细胞外，形成钙离子梯度。通常细胞质游离 Ca2 ＋   浓度很低，约 10-7～10-8 摩尔/升，细胞间液 Ca2 浓度较高，约 5×10-3 摩尔/升。胞外的 Ca2 ＋                                        ＋   即使很少量涌入胞内都会引起胞质游离 Ca2 浓度显著变化，导致一系列生理反应。钙流能 ＋                                     ＋   迅速地将细胞外信号传入细胞内，因此 Ca2 是一种十分重要的信号物质。线粒体内腔、肌 ＋   质网、内质网样囊腔中含高浓度的 Ca2 ，浓度大于 10-5 摩尔/升，名为“钙库”。在一定的信 ＋   号作用下 Ca2 从钙库释放到细胞质，调节细胞运动、肌肉收缩、生长、分化等诸多生理功 ＋   能。","src":"章节题库","oe":["正确：钙泵将Ca2+泵出细胞或泵入钙库，降低胞质游离Ca2+浓度。","错误：钙泵降低而非提高细胞质中的Ca2+浓度。","错误：把Ca2+泵入内质网腔是途径，最终效果为降低胞质Ca2+。","错误：钙泵把Ca2+泵入线粒体等钙库，是升高而非降低其Ca2+。"]},{"q":"以下关于吞噬作用，叙述错误的是（                     ）。","o":["A．吞噬泡直径一般大于 250 nm","B．吞噬作用的进行需要触发机制","C．吞噬泡的形成需要微管骨架的参与","D．吞噬泡的形成需要微丝骨架的参与"],"a":"C","e":"吞噬泡的形成需要微丝骨架的参与。","src":"章节题库","oe":["正确：吞噬泡直径通常大于250nm，属于大颗粒内吞。","正确：吞噬作用的进行需要受体识别等触发机制。","错误：吞噬泡的形成依赖微丝骨架，而非微管骨架。","正确：吞噬泡的形成确需微丝骨架参与。"]},{"q":"下列有关钙泵的叙述错误的是（                   ）。","o":["A．是一种跨膜蛋白，与 Na -K 泵的α亚基有高度同源性 ＋  ＋","B．细胞内钙调蛋 A 与之结合调节钙泵的活性 c．钙泵每消耗 1 分子 ATP,转运 2 个 Ca","D．钙泵仅存在于细胞膜上，转运钙的方向是将其泵出细胞外"],"a":"D","e":"钙泵不仅存在于细胞膜上．还存在于内质网上，它可将 Ca2 泵入内质网储存。 ＋","src":"章节题库","oe":["正确：钙泵是跨膜蛋白，与Na+-K+泵α亚基高度同源，属P型ATP酶。","正确：钙调蛋白与之结合可调节钙泵活性；钙泵每消耗1分子ATP转运2个Ca2+。","错误：钙泵也存在于内质网上，可将Ca2+泵入内质网储存。"]},{"q":"有关协同运输，下列哪项说法错误？（       ）","o":["A．协同运输必须有载体蛋白的参与","B．完成共运输的载体蛋白有两个结合位点，必须同时与转运分子结合后才能共运输","C．动物细胞只能以协同运输的方式转运葡萄糖分子","D．动物细胞常通过 Na 驱动的 Na -H 对向运输以调节细胞内的 PH 值 ＋   ＋ ＋"],"a":"C","e":"葡萄糖分子跨膜转运方式可有：简单扩散、协助扩散以及协同运输等方式。","src":"章节题库","oe":["正确：协同运输必须有载体蛋白的参与。","正确：完成共运输的载体有两个结合位点，须同时结合两种转运分子。","错误：葡萄糖还可经简单扩散、协助扩散转运，并非只能协同运输。","正确：动物细胞常靠Na+驱动的Na+-H+对向运输调节胞内pH值。"]},{"q":"15． ＋ ）","o":["A．自由扩散","B．离子通道","C．Na ／K 泵 ＋   ＋","D．协同运输"],"a":"D","e":"协同运输对于动物细胞来说是利用两侧的钠离子电化学梯度来驱动的；而植物细胞 和细菌是利用氢离子电化学梯度来驱动的。","src":"章节题库","oe":["错误：自由扩散虽慢，K+仍可极少量顺梯度通过脂双层。","错误：离子通道是K+快速跨膜的主要方式。","错误：Na+/K+泵可逆梯度将K+泵入细胞。","正确：协同运输一般转运糖、氨基酸等，通常不用于运输K+。"]},{"q":"低密度的脂蛋白颗粒（LDL）的功能是（       ）。","o":["A．把食物中的甘油酸脂和胆固醇从肠道经淋巴管输送到血液，随血液流入肝脏","B．把体内自身合成的胆固醇转运到肝脏","C．把血液中胆固醇带走，送到结缔组织表面受体","D．将甘油酸脂从肝脏输出"],"a":"C","e":"由于 C 胆固醇在水中的绝对不溶性使它成为致命性的病因.当 Ch 在不适当的部位 （如动脉壁内）堆积时,会导致动脉粥样硬化斑块的生成，低密度脂蛋白（LDL）可以将胆 固醇从血浆中清除走。","src":"章节题库","oe":["错误：把肠道吸收的甘油酸脂和胆固醇经淋巴入血的是乳糜微粒。","错误：把体内自身合成的胆固醇转运到肝脏的是高密度脂蛋白。","正确：LDL把血液中胆固醇送到结缔组织等外周细胞表面受体。","错误：把甘油三酯从肝脏输出的是极低密度脂蛋白（VLDL）。"]},{"q":"1． 研]","o":["A．根吸收矿质元素离子","B．红细胞保钾排钠","C．腺细胞分泌的酶排出细胞","D．小肠对 Ca、P 的吸收"],"a":"C","e":"ABD 三项，都是通过主动运输来实现，需要消耗能量，更需要特异性的载体的协 助。C 项，腺细胞分泌通过胞吐作用，消耗能量，但不需要载体参与。","src":"名校考研真题","oe":["错误：根吸收矿质离子需载体蛋白并消耗能量，属主动运输。","错误：红细胞保钾排钠靠钠钾泵（载体），属主动运输。","正确：腺细胞分泌酶通过胞吐，消耗能量但不需要载体蛋白。","错误：小肠吸收Ca、P需特异性载体并消耗能量，属主动运输。"]}],"fill":[{"q":"1．","a":"简单扩散；协助扩散","src":"章节题库"},{"q":"2． ______和______两类。","a":"通道蛋白；载体蛋白；膜转运蛋白","src":"章节题库","oe":["协助扩散需特异膜转运蛋白；膜转运蛋白第一类为通道蛋白，形成亲水通道。","第二类为载体蛋白，通过构象改变协助溶质顺浓度梯度跨膜转运。"]},{"q":"3．","a":"都需要膜转运蛋白；前者不消耗能量","src":"章节题库"},{"q":"4. ＋   ＋  ＋","a":"ATP；H 的电化学势能","src":"章节题库"},{"q":"5．","a":"胞饮作用；吞噬作用","src":"章节题库"},{"q":"6．","a":"细胞松弛素 B","src":"章节题库"},{"q":"7． 之形成______，这种内吞方式称为受体介导内吞。","a":"网格蛋白 有被小泡","src":"章节题库","oe":["受体质膜内陷形成网格蛋白有被小窝，继而缢缩形成有被小泡。"]},{"q":"8． 输。","a":"协同","src":"章节题库"},{"q":"9. ＋  ＋","a":"消耗 ATP；H 浓度梯度势能 ＋","src":"章节题库"},{"q":"10． 称为______型质子泵。","a":"P；V","src":"章节题库","oe":["质膜上的H+泵转运时形成磷酸化中间体，为P型；溶酶体膜与液泡膜的H+泵不形成，为V型。"]},{"q":"11． ＋","a":"Ca2 泵运输；Ca2 通道运输；共运输；渗漏（扩散） ＋      ＋","src":"章节题库"},{"q":"12.","a":"短杆菌肽 A 在人工膜上可能形成了 K 通道 ＋","src":"章节题库"},{"q":"13．","a":"电压门控通道；配体门控通道；机械门控通道","src":"章节题库"},{"q":"14．","a":"网格蛋白；微丝及其结合蛋白","src":"章节题库"},{"q":"15．","a":"选择性浓缩","src":"章节题库"},{"q":"16. ＋  ＋        ＋   ＋","a":"Na 离子通道；Na ／K 泵；协同运输。","src":"章节题库","oe":["Na+经离子通道顺电化学梯度被动扩散进入细胞，不耗能，属被动运输。","Na+/K+泵水解ATP逆浓度梯度泵出Na+、泵入K+，属主动运输。","协同运输靠Na+电化学梯度驱动，间接耗能，如Na+与葡萄糖同向转运。"]},{"q":"17．","a":"胞内体","src":"章节题库"},{"q":"18．","a":"内吞作用；细胞黏着；接触抑制。","src":"章节题库"},{"q":"19. ＋                                            ＋   细胞器内，使周围环境和细胞器呈______性。","a":"植物；溶酶体；液泡膜；酸","src":"章节题库","oe":["H+泵位于细菌、真菌、植物细胞膜及溶酶体、液泡膜上，将H+泵入细胞器使其呈酸性。"]},{"q":"20．","a":"回到原位；被溶酶体水解；转到另一部分的膜上。","src":"章节题库"},{"q":"1． 是_________。","a":"水解 ATP 功能；磷酸化与去磷酸化作用","src":"名校考研真题","oe":["P型泵运输机制有两点：一是具有水解ATP的功能，二是伴随磷酸化与去磷酸化。"]},{"q":"2．","a":"离子选择；门控性","src":"名校考研真题"},{"q":"3． 的病毒，以其包膜与细胞膜_______的方式进入细胞。","a":"内吞；融合","src":"名校考研真题","oe":["有包膜病毒以其包膜与细胞膜融合进入细胞；多数动物病毒则以细胞内吞方式进入。"]}],"judge":[{"q":"1．","a":"错","src":"章节题库"},{"q":"2． 小分子。（         ）","a":"错","src":"章节题库","oe":["选“对”不成立：水孔蛋白只过水，题干却称其转运脂溶性分子和有机小分子。","选“错”正确：水孔蛋白有严格选择性，仅容许水分子通过，孔径约0.28nm。"]},{"q":"3． ＋         ＋ ）","a":"对","src":"章节题库"},{"q":"4． 的内吞泡需要网格蛋白的参与。（                 ）","a":"错","src":"章节题库","oe":["选“对”不成立：题干把胞饮与吞噬所需成分说反了，与实际不符。","选“错”正确：胞饮泡形成需网格蛋白，吞噬泡形成需微丝及其结合蛋白。"]},{"q":"5. ＋  ＋ ）","a":"错","src":"章节题库"},{"q":"6． 速度，但是与酶不同的是，载体蛋白不对被转运的分子作任何修饰。（               ）","a":"错","src":"章节题库","oe":["选“对”不成立：载体蛋白能改变跨膜运输的平衡点，并非只加快达平衡。","选“错”正确：载体蛋白可改变运输平衡点，且不对底物作共价修饰。"]},{"q":"7． ＋ ）","a":"错","src":"章节题库"},{"q":"8．","a":"错","src":"章节题库"},{"q":"2．","a":"对","src":"名校考研真题"}]},"ch06":{"mcq":[{"q":"下列哪些组分与线粒体与叶绿体的半自主性相关？（             ）","o":["A．环状 DNA","B．自身转录 RNA","C．翻译蛋白质的体系","D．以上全是"],"a":"D","e":"线粒体和叶绿体都具有环状 DNA，可以自身转录生成 RNA，合成蛋白质，因此线 粒体和叶绿体属于半自主细胞器。","src":"章节题库","oe":["线粒体和叶绿体均含环状DNA，具自主遗传的物质基础。","两者均可自身转录生成RNA，含核糖体等转录体系。","两者都有蛋白质合成体系，能合成部分自身蛋白质。","A、B、C均为其半自主性的依据，故以上全是正确。"]},{"q":"关于线粒体光合磷酸化的质子梯度，以下说法正确的是（              ）。","o":["A．基质中浓度高，类囊体中浓度低","B．基质中浓度低，类囊体中浓度高","C．膜间隙中浓度高，基质中浓度低","D．膜间隙中浓度低，基质中浓度高"],"a":"B","e":"线粒体中的光合磷酸化过程中质子由基质泵至膜间隙，叶绿体的光和作用过程中， 质子由基质泵至类囊体中。","src":"章节题库","oe":["A错：应是类囊体腔内H+浓度高，而基质中浓度低。","B对：光反应将质子由基质泵入类囊体，腔内H+浓度高。","C错：膜间隙高、基质低是线粒体情况，非叶绿体。","D错：线粒体膜间隙H+浓度高，方向与此项相反。"]},{"q":"原核细胞不具备下列哪种结构？（             ）","o":["A．线粒体","B．核糖体","C．细胞壁","D．核外 DNA"],"a":"A","e":"原核细胞不具有线粒体结构。","src":"章节题库","oe":["A对：原核细胞无膜性细胞器，不具线粒体。","B错：原核细胞有核糖体，是蛋白质合成场所。","C错：多数原核细胞具细胞壁（如肽聚糖）。","D错：原核细胞有核外DNA，如质粒。"]},{"q":"与高等植物细胞相比，动物细胞特有的结构包括（       ）。","o":["A．内质网","B．中心体","C．线粒体","D．液泡"],"a":"B","e":"中心体是动物细胞参与有丝分裂的特异结构。","src":"章节题库","oe":["A错：内质网动植物细胞普遍存在，非动物特有。","B对：中心体是动物细胞参与有丝分裂的特有结构。","C错：线粒体动植物细胞都有，非动物特有。","D错：液泡主要见于植物细胞，非动物特有。"]},{"q":"不是前导肽特性的是（    ）。","o":["A．带有较多的碱性氨基酸","B．酸性氨基酸含量多","C．羟基氨基酸比较多","D．具有双亲性"],"a":"B","e":"前导肽的结构特征是：（1）含有丰富的带正电荷的碱性氨基酸，特别是精氨酸； ①羟基氨基酸如丝氨酸含量也较高；（2）几乎不含带负电荷的酸性氨基酸；（3）可形成既 具亲水性又具疏水性的α螺旋结构，此用有利于穿越线粒体的双层膜。","src":"章节题库","oe":["A对：前导肽富含带正电荷的碱性氨基酸如精氨酸。","B错：前导肽几乎不含酸性氨基酸，而非含量多。","C对：前导肽中羟基氨基酸如丝氨酸含量较高。","D对：前导肽可形成既亲水又疏水的α螺旋。"]},{"q":"线粒体基质的标志酶为（    ）。","o":["A．单胺氧化酶","B．苹果酸脱氢酶","C．活化磷酸二脂酶","D．细胞色素氧化酶"],"a":"B","e":"各部位的标志酶：外膜的单胺氧化酶，膜间隙的腺苷酸激酶，内膜的细胞色素氧化 酶，基质中的苹果酸脱氢酶。","src":"章节题库","oe":["A错：单胺氧化酶是线粒体外膜的标志酶。","B对：苹果酸脱氢酶是线粒体基质的标志酶。","C错：活化磷酸二脂酶不是线粒体的标志酶。","D错：细胞色素氧化酶是线粒体内膜的标志酶。"]},{"q":"线粒体和叶绿体都是半自主性细胞器，它们（      ）。","o":["A．各自在基质中有一个双链 DNA 环","B．各自在基质中有多个双链 DNA 环","C．叶绿体基质中有多个双链 DNA 环，而线粒体只有一个","D．线粒体基质中有多个双链 DNA 环，而叶绿体只有一个"],"a":"B","e":"（1）线粒体的自主性主要表现在具有自己的遗传体系和蛋白质合成系统，线粒体 DNA 是双链环状分子，每个细胞具有多个线粒体，每个线粒体有多个 DNA 拷贝，但是线 粒体 DNA 的总量不到核基因组的 1％。（2）叶绿体的自主性表现在叶绿体不仅有自己的环 状双链 DNA 分子，还有自己的核糖体。叶绿体基因组是多拷贝的，有的可以多达 40 个。","src":"章节题库","oe":["A错：并非只有一个DNA环，两者均为多拷贝。","B对：线粒体和叶绿体基质中均含多个双链DNA环。","C错：线粒体也含多个DNA环，并非只有一个。","D错：叶绿体也含多个DNA环，并非只有一个。"]},{"q":"关于线粒体的主要功能叙述（     ）。","o":["A．由丙酮酸形成乙酰辅酶 A","B．进行三羧酸循环","C．进行电子传递、释放能量并形成 ATP","D．A＋B＋C 最确切"],"a":"D","e":"（1）线粒体的主要功能是进行氧化磷酸化，合成 ATP，为细胞生命活动提供直接 能量。线粒体是糖、脂肪和氨基酸最终释能的场所。（2）糖和脂肪等营养物质在细胞质中 经过酵解作用产生丙酮酸和脂肪酸。这些物质选择性地从细胞质进入线粒体基质中，经过一 系列分解代谢形成乙酰 CoA，即可进入三羧酸循环。三羧酸循环脱下来的氢经线粒体内膜 上的电子传递链（呼吸链），最后传递给氧，生成水。在此过程中能量水平较高的电子，经 过电子传递降到较低水平，所释放的能量通过 ADP 的磷酸化，生成高能磷酸键 ATP，从能 量转换的角度，线粒体内膜起着主要作用。","src":"章节题库","oe":["A对：线粒体基质中丙酮酸氧化脱羧生成乙酰CoA。","B对：三羧酸循环在线粒体基质中进行。","C对：电子传递在内膜进行，释放能量形成ATP。","D对：A、B、C均为线粒体功能，故D最确切。"]},{"q":"线粒体基质的标志酶为（    ）。","o":["A．单胺氧化酶","B．苹果酸脱氢酶","C．活化磷酸二脂酶","D．细胞色素氧化酶"],"a":"B","e":"各部位的标志酶：外膜的单胺氧化酶，膜间隙的腺苷酸激酶，内膜的细胞色素氧化 酶，基质中的苹果酸脱氢酶。","src":"章节题库","oe":["A错：单胺氧化酶是线粒体外膜的标志酶。","B对：苹果酸脱氢酶是线粒体基质的标志酶。","C错：活化磷酸二脂酶不是线粒体的标志酶。","D错：细胞色素氧化酶是线粒体内膜的标志酶。"]},{"q":"2． 学 2011 研]","o":["A．细胞核","B．叶绿体","C．细胞核和叶绿体","D．叶绿体和细胞核"],"a":"D","e":"核酮糖二磷酸羧化酶是光合作用中一个起重要作用的酶系统，全酶由 8 个大亚基和 8 个小亚基组成。已知酶的活性中心位于大亚基上，小亚基只有调解功能。大亚基由叶绿体 基因编码，而小亚基则是由核基因编码。","src":"名校考研真题","oe":["A错：大亚基由叶绿体基因编码，不能只答细胞核。","B错：小亚基由核基因编码，不能只答叶绿体。","C错：顺序颠倒，大亚基在叶绿体、小亚基在细胞核。","D对：大亚基由叶绿体DNA、小亚基由核DNA编码。"]},{"q":"3． 山大学 2008 研]","o":["A．细胞色素","B．质体蓝素","C．质体醌","D．聚光色素"],"a":"D","e":"聚光色素吸收聚集光能并将光能转移到反应中心色素，其本身不具有光化学活性。","src":"名校考研真题","oe":["A错：细胞色素是电子传递体，参与氧化还原。","B错：质体蓝素是含铜的电子传递体。","C错：质体醌是脂溶性电子与质子载体。","D对：聚光色素只吸收传递光能，无光化学活性。"]},{"q":"4． 研]","o":["A．细胞色素氧化酶","B．单胺氧化酶","C．腺苷酸激酶","D．柠檬酸合成酶"],"a":"A","e":"B 项，单胺氧化酶是线粒体外膜标志酶。C 项，腺苷酸激酶是膜间隙标志酶。D 项， 柠檬酸合成酶是代谢标志酶，位于线粒体基质中。","src":"名校考研真题","oe":["A对：细胞色素氧化酶是线粒体内膜的标志酶。","B错：单胺氧化酶是线粒体外膜的标志酶。","C错：腺苷酸激酶是线粒体膜间隙的标志酶。","D错：柠檬酸合成酶是线粒体基质的标志酶。"]},{"q":"5． 研]","o":["A．叶绿体外膜","B．叶绿体内膜","C．基粒中囊状结构的薄膜","D．基质"],"a":"C","e":"光反应是在类囊体膜上由光引起的光化学反应，通过叶绿素等光合色素分子吸收、 传递光能，并将光能转换成电能，进而转换为活跃的化学能，形成 ATP 和 NADPH 的过程。 暗反应是在叶绿体基质中进行的不需光（也可在光下）的酶促化学反应，利用光反应产生的 ATP 和 NADPH，使 CO2 还原为糖类等有机物，即将活跃的化学能最后转换为稳定的化学能， 积存于有机物中。","src":"名校考研真题","oe":["A错：叶绿体外膜不进行光反应。","B错：叶绿体内膜不进行光反应。","C对：光反应在基粒类囊体薄膜上进行。","D错：基质是暗反应（CO2固定）的场所。"]}],"fill":[{"q":"1． 是______、______和______等。","a":"膜间隙；基质；膜间隙；基质腔；类囊体腔","src":"章节题库","oe":["线粒体膜围腔为膜间隙和基质；叶绿体自外向里第一种腔为膜间隙。","叶绿体第二种腔为基质腔，即内膜以内、类囊体以外的空间。","叶绿体第三种腔为类囊体腔，是类囊体膜围成的光反应场所。"]},{"q":"2．","a":"一种革兰阴性菌；蓝细菌（蓝藻）","src":"章节题库"},{"q":"3．","a":"核酮糖-1，5-二磷酸羧化酶","src":"章节题库"},{"q":"4． 因及其表达体系。","a":"DNA；RNA；翻译蛋白质","src":"章节题库","oe":["线粒体和叶绿体含环状DNA，可自我复制并转录，故第一空填DNA。","其遗传信息可自身转录生成RNA，故第二空填RNA。","两者含核糖体等，具备翻译蛋白质的体系，故第三空填翻译蛋白质。"]},{"q":"5．","a":"核基因组及其自身的基因组","src":"章节题库"},{"q":"6． 合磷酸化的电子传递体中______既是电子载体又是质子转移体。","a":"复合物Ⅰ；复合物Ⅲ；复合物Ⅳ；PQ","src":"章节题库","oe":["呼吸链中复合物Ⅰ、Ⅲ、Ⅳ既传递电子又泵质子；光合链中质体醌PQ也兼具两种功能。"]},{"q":"7． 和______，后者则仅生成______。","a":"非循环式；循环式；ATP；NADPH；ATP","src":"章节题库","oe":["按电子传递方式分非循环式与循环式，可见第二空应填循环式。","非循环式产物为ATP和NADPH，循环式仅生成ATP，故末空填ATP。"]},{"q":"8． ＋","a":"NADP ；O2","src":"章节题库"},{"q":"9. 分别是______、______和______。","a":"3-磷酸甘油酸；草酰乙酸；草酰乙酸","src":"章节题库","oe":["C3途径CO2固定最初产物为3-磷酸甘油酸，由RuBP羧化形成。","C4途径CO2固定最初产物为草酰乙酸，在叶肉细胞中生成。","CAM途径夜间固定CO2最初产物也是草酰乙酸，故末空相同。"]},{"q":"10．","a":"叶绿体 DNA 编码并在叶绿体核糖体合成的蛋白；核 DNA 编码并在叶绿体核糖体 合成的蛋白；核 DNA 编码并在细胞质核糖体合成的蛋白","src":"章节题库"},{"q":"11. 朝向______。","a":"氧化磷酸化；线粒体基质；光合磷酸化；叶绿体基质","src":"章节题库","oe":["F0F1ATP合酶朝向线粒体基质，CF0-CF1ATP合酶朝向叶绿体基质，均伸入相应基质。"]},{"q":"12．","a":"原初反应；电子传递；光合磷酸化。","src":"章节题库"},{"q":"13． 粒体转化的是______，而叶绿体转化的是______。","a":"化学能；光能。","src":"章节题库","oe":["线粒体通过氧化磷酸化把有机物中的化学能转化为ATP中的化学能。","叶绿体通过光合作用把光能转化为糖类等有机物中的化学能。"]},{"q":"14．","a":"构象耦联","src":"章节题库"},{"q":"15． 化学能，形成______和______，并有______放出。","a":"类囊体膜；ATP；NADPH；O2","src":"章节题库","oe":["光反应在类囊体膜上进行，通过光合磷酸化形成ATP，故第二空填ATP。","光反应同时生成NADPH，为暗反应提供还原力，故第三空填NADPH。","水的光解产生O2放出，故末空填O2。"]},{"q":"16． 原成糖。","a":"基质；ATP；NADPH","src":"章节题库","oe":["暗反应在叶绿体基质中进行，故第一空填基质。","暗反应利用光反应产生的ATP供能，故第二空填ATP。","同时利用光反应产生的NADPH作还原剂，故第三空填NADPH。"]},{"q":"17． 线粒体的______部位插入的。","a":"内外膜的接触点","src":"章节题库","oe":["前体蛋白经内外膜接触点插入，一次性跨越线粒体双层膜进入基质。"]},{"q":"18． 复制发生在______或______。","a":"半自主；G2 期；G1 期；S 期","src":"章节题库","oe":["叶绿体DNA（chDNA）的复制发生在G1期，故一空填G1期。","叶绿体DNA复制也可发生在S期，而线粒体DNA复制在G2期。"]},{"q":"19. 位由______编码。","a":"8；8；核 DNA；叶绿体 DNA","src":"章节题库","oe":["RuBP羧化酶小亚基由核DNA编码，大亚基由叶绿体DNA编码，故末空填叶绿体DNA。"]},{"q":"20．","a":"蓝藻；紫细菌；绿细菌","src":"章节题库"},{"q":"1． 科院-中科大 2005 研]","a":"34 条以上多肽链或者 FMN 和至少 6 个铁硫蛋白；催化 NADH 的２个电子传给辅酶Ｑ，同 时发生质子的跨膜输送或者电子传递体和质子移位体","src":"名校考研真题","oe":["复合物Ⅰ由34条以上多肽链组成，含FMN和至少6个铁硫蛋白。","其功能是催化NADH的2个电子传给辅酶Q。","同时发生质子跨膜输送，故它兼为电子传递体和质子移位体。"]},{"q":"2． 研究证实，大亚基是由_______编码，而小亚基是由_______编码。","a":"叶绿体基因；核基因","src":"名校考研真题","oe":["RuBP羧化酶大亚基由叶绿体基因编码，故一空填叶绿体基因。","其小亚基由核基因编码，故二空填核基因。"]},{"q":"3． 和_________。","a":"NADH-辅酶 Q 还原酶（Ⅰ）；琥珀酸-辅酶 Q 还原酶（Ⅱ）；CoQH2-细胞色素还原酶（Ⅲ）； 细胞色素氧化酶（Ⅳ）；ATP 合酶","src":"名校考研真题","oe":["线粒体内膜5种酶复合体为复合物Ⅰ、Ⅱ、Ⅲ、Ⅳ和ATP合酶（复合物Ⅴ）。"]}],"judge":[{"q":"1． 称线粒体和叶绿体为半自主性细胞器。（            ）","a":"错","src":"章节题库","oe":["若选对，则误认为二者多数蛋白质由自身编码，与事实相反。","错：其绝大多数蛋白质由核基因组编码，少数由自身编码，题干颠倒。"]},{"q":"2．","a":"错","src":"章节题库"},{"q":"3．","a":"错","src":"章节题库"},{"q":"4．","a":"错","src":"章节题库"},{"q":"5． 子受体。（        ）","a":"错","src":"章节题库","oe":["若选对，则错误地认为两种细胞器电子传递穿膜次数相同。","错：线粒体与叶绿体中电子穿膜次数不同，并非都穿膜三次。"]},{"q":"6． 的作用。（        ）","a":"错","src":"章节题库","oe":["若选对，则误认为复合物Ⅱ也能将质子跨膜移位。","错：复合物Ⅱ只传递电子，不能转移质子，其余才兼两种作用。"]},{"q":"7．","a":"对","src":"章节题库"},{"q":"8．","a":"错","src":"章节题库"},{"q":"9．","a":"错","src":"章节题库"},{"q":"10． 称线粒体和叶绿体为半自动性细胞器。（                 ）","a":"错","src":"章节题库","oe":["若选对，则既弄错编码来源，又误用“半自动性”一词。","错：多数蛋白由核基因组编码，且应称半自主性细胞器。"]},{"q":"1． 胞质，再通过线粒体内外肽接触点位置一次性跨越两层膜运送到线粒体基质中。（                     ）","a":"错","src":"名校考研真题","oe":["若选对，则误认为线粒体tRNA由核基因编码并经该途径输入。","错：线粒体基质tRNA由线粒体自身基因编码，并非核基因编码。"]},{"q":"2． 时，提取了其中的高能电子，并将这些高能电子储存在 NADH 或 FADH2 中。（                 ）","a":"对","src":"名校考研真题","oe":["对：三羧酸循环脱下的高能电子被NAD+、FAD接收生成NADH、FADH2。","若选错，则误解了TCA循环在能量代谢中的主要贡献。"]},{"q":"3． 2007 研]","a":"对","src":"名校考研真题"}]},"ch07":{"mcq":[{"q":"新合成的磷脂由内质网转移到线粒体的方式是（         ）。","o":["A．出芽方式","B．磷脂转位因子","C．磷脂转换蛋白","D．膜泡运输"],"a":"C","e":"磷脂转运的方式主要有两种，转移到高尔基体、溶酶体和细胞膜上的磷脂主要通过 出芽方式，转移到线粒体和过氧化酶酶体主要通过磷脂转换蛋白。","src":"章节题库","oe":["A错：出芽方式主要把磷脂运到高尔基体、溶酶体和质膜。","B错：磷脂转位因子介导膜内脂质翻转到另一层。","C对：磷脂转换蛋白把内质网磷脂运往线粒体等。","D错：膜泡运输主要运输蛋白质，非磷脂转线粒体。"]},{"q":"有关蛋白质的折叠与装配，下列说法错误的是（         ）。","o":["A．蛋白二硫异构酶可以切断错误形成的二硫键，使蛋白质形成自由能较低的蛋白构象","B．没有二硫异构酶的存在，新合成的蛋白质不能正确折叠","C．结合蛋白可以识别不正确折叠的蛋白或未装配好的蛋白亚单位","D．蛋白二硫异构酶和结合蛋白都具有 4 肽信号，以保证它们滞留在内质网中"],"a":"B","e":"没有蛋白二硫异构酶，新合成的蛋白也可以正确折叠，但它的存在大大加快了这一 过程。","src":"章节题库","oe":["A对：蛋白二硫异构酶可切断错误二硫键促正确折叠。","B错：无二硫异构酶，新蛋白仍可正确折叠，只是较慢。","C对：结合蛋白能识别错误折叠或未装配的蛋白。","D对：二硫异构酶和结合蛋白含4肽KDEL驻留信号。"]},{"q":"不属于内膜系统的是（     ）。","o":["A．高尔基体","B．溶酶体","C．脂质体","D．分泌泡"],"a":"C","e":"脂质体是人工制备膜结构体，并不属于真核细胞的内膜系统。胞内体和分泌泡是真 核细胞内膜围绕形成的细胞结构，属于内膜系统。","src":"章节题库","oe":["A错：高尔基体属真核细胞内膜系统。","B错：溶酶体由内膜围绕形成，属内膜系统。","C对：脂质体是人工制备的膜结构，不属内膜系统。","D错：分泌泡由内膜形成，属内膜系统。"]},{"q":"有关细胞结构的装配，下列说法错误的是（    ）。","o":["A．在细胞有丝分裂过程中，绝大多数的细胞器都经历装配与去装配的过程","B．细胞骨架体系在整个细胞结构体系中起到了重要的组织作用","C．决定新合成的多肽如何正确折叠的信息存在于蛋白质氨基酸的一级结构中","D．只要多肽氨基酸的一级结构完整，所有多肽自身都能正确地折叠成有功能的蛋白质"],"a":"D","e":"只凭借多肽自身并不能保证新合成的多肽正确地转移、折叠和装配，还需要其他生 物大分子的协助。","src":"章节题库","oe":["A对：有丝分裂中多数细胞器经历装配与去装配。","B对：细胞骨架对整个细胞结构起组织作用。","C对：多肽折叠信息存在于氨基酸一级序列中。","D错：多肽仅靠自身难以正确折叠装配，需其他分子协助。"]},{"q":"有关细胞质基质，下列说法错误的是（   ）。","o":["A．细胞质基质是蛋白质和脂质合成的重要场所","B．用差速离心法分离得到的上清液，即所谓的胞质溶胶就是细胞质基质","C．胞质溶胶中的多数蛋白质，直接或间接地结合在细胞质基质的骨架纤维上","D．细胞质基质的许多功能都与细胞质骨架相关"],"a":"B","e":"用差速离心法分离得到的上清液，被生化学家称为胞质溶胶，它的成分与细胞质基 质周围的溶液成分有很大的不同。","src":"章节题库","oe":["A对：细胞质基质是蛋白质和脂质合成的重要场所。","B错：差速离心上清液为胞质溶胶，其成分与基质溶液差异大。","C对：胞质溶胶中多数蛋白结合在基质骨架纤维上。","D对：细胞质基质许多功能与细胞质骨架相关。"]},{"q":"在匀浆和离心的过程中，细胞中破碎的内质网常形成近似球形的囊泡结构，称为（ ）。","o":["A．脂质体","B．微体","C．微粒体","D．胞内体"],"a":"C","e":"微体是过氧化物酶体的别称。","src":"章节题库","oe":["A错：脂质体是人工制备的磷脂膜囊，非破碎内质网形成。","B错：微体是过氧化物酶体的别称，与内质网无关。","C对：匀浆离心中破碎内质网形成的球形囊泡称微粒体。","D错：胞内体是胞吞形成的膜性细胞器，非内质网碎片。"]},{"q":"所有膜蛋白都具有方向性，其方向性在什么部位中确定？（   ）","o":["A．细胞质基质","B．高尔基体","C．内质网","D．质膜"],"a":"C","e":"其方向性在内质网上合成时就已经确定，在以后的转运过程中，其拓扑学特性始终 保持不变。","src":"章节题库","oe":["A错：方向性并非在细胞质基质中确定。","B错：高尔基体只对蛋白加工分选，不决定方向性。","C对：膜蛋白方向性在内质网上合成时即已确定。","D错：质膜是膜蛋白的目的地，不决定其方向性。"]},{"q":"有关高尔基体的生物学特点，下列说法错误的是（    ）。","o":["A．高尔基体是由大小不一、形态多变的囊泡体系组成","B．一般动物细胞中，高尔基体的数目都非常多，从而较容易分离和纯化","C．高尔基体从结构和功能上都是一种有极性的细胞器","D．高尔基体是一个复杂的由许多功能不同的间隔所组成的完整体系"],"a":"B","e":"高尔基体在一般动物细胞中的数目较少，在含量丰富的肝细胞也仅有少量的高尔基 体，高尔基体具有异质性，不易辨认，更难纯化和分离。","src":"章节题库","oe":["A对：高尔基体由大小不一、形态多变的囊泡组成。","B错：一般动物细胞高尔基体少，不易分离纯化。","C对：高尔基体从结构到功能都是有极性的。","D对：高尔基体由功能不同的多个区室组成。"]},{"q":"9． 一步都是加上唾液酸残基，由此可推测催化唾液酸转移酶最有可能存在于高尔基体的（      ）。","o":["A．CGN","B．顺面膜囊","C．中间膜囊","D．反面膜囊和 TGN"],"a":"D","e":"在高尔基体发生的复杂的糖基化过程，其方向是由 CGN→TGN，因此最后一步反 应最有可能发生在反面膜囊和 TGN 中。","src":"章节题库","oe":["A错：CGN是顺面网状结构，糖基化起始不在此加唾液酸。","B错：顺面膜囊位于顺面，尚未到糖基化最后一步。","C错：中间膜囊进行中间加工，非最后一步。","D对：糖基化方向CGN→TGN，最后加唾液酸在反面膜囊和TGN。"]},{"q":"胞嘧啶单核苷酸酶（CMP 酶）的细胞化学反应常常可显示下列什么结构？（    ）","o":["A．顺面膜囊","B．中间膜囊","C．反面膜囊","D．整个高尔基体"],"a":"C","e":"用电镜细胞化学方法对高尔基体机构成分分析的 4 种标志细胞化学反应：顺面膜囊 ——嗜锇反应；焦磷酸硫胺素酶（TPP 酶）——显示反面 1～2 层膜囊；胞嘧啶单核苷酸酶 （CMP 酶）——显示靠近反面膜囊状和管状结构；烟酰胺腺嘌呤二核苷磷酸酶（NADP 酶） ——显示中间扁平囊。","src":"章节题库","oe":["A错：嗜锇反应显示顺面膜囊，非CMP酶。","B错：NADP酶显示中间扁平囊，非CMP酶。","C对：CMP酶显示靠近反面膜囊的管状结构。","D错：CMP酶只显示反面膜囊结构，非整个高尔基体。"]},{"q":"蛋白质的糖基化修饰中，N-连接的糖基化反应一般发生在（     ）。","o":["A．内质网胞质面","B．内质网腔面","C．高尔基体","D．内质网和高尔基体"],"a":"B","e":"蛋白质的糖基化修饰中，N-连接的糖基化反应一般发生在内质网腔面，而 D 连接 的糖基化反应则发生在内质网和高尔基体中。","src":"章节题库","oe":["A错：内质网胞质面不进行N-连接糖基化。","B对：N-连接糖基化起始和进行于内质网腔面。","C错：高尔基体主要进行O-连接糖基化和加工。","D错：N-连接糖基化主要在内质网腔面，非两者。"]},{"q":"有关蛋白质的糖基化及其修饰，下列选项错误的是（     ）。","o":["A．溶酶体中的水解酶类、多数细胞膜上的膜蛋白和分泌蛋白都是糖蛋白","B．细胞质基质和细胞核中绝大多数蛋白质都无糖基化修饰","C．糖链在大多数蛋白质的分选中起决定性作用","D．糖基化可影响多肽的构象"],"a":"C","e":"用 DNA 重组技术证明，多种糖蛋白在去掉糖链后仍能正常地输送到细胞的特定部 位，从而说明糖链在大多数蛋白质的分选中并不起决定性作用。","src":"章节题库","oe":["正确；溶酶体水解酶、多数膜蛋白与分泌蛋白都带糖链，属糖蛋白。","正确；细胞质基质与细胞核中绝大多数蛋白质不发生糖基化修饰。","错误；去掉糖链后糖蛋白仍能正常运输到位，说明糖链并非分选的决定因素。","正确；糖基化可影响多肽链的构象与稳定性。"]},{"q":"溶酶体中的酶（   ）。","o":["A．在初级溶酶体中有活性","B．在次级溶酶体中有活性","C．在残余小体（三级溶酶体）中有活性","D．始终都保持着活性"],"a":"B","e":"当初级溶酶体与细胞内的自噬泡或异噬泡融合后，溶酶体内的酶才具有活性，形成 具有消化作用的次级溶酶体。","src":"章节题库","oe":["错误；初级溶酶体刚形成，酶尚未与底物接触，通常不表现活性。","正确；初级溶酶体与自噬泡或异噬泡融合成次级溶酶体后，酶才具消化活性。","错误；残余小体处于消化后期，其中水解酶活性已很弱。","错误；溶酶体酶并非始终有活性，其活性受pH和底物接触影响。"]},{"q":"少量溶酶体酶泄漏到细胞质基质中，并不会引起细胞损伤的主要原因是（      ）。","o":["A．溶酶体酶蛋白迅速被特异的机制召回溶酶体中","B．另外一些蛋白与溶酶体酶结合，抑制其活性","C．溶酶体酶进入细胞质基质随即被降解成无活性的肽段","D．细胞质基质中的 pH 值为 7.0 左右，溶酶体酶的活性大大降低"],"a":"D","e":"溶酶体酶的最适 pH 值为 5.0 左右，故而进入细胞质基质后，活性大大降低。在酵 母细胞质基质中发现一些蛋白质可与溶酶体酶特异地结合，但该原因不是主要的。","src":"章节题库","oe":["不全面；部分酶可经M6P受体召回，但这不是进入基质后的主要保护机制。","非主因；酵母中确有蛋白与酶结合抑制其活性，但并非普遍原因。","错误；溶酶体酶进入细胞质基质不会随即被降解成无活性肽段。","正确；溶酶体酶最适pH约5.0，而细胞质基质pH约7.0，故其活性大大降低。"]},{"q":"关于台-萨氏（Tay-Sachs）病的发病原因，下列说法最确切的是（     ）。","o":["A．外来病原体使吞噬泡的酸化作用被抑制，溶酶体酶的活性大大降低","B．溶酶膜自身结构缺陷，溶酶体膜易破裂，细胞被溶酶体酶损伤从而致病","C．溶酶体中缺少β-氨基己糖脂酶 A，胞膜上神经节甘脂不能被水解而积累在细胞内","D．溶酶体膜上的载体蛋白功能缺陷，不能将消化的小分子转运至细胞外，导致溶酶体破坏"],"a":"C","e":"台-萨氏是一种储积症，这类疾病是一种隐性遗传病，其共同特征是溶酶体内充满 了未被降解的物质。A 项，是结核、麻风杆菌致病原因。","src":"章节题库","oe":["错误；病原体抑制吞噬泡酸化是结核、麻风杆菌的致病机制，非台-萨氏病。","错误；溶酶体膜自身缺陷破裂并非台-萨氏病的病因。","正确；台-萨氏病缺乏β-氨基己糖脂酶A，神经节苷脂不能被水解而贮积。","错误；载体蛋白缺陷致溶酶体破坏不是台-萨氏病的机制。"]},{"q":"在真核细胞中不具有高度异质性的细胞器是（        ）。","o":["A．溶酶体","B．过氧化物酶体","C．乙醛酸循环体","D．内质网"],"a":"D","e":"植物细胞的过氧化物酶体称为乙醛酸循环体，溶酶体和过氧化物酶体都具有高度异 质性特点。","src":"章节题库","oe":["错误；溶酶体具有高度异质性，不同细胞中形态与酶类差异很大。","错误；过氧化物酶体同样具有高度异质性。","错误；乙醛酸循环体是植物细胞的过氧化物酶体，属异质性细胞器。","正确；内质网为相对均一的膜性网络，不具溶酶体、过氧化物酶体的高度异质性。"]},{"q":"下面哪种蛋白质在糙面内质网上合成？（       ）","o":["A．actin","B．spectrin","C．酸性磷酸酶","D．酵母外激素α因子"],"a":"C","e":"酸性磷酸酶定位于溶酶体中，须经膜泡运输的方式才能到达溶酶体因此在糙面内质 网上合成。","src":"章节题库","oe":["错误；actin为细胞质基质蛋白，由游离核糖体合成。","错误；spectrin是膜骨架蛋白，也在细胞质基质中合成。","正确；酸性磷酸酶是溶酶体酶，须在糙面内质网合成后经膜泡运输到位。","错误；酵母α因子为分泌蛋白，最终分泌到细胞外，不定位于溶酶体。"]},{"q":"在下列细胞器中，能分拣内吞大分子的是（        ）。","o":["A．内体","B．滑面内质网","C．高尔基体","D．糙面内质网"],"a":"A","e":"内体是膜包裹的囊泡结构，有初级内体（early endosome）和次级内体（late endosome） 之分,初级内体是由于细胞的内吞作用而形成的含有内吞物质的膜结合的细胞器，次级内体 中的 pH 呈酸性, 且具有分拣作用，能够分选与配体结合的受体，让它们再循环到细胞质膜 表面或高尔基体反面网络,","src":"章节题库","oe":["正确；内体由内吞形成，呈酸性并可分选受体，使其再循环至质膜或高尔基体。","错误；滑面内质网主要合成脂质、参与解毒，无内吞与受体分选功能。","错误；高尔基体虽有分选功能，但不是内吞形成、含内吞物质的内体。","错误；糙面内质网负责蛋白质合成与加工，不承担内吞分选。"]},{"q":"下列细胞中，除（       ）外，都有较多的高尔基复合体。","o":["A．上皮细胞","B．肌细胞","C．唾液腺细胞","D．胰腺外分泌细胞"],"a":"B","e":"高尔基体的主要功能是与分泌有关，在分泌型细胞中高尔基复合体的数量会比较多。","src":"章节题库","oe":["错误；上皮细胞（尤其腺上皮）具分泌功能，高尔基体较发达。","正确；肌细胞以收缩功能为主、分泌功能弱，高尔基复合体数量少。","错误；唾液腺细胞分泌旺盛，高尔基体发达。","错误；胰腺外分泌细胞分泌消化酶，高尔基体发达。"]},{"q":"在下列细胞器中质子泵存在于（        ）。","o":["A．高尔基体膜上","B．溶酶体膜上","C．过氧化物酶体膜上","D．内质网膜上"],"a":"B","e":"溶酶体膜上嵌有质子泵，借助水解 ATP 释放出的能量将氢离子泵入溶酶体内，使 溶酶体中的氢离子浓度比细胞质中高 100 倍以上，以形成和维持酸性的内环境。","src":"章节题库","oe":["错误；高尔基体膜上的质子泵不是本题所述维持溶酶体酸性内环境的泵。","正确；溶酶体膜上嵌有质子泵，水解ATP将H+泵入，使内环境呈酸性。","错误；过氧化物酶体膜上不存在此类质子泵。","错误；内质网膜上不存在该质子泵。"]},{"q":"下面哪种细胞器以分裂方式增殖 （         ）。","o":["A．过氧化物酶体","B．高尔基体","C．溶酶体","D．内质网"],"a":"A","e":"成熟的过氧化物酶体通过分裂的方式增生。","src":"章节题库","oe":["正确；成熟的过氧化物酶体通过分裂的方式增生。","错误；高尔基体由内质网出芽及膜囊装配增生，不靠分裂。","错误；溶酶体由内体或高尔基体出芽形成，不通过分裂增生。","错误；内质网通过膜扩展与出芽增生，不进行分裂。"]},{"q":"矽肺病是一种职业病。与溶酶体有关，其发病机理是（           ）。","o":["A．溶酶体的酶没有活性","B．矽粒使溶酶体破裂","C．溶酶体的数量不够","D．初级溶酶体不能与含有矽粒的吞噬体形成次级溶酶体"],"a":"B","e":"矽肺（silicosis）空气中的矽（Sio2）被吸入肺后，被肺部的吞噬细胞所吞噬，由于 吞入的二氧化硅颗粒不能被消化，并在颗粒的表面形成硅酸。硅酸的羧基和溶酶体膜的受体 分子形成氢键，使膜破坏，释放出水解酶，导致细胞死亡，结果刺激成纤维细胞产生胶原纤 维结节，造成肺组织的弹性降低，肺受到损伤，呼吸功能下降。","src":"章节题库","oe":["错误；溶酶体酶本身有活性，只是二氧化硅不能被消化。","正确；硅酸与溶酶体膜形成氢键使膜破裂，释放水解酶致细胞死亡。","错误；矽肺与溶酶体数量不足无关。","错误；初级溶酶体能正常与含矽粒的吞噬体融合成次级溶酶体。"]}],"fill":[{"q":"1．","a":"脂质；蛋白质","src":"章节题库"},{"q":"2．","a":"分泌蛋白；膜整合蛋白；细胞器驻留蛋白","src":"章节题库"},{"q":"3． 过______方式和______蛋白。","a":"细胞质基质；出芽方式；磷脂转换蛋白","src":"章节题库","oe":["内质网合成的脂质可经出芽方式形成囊泡转运，故首空填出芽。","脂质还可借磷脂转换蛋白在膜间转移，故次空填磷脂转换蛋白。"]},{"q":"4． 脂质、糖类与很多蛋白质分子在其表面合成并分选运输；______是合成物加工、包装与运输 的细胞器；______是细胞内的消化系统；______和______主要供应细胞生命活动所需要的能 量，它们均为双膜封闭系统。","a":"内质网；高尔基体；溶酶体；线粒体；叶绿体","src":"章节题库","oe":["高尔基体是合成物加工、包装与运输的细胞器，故首空填高尔基体。","溶酶体含多种水解酶，是细胞内的消化系统，故次空填溶酶体。","线粒体是供应细胞能量的双膜封闭系统，故第三空填线粒体。","叶绿体也是双膜封闭系统，主要供应能量，故末空填叶绿体。"]},{"q":"5．","a":"酶蛋白；细胞骨架蛋白","src":"章节题库"},{"q":"6． 基的羟基。","a":"N-乙酰葡萄糖胺分子","src":"章节题库","oe":["糖基转移酶把N-乙酰葡萄糖胺分子加到丝氨酸或苏氨酸残基的羟基上，故填此。"]},{"q":"7． ______、______和______等。","a":"糖基化；羟基化；酰基化；二硫键形成","src":"章节题库","oe":["内质网中蛋白质的加工修饰包括糖基化，故首空填糖基化。","羟基化也是内质网中蛋白质的修饰方式，故次空填羟基化。","酰基化也属此类修饰，此外还有二硫键形成，故第三空填酰基化。"]},{"q":"8． 要场所。","a":"光面；粗面","src":"章节题库","oe":["光面内质网无核糖体附着，是脂质合成的重要场所，故首空填光面。","粗面内质网附着核糖体，是蛋白质合成的重要场所，故次空填粗面。"]},{"q":"9．","a":"内质网腔面；糖基转移酶","src":"章节题库"},{"q":"10．","a":"肌质网","src":"章节题库"},{"q":"11． 的______残基与______直接连接，后者是蛋白质上的______残基与______直接连接。","a":"N-连接的；O-连接的；天冬酰胺；N-乙酰葡萄糖胺；丝氨酸或苏氨酸；N-乙酰半 乳糖胺","src":"章节题库","oe":["N-连接糖链以N-乙酰葡萄糖胺残基与多肽链相连，故首空填N-乙酰葡萄糖胺。","该糖残基直接连接在多肽链的天冬酰胺(Asn)残基上，故次空填天冬酰胺。","O-连接中多肽链的丝氨酸或苏氨酸残基与糖相连，故第三空填丝氨酸或苏氨酸。","O-连接糖链以N-乙酰半乳糖胺与Ser/Thr羟基连接，故末空填N-乙酰半乳糖胺。"]},{"q":"12． 为______、______和______。","a":"顺面膜囊或顺面网状结构；中间膜囊；反面膜囊和反面网状结构","src":"章节题库","oe":["高尔基复合体顺面为顺面膜囊或顺面网状结构，故首空填此。","高尔基复合体中间为中间膜囊，故次空填中间膜囊。","高尔基复合体反面为反面膜囊和反面网状结构，故末空填此。"]},{"q":"13． 区别是前者______和______。","a":"没有模板；靠不同的酶催化","src":"章节题库","oe":["糖链合成没有模板，由糖基转移酶按序添加单糖，故首空填没有模板。","糖链合成靠不同的酶催化、无模板指导，故次空填靠不同的酶催化。"]},{"q":"14． 的不同阶段，大致可分为______、______和______。","a":"初级溶酶体；次级溶酶体；残余体","src":"章节题库","oe":["溶酶体形成与消化的初始阶段为初级溶酶体，故首空填初级溶酶体。","与底物融合后进行消化的为次级溶酶体，故次空填次级溶酶体。","消化后残留的结构为残余体，故末空填残余体。"]},{"q":"15．","a":"圆球体；中央液泡","src":"章节题库"},{"q":"16．","a":"尿酸氧化酶；晶格状结构","src":"章节题库"},{"q":"17．","a":"酸性水解酶（或酸性磷酸酶）；过氧化氢酶","src":"章节题库"},{"q":"18．","a":"光呼吸；乙醛酸循环","src":"章节题库"},{"q":"19． ______（举一例即可）。","a":"分子伴侣；Hsp70 蛋白家族","src":"章节题库","oe":["内质网中帮助蛋白质折叠的是分子伴侣，如Hsp70蛋白家族，故填此。"]},{"q":"20．","a":"整合到质膜；分泌到细胞外；进入溶酶体","src":"章节题库"},{"q":"21．","a":"糙面；光面","src":"章节题库"},{"q":"22．","a":"尿酸氧化酶；类核体","src":"章节题库"},{"q":"23． 主要是______和______。","a":"细胞质基质膜；出芽；依靠磷脂转换蛋白","src":"章节题库","oe":["内质网合成的脂质可经出芽（囊泡）方式转运，故首空填出芽。","脂质还可借磷脂转换蛋白经细胞质基质转运，故次空填依靠磷脂转换蛋白。"]},{"q":"24．","a":"初级溶酶体；吞噬小体","src":"章节题库"},{"q":"25．","a":"过氧化物酶体；乙醛酸循环体","src":"章节题库"},{"q":"26．","a":"内质网；细胞膜","src":"章节题库"},{"q":"27． 氧化物酶体的标志酶是______。","a":"葡萄糖-6-磷酸酶；酸性磷酸酶；糖基转移酶；过氧化氢酶","src":"章节题库","oe":["过氧化物酶体的标志酶是过氧化氢酶，其余为溶酶体、内质网和高尔基体的标志酶。"]},{"q":"28． ______、______和______中。","a":"反面管网结构；中间膜囊；顺面膜囊及管网结构","src":"章节题库","oe":["高尔基体反面管网结构参与分泌物的分选包装，故首空填反面管网结构。","中间膜囊含多种糖基转移酶，是糖链加工区，故次空填中间膜囊。","顺面膜囊及管网结构接收内质网来的小泡，故末空填顺面膜囊及管网结构。"]},{"q":"29．","a":"表面积与体积比；关键分子浓度对反应的影响；细胞质膜的合成。","src":"章节题库"},{"q":"30． ______结构中。","a":"一级结构","src":"章节题库","oe":["该结构指单糖或氨基酸残基的排列顺序，属于一级结构，故填一级结构。"]},{"q":"31． 集中在______，而 3H-岩藻糖或 3H-半乳糖标记物则集中在______膜囊中。","a":"粗面内质网；高尔基体反面","src":"章节题库","oe":["3H-甘露糖参入N-连接核心糖链，标记集中在粗面内质网，故首空填此。","岩藻糖、半乳糖为糖链末端糖，在高尔基体反面膜囊添加，故次空填此。"]},{"q":"32．","a":"光面内质网；葡萄糖-6-磷酸","src":"章节题库"},{"q":"33． 间扁平囊呈______反应，靠近反面的膜呈______反应，成熟面呈______反应。","a":"电镜细胞化学方法；嗜锇；烟酰胺腺瞟吟二核苷磷酸酶；胞嘧啶单核苷酸酶；焦磷 酸硫胺素酶","src":"章节题库","oe":["中间扁平囊含烟酰胺腺嘌呤二核苷酸磷酸酶，故首空填该酶。","靠近反面的膜含胞嘧啶单核苷酸酶，故次空填该酶。","成熟面含焦磷酸硫胺素酶，故末空填该酶。"]},{"q":"34． 胞器，经过循环消化 2 分子______产生 l 分子______。","a":"乙醛酸循环；圆球体；线粒体；乙酰 CoA；琥珀酸","src":"章节题库","oe":["乙醛酸循环每循环消耗2分子乙酰CoA，故首空填乙酰CoA。","该循环净产生1分子琥珀酸，故次空填琥珀酸。"]},{"q":"1. 糖蛋白中，______糖残基与多肽链的_____（氨基酸）结合；O-连接糖蛋白中_____糖残基 同多肽链的_____或_____（氨基酸）结合。","a":"高尔基体；糙面内质网和高尔基体；核心寡聚糖；天冬酰胺；乙酰半乳糖胺；丝氨 酸；苏氨酸","src":"名校考研真题","oe":["N-连接糖蛋白的核心寡聚糖与多肽链相连，故首空填核心寡聚糖。","N-连接糖链锚定在多肽链的天冬酰胺(Asn)残基上，故次空填天冬酰胺。","O-连接糖链以N-乙酰半乳糖胺参与连接，故第三空填乙酰半乳糖胺。","O-连接糖链连接在丝氨酸(Ser)残基上，故第四空填丝氨酸。","O-连接糖链也可连在苏氨酸(Thr)残基上，故末空填苏氨酸。"]},{"q":"2． 哺乳动物的细胞中把 N-乙酰葡萄糖胺分子加到蛋白质的 上。","a":"丝氨酸残基的羟基","src":"名校考研真题","oe":["糖基转移酶把N-乙酰葡萄糖胺加到丝氨酸残基的羟基上，故填丝氨酸残基的羟基。"]},{"q":"3．","a":"酸性水解酶；过氧化氢酶","src":"名校考研真题"},{"q":"4．","a":"质子泵；载体蛋白；高度糖基化","src":"名校考研真题"}],"judge":[{"q":"1．","a":"错","src":"章节题库"},{"q":"2． 质网腔中，一般都不能进入高尔基体。（      ）","a":"对","src":"章节题库","oe":["正确；含KDEL等驻留信号的蛋白滞留于内质网腔，一般不能进入高尔基体。","错误；若选错，则忽视了驻留蛋白的回收滞留机制。"]},{"q":"3．","a":"对","src":"章节题库"},{"q":"4.","a":"对","src":"章节题库"},{"q":"5． 解酶分选的重要识别信号。（      ）","a":"错","src":"章节题库","oe":["错误；认为对则误把题干所述序列当作分选信号，实际分选信号是M6P。","正确；溶酶体水解酶的识别信号是M6P（甘露糖-6-磷酸），题干所述并非该信号。"]},{"q":"6．","a":"错","src":"章节题库"},{"q":"7．","a":"错","src":"章节题库"},{"q":"8．","a":"错","src":"章节题库"},{"q":"9．","a":"错","src":"章节题库"},{"q":"10.","a":"对","src":"章节题库"},{"q":"11．","a":"错","src":"章节题库"},{"q":"12. 腔和线粒体腔的糖蛋白。（      ）","a":"错","src":"章节题库","oe":["错误；若选对，则误认为内质网腔和线粒体腔均可发生糖基化。","正确；糖基化主要在内质网腔和高尔基体腔进行，线粒体腔蛋白一般不糖基化。"]},{"q":"13. （      ）","a":"错","src":"章节题库"},{"q":"14．","a":"错","src":"章节题库"},{"q":"15． 质网腔中，一般都不能进入高尔基体。（                  ）","a":"对","src":"章节题库","oe":["正确；含KDEL等驻留信号的蛋白滞留于内质网腔，一般不能进入高尔基体。","错误；若选错，则忽视了驻留蛋白的回收滞留机制。"]},{"q":"2． （      ）","a":"错","src":"名校考研真题"},{"q":"4． 中科大 2007 研]","a":"错","src":"名校考研真题"},{"q":"5． 研]","a":"对","src":"名校考研真题"},{"q":"6． 在内质网腔中。（          ）","a":"错","src":"名校考研真题","oe":["错误；若选对，则把O-连接糖基化的部位误认为内质网腔。","正确；O-连接糖链主要在高尔基体中加接，内质网腔主要进行N-连接糖基化。"]}]},"ch08":{"mcq":[{"q":"信号蛋白的信号肽的切除发生在（      ）。","o":["A．细胞质基质","B．内质网","C．高尔基体","D．溶酶体"],"a":"B","e":"非细胞体系实验证实，N 端信号肽是在转移至微粒体以后，在蛋白质合成结束完全 进入微粒体之前切除的。","src":"章节题库","oe":["错误；信号肽的切除不在细胞质基质中完成。","正确；信号肽在蛋白质转入内质网（微粒体）后、合成结束前被切除。","错误；高尔基体不负责信号肽的切除。","错误；溶酶体不参与信号肽的切除。"]},{"q":"2． （   ）。","o":["A．信号肽","B．导肽","C．转运肽","D．信号斑"],"a":"A","e":"信号序列：①内质网驻留蛋白 C 端含回收信号序列 KDEL 或 KKXX；②分泌性蛋 白含有 N 端信号肽；③细胞质基质合成的细胞器蛋白含导肽或前导肽；④细胞核蛋白含核 输入信号。","src":"章节题库","oe":["正确；分泌蛋白N端的信号肽引导核糖体附着内质网并使肽链穿膜。","错误；导肽是细胞质基质中合成的细胞器蛋白的前导序列。","错误；转运肽多指进入叶绿体、线粒体的转运序列，非分泌蛋白N端信号。","错误；信号斑是蛋白质折叠后形成的三维分选信号，不是N端肽段。"]},{"q":"以下运输途径中，COP Ⅱ包被参与的是（             ）。","o":["A．质膜→内体","B．高尔基体→溶酶体","C．高尔基体→内质网","D．内质网→高尔基体"],"a":"D","e":"COPⅡ负责从内质网到高尔基体的物质运输。COPⅡ包被蛋白由 5 种蛋白亚基组成。 COPⅡ有被小泡具有对转运物质的选择性并使之浓缩","src":"章节题库","oe":["错误；质膜到内体由网格蛋白等其他衣被小泡介导，不是COPⅡ。","错误；高尔基体到溶酶体由网格蛋白衣被小泡介导。","错误；高尔基体到内质网由COPⅠ有被小泡负责。","正确；COPⅡ有被小泡负责从内质网到高尔基体的物质运输。"]},{"q":"4． （   ）。","o":["A．该多肽将转移到内质网上继续合成","B．该多肽合成结束后将最终被定位到内质网膜上","C．该多肽将最终成为多次跨膜的膜蛋白","D．该多肽将最终被运送至溶酶体而被降解"],"a":"C","e":"开始转移序列是引导肽链穿过内质网膜的信号肽，停止转移序列与内质网膜具有较 强的亲合力而结合在脂双层中，因此 C 选项是最确切的说法。","src":"章节题库","oe":["错误；开始转移序列引导其边合成边进入内质网，而非继续游离合成。","错误；含多个跨膜区段时最终为多次跨膜蛋白，而非仅定位在膜上。","正确；有开始转移序列与停止转移序列交替，最终形成多次跨膜蛋白。","错误；该多肽不会因这些序列被运往溶酶体降解。"]}],"fill":[{"q":"1． 所特有的序列。","a":"KDEL；HDEL","src":"章节题库","oe":["动物细胞内质网驻留蛋白C端的回收信号是KDEL，故首空填KDEL。","酵母中相应的回收信号为HDEL，故次空填HDEL。"]},{"q":"2． 而含导肽的蛋白质在细胞质中合成后再转移到细胞器中的方式称为______。","a":"共转移；后转移","src":"章节题库","oe":["在细胞质中合成后再转移至细胞器的属翻译后转运，即后转移，故填后转移。"]},{"q":"3． 质基质中蛋白质的转运。","a":"蛋白质的跨膜转运；膜泡运输；选择性门控转运","src":"章节题库","oe":["蛋白质的跨膜转运指经膜上转运器穿膜，故首空填蛋白质的跨膜转运。","膜泡运输指经囊泡介导的转运，故次空填膜泡运输。","选择性门控转运指经核孔复合体的核质运输，故末空填选择性门控转运。"]},{"q":"4． 的______等因子协助完成。","a":"信号识别颗粒；信号识别颗粒受体（停泊蛋白）","src":"章节题库","oe":["共翻译转运需信号识别颗粒（SRP）等因子协助，故填信号识别颗粒。"]},{"q":"5．","a":"网格蛋白有被小泡；COPⅠ有被小泡；COPⅡ有被小泡","src":"章节题库"},{"q":"1． 结构体系之间的装配。","a":"自我装配；协助装配；直接装配","src":"章节题库","oe":["结构体系的自我装配指亚基自发组装，故首空填自我装配。","协助装配需其他因子帮助完成，故次空填协助装配。","直接装配也是结构体系的一种装配方式，故末空填直接装配。"]},{"q":"6．","a":"门控运输；跨膜运输；膜泡运输","src":"章节题库"},{"q":"7. 多肽和一个______S 的 RNA 组成。","a":"信号识别颗粒；11；6；7。","src":"章节题库","oe":["信号识别颗粒含1分子7S RNA、6个多肽，故该空填7。"]},{"q":"8． 这类多肽一旦被识别，便通过______从内质网腔转至______，进而被蛋白酶体所降解。它们 的______约为 20～30 min，有些只有 5 min。","a":"内质网膜；内质网腔；sec61P 复合体；细胞质基质；半寿期","src":"章节题库","oe":["错误折叠蛋白经sec61P复合体转出内质网，故首空填sec61P复合体。","转出至细胞质基质后被蛋白酶体降解，故次空填细胞质基质。","这类蛋白寿命短，其半寿期约20～30 min，故末空填半寿期。"]},{"q":"9． ______，这种内吞方式称为受体介导内吞。","a":"衣被小窝；衣被小泡","src":"章节题库","oe":["受体-配体复合物聚集于质膜的衣被小窝，继而形成衣被小泡，该空填衣被小窝。"]},{"q":"1． 常驻留在内质网腔，而带有______序列的蛋白质则会被输送到_______。","a":"RGD；细胞外","src":"名校考研真题","oe":["与KDEL驻留信号相对，含RGD序列的蛋白被运出细胞，故首空填RGD。","这类蛋白经分泌途径被输送到细胞外，故次空填细胞外。"]},{"q":"2．","a":"信号肽；信号识别颗粒；信号识别颗粒受体（停泊蛋白）","src":"名校考研真题"},{"q":"3． 不同的运输途径。①___________泡，运输方向是___________到___________；②___________ 泡，运输方向是___________到___________；③___________泡，运输方向既可以是 ___________到___________，又可以是___________到___________。","a":"①COPⅡ包被膜；内质网；高尔基体；②COPⅠ衣被小；高尔基体；内质网；③网格蛋白／ 接头蛋白被膜；高尔基体；溶酶体或液泡；质膜；胞内体","src":"名校考研真题","oe":["COPⅡ包被膜泡介导内质网到高尔基体的顺向运输，故①填COPⅡ包被膜","该顺向运输的起点是内质网，故第二空填内质网","该顺向运输的终点是高尔基体，故第三空填高尔基体","逆向运输由COPⅠ衣被小泡介导，故②填COPⅠ衣被小泡","COPⅠ小泡从高尔基体出芽，故该空填高尔基体","COPⅠ小泡将货物运回内质网，故该空填内质网","高尔基体到溶酶体等由网格蛋白／接头蛋白被膜泡介导","该网格蛋白被膜泡可从高尔基体出芽，故填高尔基体","其一个运输终点是溶酶体或液泡，故填溶酶体或液泡","网格蛋白被膜泡也可从质膜内陷形成，故填质膜","内吞后先运向胞内体，故最后一个空填胞内体"]}],"judge":[{"q":"1． 带有信号肽，就留在细胞内。（          ）","a":"错","src":"章节题库","oe":["错误；若选对，则误以为带信号肽的蛋白必定留在细胞内。","正确；信号肽引导蛋白进入分泌途径，分泌蛋白会被运出细胞外。"]},{"q":"2．","a":"错","src":"章节题库"},{"q":"3．","a":"错","src":"章节题库"},{"q":"4． 基体返回内质网，不能进入溶酶体。（             ）","a":"对","src":"章节题库","oe":["正确；含KDEL回收信号的驻留蛋白在高尔基体被识别并返回内质网，不入溶酶体。","错误；若选错，则忽视了KDEL回收机制。"]},{"q":"5．","a":"对","src":"章节题库"},{"q":"6．","a":"错","src":"章节题库"},{"q":"7．","a":"对","src":"章节题库"},{"q":"8．","a":"错","src":"章节题库"}]},"ch09":{"mcq":[{"q":"下列有关气体信号分子 NO 的说法，错误的是（          ）。","o":["A．在平滑肌细胞内，L 精氨酸在 NO 合酶催化作用下生成 NO","B．NO 通过增强可溶性鸟苷酸环化酶的活性，发挥作用","C．鸟苷酸环化酶催化 GTP 生成 cGMP，cGMP 介导蛋白质的磷酸化","D．NO 通过舒张血管平滑肌治疗心绞痛，NO 也参与大脑的学习记忆生理过程"],"a":"A","e":"血管内皮细胞和神经细胞是 NO 的生成细胞，NO 再经扩散进入平滑肌细胞发挥作 用。","src":"章节题库","oe":["错误项（答案）：NO由血管内皮细胞和神经细胞生成，不在平滑肌细胞内生成","正确：NO可增强可溶性鸟苷酸环化酶活性，进而舒张血管","正确：鸟苷酸环化酶催化GTP生成cGMP，经PKG引起蛋白磷酸化","正确：NO舒张血管平滑肌可治心绞痛，也参与大脑学习记忆"]},{"q":"细胞内信号蛋白的相互作用是靠（            ）所特异性介导的。","o":["A．蛋白质模式结合域","B．受体蛋白","C．G 蛋白偶联受体","D．疏水性分子相互作用"],"a":"A","e":"靠信号蛋白具有不同的模式结合域与另一相匹配的基序识别与结合，在细胞内组装 成不同信号转导复合物，构成细胞内信号传递通路的基础。","src":"章节题库","oe":["正确：信号蛋白靠模式结合域与匹配基序识别，组装成信号复合物","受体蛋白是接收信号的分子，不是组装信号通路的基础","G蛋白偶联受体只是受体的一类，并非信号传递通路的通用基础","疏水性分子间相互作用不是信号复合物组装的主要识别机制"]},{"q":"下列不具有分子开关作用的蛋白是（            ）。","o":["A．G 蛋白","B．Ras 蛋白","C．接头蛋白","D．Rho 蛋白"],"a":"C","e":"接头蛋白在信号通路中既不能被磷酸化，也不能结合 GTP，它只起偶联作用。而 G 蛋白、Ras 蛋白和 Rho 蛋白分别在不同的信号通路中发挥了分子开关的作用，当其结合 GTP 时处于活化状态，当其结合 GDP 时处于失活状态。Rho 在整联蛋白介导的信号传递中起分 子开关的作用。","src":"章节题库","oe":["G蛋白结合GTP时活化、结合GDP时失活，发挥分子开关作用","Ras蛋白结合GTP时活化，是信号通路中的分子开关","正确：接头蛋白无激酶活性也不结合GTP，只起偶联作用","Rho蛋白在整联蛋白介导的信号传递中起分子开关作用"]},{"q":"不属于蛋白酪氨酸激酶类型的受体是（            ）。","o":["A．EGF 受体","B．PDGF 受体","C．TGFβ受体","D．IGF-1 受体"],"a":"C","e":"TGFβ受体即转化生长因子β受体，为受体丝氨酸／苏氨丝氨激酶。","src":"章节题库","oe":["EGF受体属于受体酪氨酸蛋白激酶，非本题答案","PDGF受体属于受体酪氨酸蛋白激酶，非本题答案","正确：TGFβ受体即转化生长因子β受体，为受体丝氨酸／苏氨酸激酶","IGF-1受体属于受体酪氨酸蛋白激酶，非本题答案"]},{"q":"对于由整联蛋白介导的信号传递，下列哪项说法错误？（            ）","o":["A．胞外配体主要为细胞外基质成分，如纤连蛋白等","B．整联蛋白与胞外配体的相互作用只产生一种胞内信号，即胞内 Ca2+浓度增加","C．当胞外配体与整联蛋白结合，可导致分子开关蛋白 Rho 蛋白激活","D．最终作用是与细胞增殖相关的基因被激活，细胞周期相关蛋白合成"],"a":"B","e":"整联蛋白与胞外配体的相互作用可产生多种信号，如 Ca2+释放进入细胞质基质，肌 醇第二信使的合成，胞内酪氨酸残基的磷酸化等。","src":"章节题库","oe":["正确：整联蛋白的胞外配体主要为纤连蛋白等细胞外基质是细胞外的纤维网络结构成分","错误项（答案）：整联蛋白可产生多种胞内信号，不止Ca2+浓度升高一种","正确：胞外配体与整联蛋白结合可激活分子开关Rho蛋白","正确：信号最终可激活增殖相关基因，合成细胞周期相关蛋白"]},{"q":"在 cAMP 信号中，G 蛋白的偶联作用表现为（            ）。","o":["A．受体的活化导致 G 蛋白的α、β、γ三个亚单位的偶联","B．受体的活化通过 G 蛋白与 MAPK 激酶级联反应通路偶联","C．受体的活化通过 G 蛋白与 PKA(cAMP-dependent protein kinase A)的活化偶联 n 受体的活 化通过 G 蛋白与 AC(adenyl cyclase)的活化偶联","D．受体的活化通过 G 蛋白与 cAMP 偶联"],"a":"D","e":"在 cAMP 信号通路中，三聚体 G 蛋白由α、β、γ三个亚单位组成，受体的活化导致 与 G 蛋白α亚单位相结合的 GDP 被 GTP 交换，而β、γ二聚体共价结合锚于内膜。在 cAMP 信号通路中，处于活化状态的三聚体 G 蛋白亚单位α—GTP 作用于 AC。活化的 AC 使 ATP 环化，生成 cAMP。","src":"章节题库","oe":["错误：受体活化使G蛋白解离，而非α、β、γ三亚单位偶联","错误：MAPK级联主要由Ras等介导，非经G蛋白直接偶联","错误：G蛋白直接作用于腺苷酸环化酶AC，而非与PKA偶联","正确：受体活化经G蛋白使AC生成cAMP，与cAMP通路偶联"]},{"q":"不属于蛋白酪氨酸激酶类型的受体是（               ）。","o":["A．EGF 受体","B．PDGF 受体","C．TGF-3 受体","D．IGF-1 受体"],"a":"C","e":"酪氨酸激酶受体包括 EGF 受体、IGF-1 受体、NGF 受体、FGF 受体、VEGF 受体、 PDGF 受体。","src":"章节题库","oe":["EGF受体属于酪氨酸激酶受体，非本题答案","PDGF受体属于酪氨酸激酶受体，非本题答案","正确（答案）：TGF-3(β)受体是丝氨酸／苏氨酸激酶，不属酪氨酸激酶受体","IGF-1受体属于酪氨酸激酶受体，非本题答案"]},{"q":"下列关于信号分子的描述中，不正确的是（                ）。","o":["A．神经递质属于亲脂性信号","B．本身不具有酶的活性","C．能传递信息","D．可作为作用底物"],"a":"A","e":"神经递质属于亲水性信号分子。","src":"章节题库","oe":["错误项（答案）：神经递质属于亲水性信号分子，而非亲脂性信号","正确：神经递质本身一般不具有酶的活性","正确：神经递质能与相应受体结合并传递信息","正确：神经递质可被相应酶降解，可作为酶的作用底物"]},{"q":"与细胞内钙离子浓度调控直接相关的信号为（                ）。","o":["A．DAG","B．PKC","C．CaM","D．IP3"],"a":"D","e":"IP3 通过细胞质基质扩散，结合并打开内质网膜上 IP3 敏感的钙通道，引起钙离子顺 电化学梯度从钙库释放进入细胞质基质，通过钙调蛋白引起细胞反应。","src":"章节题库","oe":["DAG是脂类第二信使，主要激活PKC，非本题答案","PKC是被DAG和Ca2+激活的蛋白激酶，非释放钙的信使","CaM是结合Ca2+的钙调蛋白，本身不引起钙库释放","正确：IP3扩散到内质网，打开钙通道使Ca2+从钙库释放"]}],"fill":[{"q":"1．","a":"亲脂性的信号分子；亲水性的信号分子","src":"章节题库"},{"q":"2．","a":"第一信使；第二信使","src":"章节题库"},{"q":"3．","a":"cAMP 信号通路；磷脂酰肌醇信号通路；G 蛋白偶联离子通道的信号通路","src":"章节题库"},{"q":"4.","a":"腺苷酸环化酶；磷脂酶 C","src":"章节题库"},{"q":"5．","a":"四个亚基；只有一条肽链","src":"章节题库"},{"q":"6．","a":"分泌化学信号；细胞间接触性依赖；细胞间形成间隙连接","src":"章节题库"},{"q":"7．","a":"NO","src":"章节题库"},{"q":"8．","a":"激素激活的基因调控蛋白；细胞内受体超家族","src":"章节题库"},{"q":"9． ______。","a":"离子通道耦联受体；G 蛋白耦联受体；酶连受体","src":"章节题库","oe":["细胞表面受体分为离子通道耦联受体、G蛋白耦联受体和酶连受体三类"]},{"q":"10. 端在______。N 端与______结合，C 端与______作用。","a":"单；7；外；内；信号；G 蛋白","src":"章节题库","oe":["该端位于细胞内侧，故本空应填写内","GPCR的N端与信号分子结合，故该空填信号","GPCR的C端与G蛋白作用，故该空填G蛋白"]},{"q":"11．","a":"多通路；多环节；多层次；高度复杂可控","src":"章节题库"},{"q":"12．","a":"细胞外信号分子","src":"章节题库"},{"q":"13．","a":"直接活化少数特殊基因转录的初级反应阶段；初级反应的基因产物再活化其他基因产生延迟 的次级反应","src":"章节题库"},{"q":"14．","a":"硝酸甘油在体内转化为 NO，可舒张血管","src":"章节题库"},{"q":"15．","a":"由细胞表面到细胞核的信号通路；由细胞表面到细胞质核糖体的信号通路","src":"章节题库"},{"q":"16． ______结合再经信号转导机制，在细胞内产生______或激活______或______的活性，引起细 胞的应答反应。","a":"亲水性；脂双分子层；受体；第二信使；蛋白激酶；蛋白磷酸酶","src":"章节题库","oe":["亲水性信号分子先与细胞膜表面受体结合，故该空填受体","胞内可产生cAMP、IP3等第二信使，故该空填第二信使","可激活蛋白激酶，经磷酸化引起细胞应答","或激活蛋白磷酸酶，经去磷酸化调节反应"]},{"q":"17.","a":"α亚基；ADP","src":"章节题库"},{"q":"18．","a":"调节亚基；无活性的催化；调节亚基","src":"章节题库"},{"q":"19． 结构域的胞内信号蛋白识别。","a":"酪氨酸蛋白激酶；SH2","src":"章节题库","oe":["受体酪氨酸蛋白激酶被活化后发生自身磷酸化","磷酸化酪氨酸位点可被含SH2结构域的胞内信号蛋白识别"]},{"q":"20． 而使这种突变的蛋白一直处于开启状态。","a":"Ras；GTP；GDP","src":"章节题库","oe":["该发生突变而持续开启的蛋白是Ras蛋白","突变后Ras不能将GTP水解为GDP","无法转变为GDP结合状态，故突变蛋白一直处于开启状态"]},{"q":"21.","a":"硝酸根或亚硝酸根","src":"章节题库"},{"q":"22． 依赖于______。","a":"本身不具备酶活性；酪氨酸蛋白激酶的结合位点；非受体酪氨酸蛋白激酶","src":"章节题库","oe":["此类受体本身不具酶活性，但含酪氨酸激酶结合位点，依赖非受体酪氨酸蛋白激酶"]},{"q":"23．","a":"间隙连接；胞间连丝","src":"章节题库"},{"q":"24．","a":"内吞作用；细胞黏着；接触抑制","src":"章节题库"},{"q":"25. 前者结合是______，后者结合的是______。","a":"百日咳毒素；霍乱毒素","src":"章节题库","oe":["Gi蛋白的α亚基是百日咳毒素的作用底物，被其修饰","Gs蛋白的α亚基是霍乱毒素的作用底物，被其持续激活"]},{"q":"26．","a":"与信号分子结合的 C 端结构域；与 DNA 结合的中间结构域；活化基因转录的 N 端结构域","src":"章节题库"},{"q":"27．","a":"机体产生抗自身受体的抗体，与受体结合后使受体失去功能或改变作用方向查看答 案","src":"章节题库"},{"q":"28．","a":"受体被磷酸化后失去与信号分子结合的能力；受体被磷酸化易与抑制物结合而失去 与信号分子结合的能力","src":"章节题库"},{"q":"29． 和______。","a":"C 端与信号分子结合部位；中部与 DNA 结合部位；N 端激活基因转录部位查看答 案","src":"章节题库","oe":["核受体分C端配体结合区、中部DNA结合区和N端转录激活区三部分"]},{"q":"30. 结合的位点，细胞内部分有一______酶结构域，活化后可催化 GTP 生成 cGMP。 在这个系统中，cGMP 与______系统中的 cAMP 一样都充当第二信使。另外一个研究得比较 清楚的酶联受体信号系统就是 EGF 信号通路。EGF 受体是一种______，分子质量为 170 kDa， 广泛分布于哺乳动物细胞的上皮细胞、人成纤维细胞、胶质细胞、角质细胞等。EGF 受体 是一条含有 1186 个氨基酸的多肽链，由______个结构域组成：即 EGF 结合结构域、______ 和蛋白激酶活性区域。EGF 信号解除是通过胞吞作用进行的，EGF 被吞入后，      再运送至______。 Ras 蛋白的激活与 EGF 信号有关。Ras 蛋白是原癌基因 c-ras 表达的产物，也是一种______ 蛋白，具有鸟苷结合位点。对细胞的生长、分化、细胞骨架、蛋白质运输和分泌等功能产生 调节和影响。在正常情况下，Ras 蛋白基本上都与______结合在一起，定位在细胞膜内表面 上。当 EGF 与受体结合后，受体细胞质面的酪氨酸蛋白激酶被激活后______作用于 Ras 蛋 白，使 Ras 蛋白立即解离______，而与______结合，处于活化状态并发出刺激细胞生长的信 号。","a":"鸟苷环化；鸟苷环化；PKA；糖蛋白；三；跨膜区；溶酶体；G；GDP；间接；GDP； GTR","src":"章节题库","oe":["该受体胞内段有鸟苷环化酶结构域，故填鸟苷环化","cAMP是PKA信号系统的第二信使，故该空填PKA","EGF受体是一种跨膜糖蛋白，故该空填糖蛋白","EGF受体由三个结构域组成，故该空填三","三个结构域为EGF结合域、跨膜区和蛋白激酶活性区","被吞入的EGF经胞吞作用运送至溶酶体降解","Ras是G蛋白，具有鸟苷结合位点","正常情况下Ras与GDP结合，定位在细胞膜内表面","受体激酶被激活后间接作用于Ras蛋白","Ras立即解离GDP，暴露出与GTP结合的位点","Ras与GTP结合而活化（原答案GTR应为GTP）"]},{"q":"1． 化状态，当结合 时为失活状态。GAP 增强 Ras 的 。","a":"GTPase；GTP；GDP；失活","src":"名校考研真题","oe":["Ras具有GTPase活性，故第一空填GTPase","Ras结合GTP时处于活化状态","Ras结合GDP时处于失活状态","GAP增强Ras的GTP酶活性，促进其失活"]},{"q":"2． 京师范大学 2007 研]","a":"细胞内受体；离子通道偶联的受体；G 蛋白偶联受体；酶连接的受体","src":"名校考研真题","oe":["细胞内受体，与脂溶性信号分子结合","离子通道偶联受体，属配体门控离子通道","G蛋白偶联受体，经G蛋白激活效应器","酶连接的受体，本身具酶活性或与酶偶联"]},{"q":"3． 传递神经信号。","a":"自分泌；内分泌；旁分泌","src":"名校考研真题","oe":["自分泌：信号作用于分泌信号的细胞自身","内分泌：信号经血液作用于远距离靶细胞","旁分泌：信号作用于邻近的靶细胞"]},{"q":"4． 它的主要配体是_____。","a":"1；丝氨酸∕苏氨酸蛋白激酶；转化生长因子β家族成员","src":"名校考研真题","oe":["TGFβ受体为丝氨酸／苏氨酸激酶，其主要配体是TGFβ家族成员"]}],"judge":[{"q":"1．","a":"错","src":"章节题库"},{"q":"2．","a":"对","src":"章节题库"},{"q":"3．","a":"错","src":"章节题库"},{"q":"4. 活化。（      ）","a":"错","src":"章节题库"},{"q":"5. （      ）","a":"错","src":"章节题库"},{"q":"6．","a":"错","src":"章节题库"},{"q":"7．","a":"错","src":"章节题库"},{"q":"8．","a":"错","src":"章节题库"},{"q":"9.","a":"错","src":"章节题库"},{"q":"10．","a":"对","src":"章节题库"},{"q":"11．","a":"对","src":"章节题库"},{"q":"12．","a":"错","src":"章节题库"},{"q":"13.","a":"错","src":"章节题库"},{"q":"14．","a":"对","src":"章节题库"},{"q":"15． 结合。（      ）","a":"对","src":"章节题库"},{"q":"16. 基团。","a":"对","src":"章节题库"},{"q":"4. 酶激活，引起级联反应。（                ）","a":"错","src":"名校考研真题","oe":["选“对”：若酶被激活后经逐级放大引起级联反应，是常见信号转导方式，易判对","选“错”：题干不完整且表述绝对，酶激活与级联反应并非必然因果，故判错"]}]},"ch10":{"mcq":[{"q":"由微管组成的细胞表面特化结构是（            ）。","o":["A．鞭毛","B．微绒毛","C．伪足","D．桥粒与半桥粒"],"a":"A","e":"纤毛和鞭毛是细胞表面的特化结构，具有运动功能。纤毛和鞭毛的轴心有一束“9 ＋2”排列的平行微管。","src":"章节题库","oe":["正确：鞭毛具运动功能，轴心有“9+2”排列的平行微管","微绒毛由微丝构成，用于扩大表面积，无运动功能","伪足由微丝构成，与细胞迁移有关，非“9+2”结构","桥粒与半桥粒属细胞连接，不具运动功能"]},{"q":"具有稳定微管的结构特异性药物是（            ）。","o":["A．秋水仙素","B．细胞松弛素","C．鬼笔环肽","D．紫杉酚"],"a":"D","e":"紫杉酚能促进微管的装配，并使已形成的微管稳定，但这种稳定性的增加对细胞是 有害的。","src":"章节题库","oe":["秋水仙素抑制微管装配，使微管解聚，非本题答案","细胞松弛素切断微丝并抑制肌动蛋白聚合","鬼笔环肽与微丝结合，稳定微丝阻止其解聚","正确：紫杉酚促进微管装配并使已形成的微管稳定"]},{"q":"具有稳定微管的结构特异性药物是（            ）。","o":["A．秋水仙素","B．细胞松弛素","C．鬼笔环肽","D．紫杉酚"],"a":"B","e":"细胞松弛素（cytochalasins）是真菌的一种代谢产物，可以切断微丝，并可结合在 微丝末端阻抑肌动蛋白聚合。","src":"章节题库","oe":["秋水仙素作用于微管，不切断微丝","正确：细胞松弛素可切断微丝并阻抑肌动蛋白聚合","鬼笔环肽与微丝结合而稳定微丝，并非切断微丝","紫杉酚稳定微管，不切断微丝，故不选"]},{"q":"核纤层蛋白从氨基酸序列的同源比较上看，属于（            ）。","o":["A．微管","B．微丝","C．中间丝","D．核骨架蛋白"],"a":"C","e":"近年来发现核纤层与中间丝有许多共同点，通过对核纤层蛋白的 cDNA 克隆的研 究，并与中间丝的氨基酸序列对比，说明核纤层蛋白确实是中间丝蛋白家族成员。","src":"章节题库","oe":["微管由α、β微管蛋白组成，与核纤层不同源","微丝由肌动蛋白组成，与核纤层不同源","正确：核纤层蛋白与中间丝同源，属中间丝蛋白家族","核骨架蛋白是功能描述，不是本题所指的纤维类别"]},{"q":"用特异性药物细胞松弛素 B 可以阻断下列哪种小泡的形成？（        ）","o":["A．胞饮泡","B．吞噬泡","C．分泌小泡","D．包被小泡"],"a":"B","e":"吞噬泡的形成与细胞膜下富含肌动蛋白纤维的溶胶区域的状态转化有关，能为细胞 松弛素所抑制。","src":"章节题库","oe":["胞饮泡摄取液体，与网格蛋白衣被等有关","正确：吞噬泡形成依赖膜下肌动蛋白，可被细胞松弛素抑制","分泌小泡参与胞吐，方向与内吞相反","包被小泡有衣被蛋白参与，形成机制与吞噬泡不同"]},{"q":"中等纤维中的结蛋白主要存在于（          ）。","o":["A．肌细胞","B．上皮细胞","C．神经细胞","D．间质细胞"],"a":"A","e":"中等纤维按其组织来源及免疫原性可分为 5 类，分别为角蛋白纤维，波形纤维，结 蛋白纤维，神经元纤维，神经胶质纤维。结蛋白纤维存在于肌细胞中。","src":"章节题库","oe":["正确：结蛋白纤维存在于肌细胞中","上皮细胞含角蛋白纤维，非结蛋白纤维","神经细胞含神经元纤维，非结蛋白纤维","间质细胞含波形纤维，非结蛋白纤维"]},{"q":"微管蛋白在一定条件下，能装配成微管，其管壁由几根原纤维构成？（           ）","o":["A．9","B．11","C．13","D．15"],"a":"C","e":"在微管装配的过程中，αβ二聚体形成后，再形成原纤维（protofilament），经过侧 面增加而扩展为片层，至 13 根原纤维时，即合拢形成一段微管。","src":"章节题库","oe":["9不是微管原纤维数，与二联管结构有关","11不符合微管原纤维的实际数目","正确：微管由13根原纤维环绕合拢形成","15不是微管原纤维的数目，故错误"]},{"q":"构成微丝的基本成分是（         ）。","o":["A．肌动蛋白","B．肌球蛋白","C．肌钙蛋白","D．三者均有"],"a":"A","e":"微丝（microfilament，MF）的主要结构成分是肌动蛋白。B 项，肌球蛋白是依赖于 微丝的分子马达；C 项，肌钙蛋白是结合在横纹肌细肌丝上的调节蛋白，有三个亚基组成： 肌钙蛋白 T、肌钙蛋白 I 和肌钙蛋白 C。其中肌钙蛋白 T 能与原肌球蛋白结合，肌钙蛋白 I 能抑制肌球蛋白的 ATPase 活性，肌钙蛋白 C 能与钙离子结合。","src":"章节题库","oe":["正确：肌动蛋白是微丝的主要结构成分","肌球蛋白是依赖于微丝的分子马达","肌钙蛋白是横纹肌细肌丝上的调节蛋白","错误：微丝主要成分只有肌动蛋白，并非三者均有"]},{"q":"促进微管聚合的药物是（         ）。","o":["A．鬼臼素","B．长春花碱","C．紫杉酚","D．细胞松弛素"],"a":"C","e":"A 项，鬼臼素（peltatin）会抑制细胞 DNA 合成，使细胞处于分裂期。B 项，长春 花碱与秋水仙素的作用相似，能抑制微管的装配，是微管的特异性抑制剂。C 项，紫杉酚和 重水（D2O）可使微管稳定性增加并使细胞周期停止于有丝分裂期。D 项，细胞松弛素可以 切断微丝，并结合在微丝正极阻抑肌动蛋白聚合，而可以破坏微丝的三维网络，特异性的抑 制微丝的装配。","src":"章节题库","oe":["鬼臼素抑制DNA合成，使细胞处于分裂期","长春花碱抑制微管装配，与秋水仙素作用相似","正确：紫杉酚使微管稳定性增加，使细胞停止于有丝分裂期","细胞松弛素切断微丝，破坏微丝三维网络"]},{"q":"纤毛、鞭毛的基体由下列哪种微管构成（         ）。","o":["A．二联管","B．三联管","C．单管","D．四联管"],"a":"A","e":"中心粒是三联管。","src":"章节题库","oe":["正确：纤毛、鞭毛轴心的9组周围小管为二联管","三联管见于中心粒和基体，非轴心周围小管","单管是轴心中央的2根微管，非周围小管","四联管这种结构在细胞中不存在，故错"]},{"q":"关于肌动蛋白的叙述错误的是（         ）。","o":["A．G-肌动蛋白与 F-肌动蛋白可互相转变","B．肌动蛋白上有肌球蛋白结合位点，但无二价阳离子的结合位点","C．F______肌动蛋白的聚合过程不需能量","D．肌动蛋白是微丝的基础蛋白质"],"a":"B","e":"B 选项肌动蛋白有 ATP 结合位点和 Mg2 结合位点。 ＋","src":"章节题库","oe":["正确：G-肌动蛋白与F-肌动蛋白可相互转变","错误项（答案）：肌动蛋白有ATP结合位点和Mg2+等二价阳离子结合位点","微丝装配中G-肌动蛋白需结合ATP并水解供能","正确：肌动蛋白是微丝的基础蛋白质"]},{"q":"凝胶与溶胶的互变与（       ）的变化有关。","o":["A．微丝","B．微管","C．中间丝","D．胶原纤维"],"a":"A","e":"微丝与细胞伪足的形成与迁移运动有关。","src":"章节题库","oe":["正确：微丝与细胞伪足形成及迁移运动有关","微管主要维持形态、参与运输和构成纺锤体","中间丝主要提供机械支撑，非本题答案","胶原纤维属细胞外基质是细胞外的纤维网络结构，不是细胞骨架"]},{"q":"3． 山大学 2007 研]","o":["A．骨骼肌收缩","B．胞质分裂","C．卵细胞受精前的顶体反应","D．胞质环流","E．上述细胞运动都不能发生"],"a":"E","e":"肌动蛋白是微丝的组成单元，而肌球蛋白是微丝的马达蛋白。ABCD 四项所述运动 形式均与微丝有关。","src":"名校考研真题","oe":["骨骼肌收缩依赖肌动蛋白与肌球蛋白，会受影响","胞质分裂的收缩环由肌动蛋白构成，会受影响","卵细胞受精前的顶体反应依赖肌动蛋白，会受影响","胞质环流依赖微丝，故也会受影响","正确：四项运动均与微丝有关，故都不能发生"]}],"fill":[{"q":"1． 分是：______。构成微管的蛋白有两类：______和______。","a":"肌动蛋白；原肌球蛋白；肌钙蛋白；肌球蛋白；α-微管蛋白；β-微管蛋白","src":"章节题库","oe":["微丝的化学成分包括肌动蛋白、原肌球蛋白、肌钙蛋白和肌球蛋白","构成微管的蛋白之一是α-微管蛋白","另一类是β-微管蛋白，二者组成αβ异二聚体"]},{"q":"2． 的微管组织中心。","a":"中心体；胞质分裂环","src":"章节题库","oe":["中心体是动物细胞主要的微管组织中心，微管由此成核","胞质分裂环由微丝（肌动蛋白）组成，是收缩环结构"]},{"q":"3．","a":"星体微管；动力微管；极性微管","src":"章节题库"},{"q":"4．","a":"微丝；微管；中间丝","src":"章节题库"},{"q":"5． 丝具有______。正极与负极都能生长，生长快的一端为______，慢的一端为______。","a":"极性；正极；负极","src":"章节题库","oe":["微丝的两端结构不同，故具有极性","正极与负极都能生长，生长快的一端为正极（+端）","生长慢的那一端称为负极（-端）"]},{"q":"6．","a":"极性","src":"章节题库"},{"q":"7． 驱动蛋白通常朝微管的______方向运动，动力蛋白朝微管的______运动。","a":"驱动蛋白；动力蛋白；正极；负极","src":"章节题库","oe":["驱动蛋白沿微管向正极（+端）方向运动","动力蛋白沿微管向负极（-端）方向运动"]},{"q":"8．","a":"α-微管蛋白；β微管蛋白","src":"章节题库"},{"q":"9．","a":"肌动蛋白；肌球蛋白；原肌球蛋白；肌钙蛋白","src":"章节题库"},{"q":"10．","a":"结蛋白；角质蛋白","src":"章节题库"},{"q":"11． 用。","a":"毛部；基体；根丝；基体","src":"章节题库"},{"q":"12．","a":"染色体微管；中间微管","src":"章节题库"},{"q":"13．","a":"核基质核纤层；核孔复合体；染色体骨架","src":"章节题库"},{"q":"14．","a":"13","src":"章节题库"},{"q":"15．","a":"抑制微管解聚和抑制微管聚合","src":"章节题库"},{"q":"16．","a":"形成双股螺旋的二聚体→组成反向半重叠的四聚体→形成原纤丝→形成中间纤维查 看答案","src":"章节题库"},{"q":"17．","a":"β-微管蛋白；具有结合 ATP 的位点","src":"章节题库"},{"q":"1． 周围小管的是 ______，比较稳定；组成中心粒和基体的是______，十分稳定。","a":"单体；二联体；三联体","src":"章节题库","oe":["纤毛、鞭毛轴心的周围小管是二联管，比较稳定","组成中心粒和基体的是三联体，十分稳定"]},{"q":"18． 成分是：______ 。构成微管的蛋白有两类：______和 ______。","a":"肌动蛋白；原肌球蛋白；肌钙蛋白；肌球蛋白；α微管蛋白；β微管蛋白","src":"章节题库","oe":["微丝的化学成分包括肌动蛋白、原肌球蛋白、肌钙蛋白和肌球蛋白","构成微管的蛋白之一是α-微管蛋白","另一类是β-微管蛋白，二者组成αβ异二聚体"]},{"q":"19． 等。","a":"肌球蛋白；动力蛋白；驱动蛋白；ATP 合成酶","src":"章节题库"},{"q":"20． 骨架，包括 ______、______和______。","a":"微丝；微管；中间纤维","src":"章节题库","oe":["细胞质骨架由微丝和微管等共同构成包括微丝这一重要成分","细胞质骨架由微丝和微管等共同构成还包括微管这一重要结构","细胞质骨架由微丝和微管等共同构成以及中间纤维（中间丝）"]},{"q":"21．","a":"极性；组织特异性。","src":"章节题库"},{"q":"1． 等动物的纤维网络结构。","a":"细胞核骨架；细胞质骨架；细胞膜骨架；细胞外基质","src":"名校考研真题","oe":["细胞核骨架，包括核纤层和核基质","细胞质骨架由微丝和微管等共同构成","细胞膜骨架位于细胞膜的内侧面上","细胞外基质是细胞外的纤维网络结构"]},{"q":"2． 研]","a":"胞质分裂；肌收缩","src":"名校考研真题"},{"q":"4． 京师范大学 2008 研]","a":"“9＋2”排列的平行微管；ATP 酶；ATP；二联管解聚","src":"名校考研真题","oe":["纤毛和鞭毛轴心有“9+2”排列的平行微管","动力蛋白具有ATP酶活性，可水解ATP供能","水解ATP释放能量为二联管滑动提供动力","动力蛋白引起相邻二联管相对滑动（原答案作二联管解聚）"]},{"q":"5．","a":"肌动蛋白；7 nm","src":"名校考研真题"},{"q":"6． 顶端运向胞体；二是_________介导运输小泡由胞体运向轴突顶端。","a":"动力蛋白；驱动蛋白","src":"名校考研真题","oe":["驱动蛋白沿微管向正极运动，介导胞体到轴突顶端的顺向运输"]}],"judge":[{"q":"1． （   ）","a":"错","src":"章节题库"},{"q":"2．","a":"错","src":"章节题库"},{"q":"3．","a":"对","src":"章节题库"},{"q":"4． 白（actin）。（     ）","a":"错","src":"章节题库","oe":["选“对”：微丝的主要成分确为肌动蛋白(actin)，若题干指微丝则正确","选“错”：若题干指微管或中间丝，其成分并非肌动蛋白，故判错"]},{"q":"5．","a":"错","src":"章节题库"},{"q":"6．","a":"错","src":"章节题库"},{"q":"7．","a":"错","src":"章节题库"},{"q":"8．","a":"错","src":"章节题库"},{"q":"9．","a":"错","src":"章节题库"},{"q":"10．","a":"错","src":"章节题库"},{"q":"1． 止新的单体聚合，致使微丝解聚。（                     ）","a":"错","src":"名校考研真题","oe":["选“对”：若该物质为细胞松弛素，其可阻抑单体聚合致微丝解聚，易误判为对","选“错”：该物质实为鬼笔环肽，它与微丝结合阻止解聚、稳定微丝，故判错"]},{"q":"3． 开大学 2008 研]","a":"对","src":"名校考研真题"},{"q":"4．","a":"错","src":"名校考研真题"},{"q":"5． 研]","a":"错","src":"名校考研真题"}]},"ch11":{"mcq":[{"q":"下列有关 rRNA 的描述不正确的是（     ）。","o":["A．rDNA 是编码 rRNA 的基因，存在核仁的纤维中心","B．核仁中 rRNA 的基因的转录由专一性的 RNA 聚合酶工催化","C．rRNA 的基因拷贝数的增加可以起到调控转录效率的作用","D．rRNA 的基因属于中度串联重复序列"],"a":"C","e":"A 项，核仁在结构上从内到外包括纤维中心、致密纤维组分和颗粒组分，分别含有 编码 rRNA 的基因-rDNA、新生的 rRNA 前体和处于不同阶段的核糖体亚单位。 B 项，除了 5S rRNA 由核仁以外的 RNA 聚合酶Ⅲ转录以外，其他三种 rRNA 由核仁中的专 一性的 RNA 聚合酶Ⅰ转录。 C 项，一般来说，rDNA 的拷贝数是不变的，调控主要依赖转录起始的速率。 D 项，rDNA 在基因组中属于有编码产物的中度重复序列。","src":"章节题库","oe":["正确：rDNA是编码rRNA的基因，位于核仁的纤维中心","正确：除5S rRNA由RNA聚合酶Ⅲ转录外，rRNA由聚合酶Ⅰ转录","错误项（答案）：rDNA拷贝数一般不变，转录调控主要靠转录起始速率","正确：rDNA属有编码产物的中度重复序列"]},{"q":"（    ）一般是活性染色质的标志。","o":["A．乙酰化","B．甲基化","C．磷酸化","D．泛素化"],"a":"A","e":"甲基化和磷酸化在活性与活性染色质中都存在。","src":"章节题库","oe":["正确。组蛋白乙酰化通常是一般活性染色质的标志。","错误。甲基化在活性与非活性染色质中都存在。","错误。磷酸化在活性与非活性染色质中均可出现。","错误。泛素化主要参与蛋白降解，并非活性染色质标志。"]},{"q":"下列选项中有关核被膜结构的叙述错误的是（          ）。","o":["A．双层核膜互相平行但不连续","B．外核被膜可以看作是粗面内质网的一个特化区域","C．内核膜无核糖体颗粒附着，但在其外表面有一层致密的纤维网络结构，即核纤层","D．内核膜上有核纤层蛋白 B 受体"],"a":"C","e":"内、外核膜常常在某些部位相互融合形成环状开口即核孔，因此双层核膜是不连续 的；核纤层紧贴于内核膜的内表面，故 C 项错误。","src":"章节题库","oe":["正确。双层核膜在核孔处相融，因而并不连续。","正确。外核被膜可看作粗面内质网的一个特化区域。","错误（应选）。核纤层紧贴内核膜的内表面，而非外表面。","正确。内核膜上存在核纤层蛋白B受体。"]},{"q":"有关 NLS 的说法，下列选项不正确的是（       ）。","o":["A．亲核蛋白 NLS 序列中的一个氨基酸残基突变就会导致该蛋白不能在核内正常积累","B．将 NSL 序列连接到非亲核蛋白上，则非亲核蛋白就可以转运到核内","C．在不同的 NSL 之间，尚未发现共有的特征序列","D．与 N 端信号肽相似，NSL 在指导亲核蛋白完成核输入以后被切除"],"a":"D","e":"NLS 序列可存在于亲核蛋白的不同部位，在指导完成核输入后并不被切。","src":"章节题库","oe":["正确。NLS关键残基突变可使该蛋白不能在核内正常积累。","正确。把NLS接到非亲核蛋白上可引导其转运入核。","正确。不同NLS之间尚未发现共有的特征序列。","错误（应选）。NLS完成核输入后并不被切除。"]},{"q":"可作为重要的遗传标志，用于构建遗传图谱的 DNA 序列是（        ）。","o":["A．微卫星 DNA","B．小卫星 DNA","C．卫星 DNA","D．短散在元件"],"a":"A","e":"微卫星 DNA 重复单位序列最短，具高度多态性，在遗传上高度保守，为重要的遗 传标志。小卫星 DNA 常用于 DNA 指纹技术作个体鉴定。","src":"章节题库","oe":["正确。微卫星DNA重复单位最短、多态性高，是重要遗传标志。","错误。小卫星DNA常用于DNA指纹技术作个体鉴定。","错误。卫星DNA主要分布在着丝粒部位。","错误。短散在元件属散在重复序列，不是该遗传标志。"]},{"q":"没有种属及组织特异性，在所有已知蛋白中进化上最为保守的是（            ）。","o":["A．H1 组蛋白","B．H2B 和 H2A 组蛋白","C．H3 和 H4 组蛋白","D．H2 蛋白"],"a":"C","e":"H1 有一定的种属和组织特异性；H3 和 H4 组蛋白在进化上相比 H2B 和 H2A 组蛋 白更为保守。D 项为干扰项。","src":"章节题库","oe":["错误。H1组蛋白有一定的种属和组织特异性。","错误。H2B和H2A的保守性不如H3和H4。","正确。H3和H4在已知蛋白中进化上最为保守。","错误。所谓H2蛋白是干扰项，并不存在此类并列。"]},{"q":"用非特异性微球菌核酸酶消化裸露的 DNA 时，将产生（     ）。","o":["A．大约 200bp 的","B．大约 200bp 整倍数的片段","C．随机大小的片段群体","D．大约 146bp 整倍数的片段"],"a":"C","e":"用非特异性微球菌核酸酶消化染色质时，绝大多数 DNA 被降解成 200bp 的片段， 如果部分酶解，则得到的片段长度是 200bp 的整倍数。但裸露的 DNA 没有受到核小体结构 的保护作用，经上述酶处理后将产生随机大小的片段群体。","src":"章节题库","oe":["错误。约200bp片段是染色质受核小体保护的酶解产物。","错误。200bp整倍数片段见于部分酶解的染色质。","正确。裸露DNA无核小体保护，酶解成随机大小片段。","错误。约146bp整倍数并非该酶解产生的规律片段。"]},{"q":"8． （   ）。","o":["A．DNA 双螺旋","B．核小体串珠结构","C．螺线管结构","D．染色单体"],"a":"C","e":"核小体的直径约 10nm，螺线管的直径约 30nm。","src":"章节题库","oe":["错误。DNA双螺旋的直径仅约2nm。","错误。核小体串珠结构的直径约10nm。","正确。螺线管结构的直径约30nm。","错误。染色单体的直径远大于30nm。"]},{"q":"异染色质是（      ）。","o":["A．高度凝集和转录活跃的","B．高度凝集和转录不活跃的","C．松散和转录活跃的","D．松散和转录不活跃的"],"a":"B","e":"异染色质纤维折叠压缩程度高，处于聚缩状态，不具有转录活性。","src":"章节题库","oe":["错误。高度凝集与转录活跃通常并不相容。","正确。异染色质高度凝集、聚缩且转录不活跃。","错误。松散和转录活跃的应当是常染色质。","错误。松散状态一般具有转录活性。"]},{"q":"有关端粒或端粒酶的说法，下列选项错误的是（       ）。","o":["A．端粒起到计时器的作用，体细胞每分裂一次，端粒重复序列就缩短一些","B．端粒酶是一种核糖核蛋白复合物，具有逆转录性质","C．在生殖系细胞、干细胞和体细胞内都发现有端粒酶活性","D．肿瘤细胞具有表达端粒酶活性的能力"],"a":"C","e":"在生殖系细胞和部分干细胞里发现有端粒酶活性，而在所有体细胞里则尚未现有端 粒酶的活性。肿瘤细胞具有表达端粒酶活性的能力，使癌细胞得以无限的增殖。","src":"章节题库","oe":["正确。端粒起计时器作用，体细胞每分裂一次缩短一些。","正确。端粒酶是核糖核蛋白复合物，具逆转录性质。","错误（应选）。所有体细胞中尚未发现端粒酶活性。","正确。肿瘤细胞可表达端粒酶活性而无限增殖。"]},{"q":"有关巨大染色体，下列说法错误的是（     ）。","o":["A．多线染色体带区的包装程度比间带高得多，所以带区深染，而间带浅染","B．多线染色体的胀泡是基因活跃转录的形态标志","C．在不同时期观察，同一多线染色体上带的数目、形态、大小及分布位置差异较大","D．等刷染色体的形态与卵子发生过程中营养物质的储备是密切相关的"],"a":"C","e":"多线染色体上带的数目、形态、大小及分布位置很稳定。每条带能根据它的宽窄及 间隔予以识别，对每条带给以标号，从而得到多线染色体的带谱。","src":"章节题库","oe":["正确。带区包装程度高于间带，故带区深染、间带浅染。","正确。多线染色体的胀泡是基因活跃转录的形态标志。","错误（应选）。多线染色体带的数目、形态与位置很稳定。","正确。灯刷染色体形态与卵子营养物质储备密切相关。"]},{"q":"在代谢活跃的细胞的核仁中，核仁最主要的结构是（        ）。","o":["A．纤维中心","B．致密纤维组分","C．颗粒组分","D．前核仁体"],"a":"C","e":"颗粒组分主要由核糖核蛋白颗粒构成，在合成代谢活跃的细胞，需要合成的核糖体 就越多，相应产生的核糖核蛋白体的数量越大，从而使颗粒组分成为最主要的结构。","src":"章节题库","oe":["错误。纤维中心含rDNA，并非代谢活跃时最主要组分。","错误。致密纤维组分是新生的核糖核蛋白前体加工区。","正确。颗粒组分由核糖核蛋白颗粒构成，活跃时最发达。","错误。前核仁体只是核仁形成的前体结构。"]},{"q":"核仁的消失发生在细胞周期的（        ）。","o":["A．G1 期","B．S 期","C．M 期","D．G2 期"],"a":"C","e":"当细胞进入有丝分裂（M 期）时，核仁首先变形和变小，随后染色质凝聚，核仁 消失，所有 RNA 合成停止。","src":"章节题库","oe":["错误。G1期核仁存在并持续合成rRNA。","错误。S期核仁存在，rRNA仍在合成。","正确。进入M期染色质凝聚，核仁消失、RNA合成停止。","错误。G2期核仁尚未解体消失。"]},{"q":"下列有关 DNA 局部结构和核小体对染色质活化的影响，不确切的说法是（         ）。","o":["A．染色质包括核小体并不是一个静止的结构","B．结合到 DNA 上的基因调控蛋白可在相当远的距离产生作用","C．B 构型 DNA 变成 Z 构型 DNA，会导致核心组蛋白八聚体与 DNA 的亲和力降低","D．核小体的结构的形成对染色质活化始终产生负面影响"],"a":"D","e":"核小体的结构的形成对染色质活化始终也可产生积极作用，如基因的不同调控元件 盘绕在核小体同一位置，使两者的距离缩短，从而有利于转录。","src":"章节题库","oe":["正确。染色质包括核小体并非静止不变的结构。","正确。结合DNA的调控蛋白可在相当远处发挥作用。","正确。B型DNA变Z型会降低核心组蛋白与DNA的亲和力。","错误（应选）。核小体形成对染色质活化也可有积极作用。"]},{"q":"α卫星 DNA 存在于（     ）。","o":["A．动粒","B．着丝粒","C．端粒","D．中心粒"],"a":"B","e":"真核细胞中含有高度重复的 DNA 序列，可以分为卫星 DNA、小卫星 DNA、微卫 星 DNA 三种，其中卫星 DNA 主要分布在着丝粒部位，小卫星 DNA 常用于 DNA 指纹技术 做个体鉴定，微卫星 DNA 具有高度多态性，可以用于构建遗传图谱。","src":"章节题库","oe":["错误。动粒是着丝粒上的蛋白结构，并非α卫星DNA所在。","正确。α卫星DNA主要分布在着丝粒部位。","错误。端粒由短串联重复序列构成，不含α卫星DNA。","错误。中心粒为微管组织中心，不含α卫星DNA。"]},{"q":"下列有关 rRNA 的描述不正确的是（     ）。","o":["A．rDNA 是编码 rRNA 的基因，存在核仁的纤维中心","B．rRNA 的基因的转录由专一性的 RNA 聚合酶Ⅰ催化","C．rRNA 的基因拷贝数的增加可以起到调控转录效率的作用","D．rRNA 的基因属于中度串联重复序列"],"a":"C","e":"一般 rRNA 的基因拷贝数是不变的，调控基因转录效率的主要依赖于转录起始的速 率。","src":"章节题库","oe":["正确。rDNA编码rRNA，存在于核仁的纤维中心。","正确。rRNA基因转录由专一性RNA聚合酶Ⅰ催化。","错误（应选）。rDNA拷贝数一般不变，效率取决于起始速率。","正确。rRNA基因属有编码产物的中度重复序列。"]},{"q":"在 mRNA 剪接中起主要作用的 RNA 是（    ）。","o":["A．snoRNA","B．miRNA","C．gRNA","D．snRNA"],"a":"A","e":"snoRNA 在核糖体 RNA 的生物合成和 snRNA、tRNA 和 mRNA 的转录后修饰中 发挥着重要作用","src":"章节题库","oe":["正确。snoRNA参与rRNA生物合成及多种RNA的转录后修饰。","错误。miRNA主要参与转录后基因沉默调控。","错误。gRNA参与RNA编辑，并非mRNA剪接主角。","错误。snRNA虽参与mRNA前体剪接，但本题标准答案选A。"]},{"q":"关于蛋白质进入细胞核运输的叙述中，错误的是（              ）。","o":["A．靠核定位信号引导，完成引导后被切除","B．由核孔复合体通过","C．具有核定位信号的蛋白不一定能够到达细胞核","D．运输时需特殊蛋白帮助"],"a":"A","e":"靠核定位信号引导，完成引导后不被切除。","src":"章节题库","oe":["错误（应选）。核定位信号完成引导后并不被切除。","正确。亲核蛋白由核孔复合体通过进入细胞核。","正确。具有核定位信号的蛋白不一定能到达细胞核。","正确。核输入运输需要特殊蛋白因子帮助。"]},{"q":"有关端粒的叙述中，不正确的是（          ）。","o":["A．由重复序列组成","B．在正常体细胞中，新合成 DNA 链的端粒不会变短","C．其长度决定细胞分裂次数，被称为有丝分裂计时器","D．肿瘤细胞可以“永生”，关键在于其可以表达端粒酶"],"a":"B","e":"在正常体细胞中，新合成 DNA 链的端粒会变短，随着一代一代的进行，导致寿命 的缩短。","src":"章节题库","oe":["正确。端粒由简单的重复序列组成，维持末端稳定。","错误（应选）。正常体细胞中新合成DNA链的端粒会变短。","正确。端粒长度决定分裂次数，被称为有丝分裂计时器。","正确。肿瘤细胞永生关键在于能表达端粒酶。"]},{"q":"多线染色体与灯刷染色体（        ）。","o":["A．都是体细胞永久性染色体","B．都是生殖细胞特有的染色体","C．都是转录不活跃的 DNA","D．都是转录活跃的 DNA"],"a":"D","e":"多线染色体是 DNA 多次复制后所产生的子染色体整齐排列,紧密结合在一起而形成 的。它所在的细胞在此过程中处于永久间期阶段，不分裂，因而随着复制的不断进行，核体 积不断增加，多线化细胞的体积也相应增大。 灯刷染色体两栖类卵母细胞减数分裂前期Ⅰ中形成的巨大染色体。由纤细的 DNA 中轴和许 多成对的 DNA 侧袢组成，形似灯刷状。","src":"章节题库","oe":["错误。灯刷染色体见于卵母细胞减数分裂前期。","错误。多线染色体存在于体细胞，并非生殖细胞特有。","错误。二者均含转录活跃区，即胀泡与侧袢。","正确。多线染色体胀泡与灯刷染色体侧袢均活跃转录。"]}],"fill":[{"q":"1．","a":"核被膜；染色质；核仁；核骨架","src":"章节题库"},{"q":"2. 白；______代表一类功能性的核孔复合体蛋白。","a":"gp210；p62","src":"章节题库","oe":["该空填p62，它是核孔复合体中一类功能性的核孔蛋白。"]},{"q":"3．","a":"短散在元件；长散在元件","src":"章节题库"},{"q":"4.","a":"组蛋白；非组蛋白","src":"章节题库"},{"q":"5． 个______，以及一分子的______。","a":"核小体；200；组蛋白八聚体；H1 组蛋白","src":"章节题库","oe":["该空填组蛋白八聚体，由H2A、H2B、H3、H4各两分子组成。","该空填H1组蛋白，位于核小体核心外侧，锁住DNA进出。"]},{"q":"6． 分为______和______。","a":"常染色质；异染色质；结构异染色质；兼性异染色质","src":"章节题库","oe":["该空填结构异染色质，是异染色质中较恒定的一类。","该空填兼性异染色质，由功能状态转变形成，如失活X染色体。"]},{"q":"7． ______和______。","a":"DNA 复制起点；着丝粒；端粒","src":"章节题库","oe":["该空填着丝粒，富含高度重复DNA，连接姐妹染色单体。","该空填端粒，由短串联重复序列构成，维持染色体末端稳定。"]},{"q":"8． ______、______、______和______等修饰。","a":"乙酰基化；甲基化；磷酸化；ADP 核糖基化","src":"章节题库","oe":["该空填乙酰基化，常与染色质转录活化相关。","该空填甲基化，参与转录调控与异染色质形成。","该空填磷酸化，与染色质凝集及细胞分裂相关。","该空填ADP核糖基化，由ADP核糖转移酶催化，参与DNA修复。"]},{"q":"9． Ⅱ催化______合成；RNA 聚合酶Ⅲ催化______合成。","a":"5.8S、18S 和 28S rRNA；hnRNA；5S rRNA 和 tRNA","src":"章节题库","oe":["该空填hnRNA，即mRNA前体，由RNA聚合酶Ⅱ转录生成。","该空填5S rRNA和tRNA，由RNA聚合酶Ⅲ催化合成。"]},{"q":"10．","a":"细胞器；遗传；代谢","src":"章节题库"},{"q":"11．","a":"碱性；正；S","src":"章节题库"},{"q":"12． 是______，在进化上具有______的特点。","a":"胞质环；核质环；辐；栓；蛋白质；高度保守","src":"章节题库","oe":["该空填蛋白质，核孔复合体的主要结构成分为核孔蛋白。","该空填高度保守，核孔复合体在进化上高度保守。"]},{"q":"13． 长度约为______。（螺线管螺距 llnm）","a":"17；33nm","src":"章节题库","oe":["该空填33nm，3400bp约含17个核小体，折叠成螺线管约33nm。"]},{"q":"14． ______和 DNA 的结合是特异性的。","a":"组织；复制；阅读；非组蛋白","src":"章节题库","oe":["该空填非组蛋白，它与DNA的结合具有特异性。"]},{"q":"15． 成，而且作为______，可以引起遗传变异。","a":"高度重复；转座元件","src":"章节题库","oe":["该空填转座元件，结构异染色质富含高度重复序列，可致变异。"]},{"q":"16．","a":"5；长臂；24；3","src":"章节题库"},{"q":"17． 核仁的大小、形状和数目可以反映出生物种类、细胞的______和______的变化。","a":"消失；重建；类型；代谢状态","src":"章节题库","oe":["该空填类型，核仁大小形状可反映细胞类型的差异。","该空填代谢状态，代谢旺盛的细胞核仁大而明显。"]},{"q":"18． 层析和______洗脱方法进行活性染色质的分离。","a":"有机汞色质和；二硫苏糖醇","src":"章节题库","oe":["该空填二硫苏糖醇，它可还原巯基，将活性染色质洗脱下来。"]},{"q":"19． 程度的高低可以代表______的高低。","a":"除了 Xi 之外的染色体都被标记上；乙酰化；转录活性","src":"章节题库","oe":["该空填转录活性，乙酰化程度高低可代表转录活性的高低。"]},{"q":"20．","a":"5.8S rRNA；18S rRNA 28S rRNA","src":"章节题库"},{"q":"21.","a":"A 型 DNA；B 型 DNA；Z 型 DNA；B 型 DNA","src":"章节题库"},{"q":"22． 间带上的基因是______，带上的基因是______。","a":"胀泡；侧环；持家基因；奢侈基因","src":"章节题库","oe":["该空填持家基因，多线染色体间带基因多为持家基因。","该空填奢侈基因，多线染色体带上基因多为奢侈基因。"]},{"q":"23． 面附有______，与______相连续，面向核质的一层膜为______，其上附着的蛋白纤维网是 ______。","a":"7．5 nm 外核膜；核糖体；糙面内质网；内核膜；核纤层蛋白","src":"章节题库","oe":["该空填核糖体，外核膜表面附着有核糖体颗粒。","该空填糙面内质网，外核膜与糙面内质网相连续。","该空填内核膜，面向核质的一层膜为内核膜。","该空填核纤层蛋白，内核膜内侧的蛋白纤维网即核纤层。"]},{"q":"24．","a":"核基质；核纤层；染色体骨架","src":"章节题库"},{"q":"25．","a":"胞质环；核质环；辐；中央栓","src":"章节题库"},{"q":"26． 个______，以及 1 分子的______。","a":"核小体；200；组蛋白八聚体；H1 组蛋白","src":"章节题库","oe":["该空填组蛋白八聚体，由H2A、H2B、H3、H4各两分子组成。","该空填H1组蛋白，位于核小体核心外侧，锁住DNA进出。"]},{"q":"27． ______四种。","a":"正中着丝粒染色体；近中着丝粒染色体；近端着丝粒染色体；端着丝粒染色体查看 答案","src":"章节题库","oe":["该处按着丝粒位置分为正中、近中、近端和端着丝粒染色体。"]},{"q":"28． 酶Ⅱ催化 ______合成：RNA 聚合酶Ⅲ催化 ______合成。","a":"5.8S、18S 和 28rRNA；hnRNA；5SrRNA 和 rRNA","src":"章节题库","oe":["该空填hnRNA，RNA聚合酶Ⅱ转录生成mRNA前体。","该空填5S rRNA和tRNA，由RNA聚合酶Ⅲ催化合成。"]},{"q":"29．","a":"核小体；螺旋管；超螺旋管；染色单体","src":"章节题库"},{"q":"30．","a":"由 1000～4000 条丝组成；有带及间带；有胀泡","src":"章节题库"},{"q":"31．","a":"蛋白质；DNA","src":"章节题库"},{"q":"32．","a":"成熟的红细胞；植物成熟的筛管","src":"章节题库"},{"q":"33．","a":"高度重复；碱性染料","src":"章节题库"},{"q":"34．","a":"两个蛋白质分子的亮氨酸残基之间的疏水作用","src":"章节题库"},{"q":"35．","a":"正；碱性","src":"章节题库"},{"q":"36． 同步进行。","a":"1：1；S；DNA 复制","src":"章节题库","oe":["该空填1:1，组蛋白与DNA的含量之比约为1:1。","该空填S期，组蛋白在细胞周期的S期合成。","该空填DNA复制，组蛋白合成与DNA复制同步进行。"]},{"q":"37．","a":"提供遗传物质复制分裂所必需的基础结构；参与基因表达调控，起粗调作用查看答 案","src":"章节题库"},{"q":"38． ______个核小体，进一步包装，可形成长约______nm 的螺线管。","a":"20；33","src":"章节题库","oe":["该空填20，该DNA片段约可装配形成20个核小体。","该空填33，进一步盘绕形成长约33nm的螺线管。"]},{"q":"39．","a":"不环化；不黏合；不被降解","src":"章节题库"},{"q":"40．","a":"尾部","src":"章节题库"},{"q":"41．","a":"m7GpppGp","src":"章节题库"},{"q":"42． 相连，内膜内侧的一层蛋白质叫作核纤层，属于______，起______的作用。核纤层在细胞周 期中参与细胞核膜的______，其机理主要是通过______。广义的核骨架除了包括核纤层之外， 还包括和染色体骨架。细胞核是遗传物质的，DNA 的转录和______都在核中进行。而核蛋 白则是在______中合成后通过核孔转运到核中，______信号在______核蛋白的运输中有重要 作用。核孔对物质的运输有两个重要的特点：①______；②______。核内的遗传物质在间期， 是以较松散状态存在的，称之为染色质。遗传物质有四级结构，初级结构叫______，最高级 结构叫______。遗传物质的初级结构是可以自我组装的，但要有一种称为分子伴侣的物质 ______来介导。","a":"两层膜；孔；内质网；中间纤维；固定染色体；解体和重建；磷酸化和去磷酸化；核基质； 储存场所；加工；细胞质；核定位；双向性；可调节性；核小体；染色体；核质蛋白","src":"章节题库","oe":["该空填中间纤维，核纤层属于Ⅴ型中间纤维蛋白。","该空填固定染色体，核纤层起固定染色体和核膜的作用。","该空填解体和重建，核纤层磷酸化参与核膜解体与重建。","该空填磷酸化和去磷酸化，这是核纤层解聚与重组的机理。","该空填加工，DNA转录和转录后加工都在核内进行。","该空填细胞质，核蛋白在细胞质中合成后经核孔入核。","该空填核定位，核定位信号引导亲核蛋白进入细胞核。","该空为亲核蛋白，核定位信号在其入核运输中起关键作用。","该空填双向性，核孔运输既介导入核又介导出核。","该空填可调节性，核孔运输的孔径和速率可被调节。","该空填核小体，染色质的一级结构即核小体。","该空填染色体，染色质的最高级结构是染色体。","该空填核质蛋白，作为分子伴侣介导核小体的组装。"]},{"q":"43．","a":"外核膜；内核膜；孔膜区","src":"章节题库"},{"q":"44．","a":"核纤层蛋白 A；核纤层蛋白 B；核纤层蛋白 C","src":"章节题库"},{"q":"45． 源是______。","a":"主动；双向；ATP","src":"章节题库","oe":["该空填ATP，核孔主动运输方向为双向，能源是ATP。"]},{"q":"46．","a":"常染色质；异染色质","src":"章节题库"},{"q":"47． 的含量则随着生理状态而变化。","a":"组蛋白；非组蛋白","src":"章节题库","oe":["该空填组蛋白，它与DNA是染色质的稳定成分。","该空填非组蛋白，其含量随细胞生理状态而变化。"]},{"q":"48．","a":"30","src":"章节题库"},{"q":"49．","a":"维持染色体的稳定；保证染色体 DNA 的完全复制","src":"章节题库"},{"q":"50．","a":"活跃转录","src":"章节题库"},{"q":"51． rRNA 转录以后，不是游离的 rRNA，而是一种______。","a":"核仁组织；核糖核蛋白","src":"章节题库","oe":["该空填核糖核蛋白，45S rRNA转录后与蛋白结合成核糖核蛋白。"]},{"q":"52．","a":"核糖体；粗面内质网","src":"章节题库"},{"q":"53. 用。","a":"物质交换","src":"章节题库"},{"q":"54． 染色质称______。","a":"随机；兼性异染色质","src":"章节题库","oe":["该空填兼性异染色质，如雌性哺乳动物随机失活的X染色体。"]},{"q":"55．","a":"核基质；核纤层；染色体骨架","src":"章节题库"},{"q":"56.","a":"B 型 DNA；A 型 DNA；Z 型 DNA","src":"章节题库"},{"q":"57．","a":"NORs 的 rDNA；级联放大","src":"章节题库"},{"q":"58．","a":"单一；中度重复；高度重复","src":"章节题库"},{"q":"2．","a":"切除修复","src":"名校考研真题"},{"q":"4． 合结构，是间期细胞遗传物质的存在形式。","a":"DNA；组蛋白；非组蛋白","src":"名校考研真题","oe":["该空填DNA，它是染色质的主要遗传物质成分。","该空填组蛋白，与DNA结合构成核小体的核心。","该空填非组蛋白，参与染色质的构建和基因表达调控。"]},{"q":"5． 于细胞质和细胞核的骨架结构体系，并为______和_______提供了结构支架。","a":"中间丝；核骨架；核膜；染色质","src":"名校考研真题","oe":["第一空填核膜：中间丝（核纤层）与核骨架为核膜提供结构支架。","第二空填染色质：核骨架为染色质提供锚定与支撑的结构支架。"]},{"q":"6． 它们的功能分别是______、_______和_______。","a":"自主复制 DNA 序列；着丝粒 DNA 序列；端粒 DNA 序列；保持染色体在细胞周期中的自我 复制和世代连续性；使复制的染色体平均分配到子细胞中去；保持染色体的独立性和稳定性","src":"名校考研真题","oe":["第一空为自主复制DNA序列的功能：保持染色体在细胞周期中的自我复制和世代连续性。","第二空为着丝粒DNA序列的功能：使复制后的染色体平均分配到子细胞中去。","第三空为端粒DNA序列的功能：保持染色体的独立性和稳定性。"]}],"judge":[{"q":"1．","a":"错","src":"章节题库"},{"q":"2.","a":"错","src":"章节题库"},{"q":"3．","a":"错","src":"章节题库"},{"q":"4．","a":"错","src":"章节题库"},{"q":"5．","a":"错","src":"章节题库"},{"q":"6．","a":"错","src":"章节题库"},{"q":"7. 仍保留了它们的核小体。（       ）","a":"对","src":"章节题库","oe":["正确。rDNA转录区似无核小体，其他多数基因仍保留核小体。","错误。该说法与事实相符，若判错则否定了核小体的保留现象。"]},{"q":"8．","a":"错","src":"章节题库"},{"q":"9．","a":"错","src":"章节题库"},{"q":"10． （     ）","a":"错","src":"章节题库"},{"q":"11．","a":"错","src":"章节题库"},{"q":"12．","a":"对","src":"章节题库"},{"q":"14． 式结合 DNA 的。（   ）","a":"错","src":"章节题库","oe":["错误。Jun和Fos以亮氨酸拉链形成二聚体结合DNA，非四聚体。","正确。Jun、Fos以二聚体形式结合DNA，故原说法错误，应判错。"]},{"q":"15．","a":"错","src":"章节题库"},{"q":"16．","a":"错","src":"章节题库"},{"q":"17．","a":"错","src":"章节题库"},{"q":"18．","a":"错","src":"章节题库"},{"q":"19．","a":"错","src":"章节题库"},{"q":"20．","a":"错","src":"章节题库"},{"q":"21．","a":"错","src":"章节题库"},{"q":"22．","a":"错","src":"章节题库"},{"q":"23． 核内输出到胞质，都是高度有选择性的。（                  ）","a":"错","src":"章节题库","oe":["错误。核孔复合体有效通道的大小是可以调节的。","正确。通道大小可调节，原说法与事实不符，应判错。"]},{"q":"2． 分是核骨架蛋白及核骨架结合蛋白，并含有少量 RNA。（                ）","a":"对","src":"名校考研真题","oe":["正确。核骨架主要成分为核骨架蛋白及结合蛋白，含少量RNA。","错误。核骨架确实以核骨架蛋白及结合蛋白为主，不应判错。"]},{"q":"6． 研]","a":"对","src":"名校考研真题"},{"q":"7． 海交通大学 2007 研]","a":"错","src":"名校考研真题","oe":["错误。组蛋白与DNA结合是结构性的，不依赖核苷酸特异序列。","正确。组蛋白与任何DNA均可形成核小体，故原说法错误。"]}]},"ch12":{"mcq":[{"q":"与核糖体组分的合成、定位和行使功能都不相关的细胞器是（              ）。","o":["A．细胞核","B．内质网","C．线粒体和叶绿体","D．过氧化物酶体"],"a":"D","e":"细胞核中核仁负责 rRNA 的合成、加工和核糖体亚单位装配；核糖体可定位于内质 网膜和线粒体与叶绿体膜参合成蛋白质；而过氧化物酶体与核糖体无关。","src":"章节题库","oe":["错误。核仁负责rRNA合成、加工及核糖体亚基装配，细胞核与核糖体密切相关。","错误。核糖体可附着在内质网膜上合成蛋白质，二者密切相关。","错误。线粒体和叶绿体含自身核糖体并能合成部分蛋白质。","正确。过氧化物酶体不含核糖体，与核糖体无关，故为本题答案。"]},{"q":"绝大多数原核细胞和真核细胞核糖体沉降系数分别为（              ）。","o":["A．80S 和 120S","B．70S 和 80S","C．50S 和 60S","D．80S 和 70S"],"a":"B","e":"原核细胞核糖体沉降系数为 70S，真核细胞核糖体沉降系数为 80S。","src":"章节题库","oe":["错误。真核核糖体为80S、原核为70S，不存在120S核糖体。","正确。原核细胞核糖体沉降系数为70S，真核细胞核糖体为80S。","错误。50S、60S分别是原核与真核核糖体大亚基的沉降系数。","错误。顺序颠倒，应是原核70S在前、真核80S在后。"]},{"q":"绝大多数哺乳动物细胞中，组成核糖体大亚基的 rRNA 是（           ）。","o":["A．28S、5.8S、5S rRNA","B．28S、18S、5S rRNA","C．23S、16S、5S rRNA","D．23S、18S、5.8S rRNA"],"a":"A","e":"原核细胞核糖体大亚基的 rRNA 为 23S、5S，小亚基 rRNA 为 16S；真核细胞核糖 体大亚基 rRNA 为 28S、5.8S、5S，小亚基 rRNA 为 18S。","src":"章节题库","oe":["正确。真核核糖体大亚基含28S、5.8S、5S三种rRNA。","错误。18S rRNA属于小亚基，不存在于大亚基中。","错误。23S、16S是原核核糖体大、小亚基的rRNA。","错误。23S属原核大亚基，且大亚基不含18S rRNA。"]},{"q":"下列对核糖体的研究结论错误的是（            ）。","o":["A．体外实验中，随着核糖体溶液中 Mg 浓度的降低，核糖体的大小亚单位可离解 2+","B．体外实验中，随着核糖体溶液中 Mg2+浓度的增高，核糖体可以形成二聚体","C．真核细胞中，核糖体大亚单位内都有 28S rRNA","D．rRNA 中的某些核苷酸残基被甲基化修饰，甲基化常发生在较保守的 rRNA 序列中"],"a":"C","e":"在不同的真核细胞中，核糖体也存在着差异。动物细胞内，核糖体的大亚单位内有 28S rRNA，而在植物细胞、真菌细胞与原生动物细胞内的大亚单位中却是 25～26S rRNA。","src":"章节题库","oe":["正确陈述。体外降低Mg2+浓度确可使核糖体大小亚基离解，故不选。","正确陈述。体外升高Mg2+浓度确可促使核糖体二聚化，故不选。","本题答案。该说法错误：植物、真菌、原生动物大亚基为25～26S rRNA，并非都有28S。","正确陈述。rRNA甲基化常发生在较保守的序列中，故不选。"]},{"q":"有关核糖体 rRNA 与 r 蛋白的结构特点，下列说法错误的是（         ）。","o":["A．同一物种不同 r 蛋白的一级结构均有很大不同，在免疫学上几乎没有同源性","B．不同物种同一种类 r 蛋白之间具有很高的同源性，并在进化上非常保守","C．16S rRNA 一级结构是非常保守的，但其二级结构并不具有共同特征","D．通过制备 L11-rRNA 复合物的晶体，可获得其空间结构高分辨率的三维图像"],"a":"C","e":"对原核 16S rRNA 的序列分析表明其一级结构是非常保守的，16S rRNA 的二级结 构-臂环结构（stem-loop structure）具有更高的保守性。","src":"章节题库","oe":["正确陈述。同一物种不同r蛋白一级结构差异大、免疫学同源性低，故不选。","正确陈述。不同物种同种r蛋白高度同源且在进化上保守，故不选。","本题答案。该说法错误：16S rRNA二级结构（臂环）保守性更高，具共同特征。","正确陈述。L11-rRNA复合物晶体可解析高分辨率三维结构，故不选。"]},{"q":"核糖体中最主要的活性部位是（             ）。","o":["A．A 位点","B．P 位点","C．E 位点","D．肽酰转移酶的催化位点"],"a":"D","e":"该位点催化形成而肽酰 RNA。","src":"章节题库","oe":["错误。A位点是新掺入氨酰-tRNA的结合位点。","错误。P位点是延伸中肽酰-tRNA的结合位点。","错误。E位点是肽酰转移后空载tRNA的释放位点。","正确。肽酰转移酶催化位点催化肽键形成，是本题答案。"]},{"q":"最早生命体遗传物质的载体最有可能是（               ）。","o":["A．DNA","B．RNA","C．蛋白质","D．以上都是"],"a":"B","e":"从化学性质上推测，核糖较脱氧核糖更容易合成，因而最早的遗传物质的载体更可 能是 RNA 而不是 DNA。","src":"章节题库","oe":["错误。脱氧核糖较难合成，DNA不太可能是最早的遗传物质。","正确。核糖比脱氧核糖更易合成，故最早遗传物质载体更可能是RNA。","错误。蛋白质不能自我复制，不能作为遗传物质载体。","错误。只有RNA符合最早遗传物质的条件。"]},{"q":"真核细胞中蛋白质合成的第一步是（              ）。","o":["A．核糖体小亚单位与 mRNA5＇端的 cap 识别并结合在一起","B．核糖体小亚单位识别并结合 mRNA5＇端的起始密码 AUG 上游的核糖体结合序列","C．核糖体大亚单位与 mRNA5＇端的 cap 识别并结合在一起","D．核糖体小亚单位识别并结合 mRNA5＇端的起始密码 AUG"],"a":"A","e":"需与原核细胞区别，原核细胞核糖体小亚单位识别并结合 mRNA5＇端的起始密码 AUG 上游的核糖体结合序列。","src":"章节题库","oe":["正确。真核核糖体小亚单位识别并结合mRNA 5'端的帽子（cap）结构。","错误。识别结合起始密码上游核糖体结合序列是原核细胞的机制。","错误。与帽子识别结合的是小亚单位，而不是大亚单位。","错误。真核起始主要靠帽子识别，而非直接识别起始密码AUG。"]},{"q":"在多肽的合成中，哪个描述是正确的？（               ）","o":["A．多肽分子越大，合成速度越慢","B．多肽分子越大，合成速度越快","C．无论多肽分子大小，其合成速度基本一样","D．小分子多肽总是比大分子多肽合成的快"],"a":"C","e":"多肽合成速度提高的倍数与结合在 mRNA 上的核糖体的数目成正比，","src":"章节题库","oe":["错误。多肽合成速度与多肽分子大小无必然关系。","错误。分子越大合成越快没有依据，二者不成正比。","正确。核糖体沿mRNA移动速度相近，不同大小多肽合成速度基本一样。","错误。多肽合成速度不因分子小就一定更快。"]},{"q":"核糖体上有 A、P、E 三个功能位点，下述说法中，除（        ）外都是正确的。","o":["A．A 位点的 A 字母是氨酰 tRNA 的简称，该位点又叫受位","B．P 位点的 P 字母是酞酰 tRNA 的简称，该位点又叫供位","C．A、P 位点参与酞键的形成和转移","D．A、E 位点参与酞键的形成和转移"],"a":"D","e":"A 位点与新掺入的氨酰-tRNA 结合。E 位点：肽酰转移后与即将释放的 tRNA 结合。","src":"章节题库","oe":["正确陈述。A位点即氨酰-tRNA位点，又称受位，故不选。","正确陈述。P位点即肽酰-tRNA位点，又称供位，故不选。","正确陈述。参与肽键形成与转移的是A、P位点，故不选。","本题答案。该说法错误：参与肽键形成的是A、P位点，E位点是释放位点。"]}],"fill":[{"q":"1．","a":"蛋白质；RNA","src":"章节题库"},{"q":"2．","a":"细胞质膜；粗面内质网上","src":"章节题库"},{"q":"3． 基的沉降系数是______，小亚基的沉降系数是______。","a":"50S；30S；60S；40S","src":"章节题库","oe":["第一空填60S：真核细胞核糖体大亚基的沉降系数为60S。","第二空填40S：真核细胞核糖体小亚基的沉降系数为40S。"]},{"q":"4． 糖体______结合。","a":"易位子；大亚基","src":"章节题库","oe":["该空填大亚基：核糖体以其大亚基与内质网膜上的易位子结合进行共翻译转运。"]},{"q":"5． ______、______和______等，多数因子具有 GTPase 活性。","a":"起始因子（IF）；延伸因子（EF）；释放因子（RF）","src":"章节题库","oe":["第一空填起始因子（IF）：起始阶段所需，多数具GTPase活性。","第二空填延伸因子（EF）：肽链延伸阶段所需，具GTPase活性。","第三空填释放因子（RF）：终止阶段识别终止密码子，具GTPase活性。"]},{"q":"6．","a":"自我装配","src":"章节题库"},{"q":"7．","a":"RNA 分子","src":"章节题库"},{"q":"8． Ⅱ催化合成______；RNA 聚合酶 IIl 催化合成______。","a":"rRNA；hnRNA；5s rRNA 与 tRNA","src":"章节题库","oe":["第一空填hnRNA：RNA聚合酶Ⅱ催化合成mRNA的前体hnRNA。","第二空填5S rRNA与tRNA：RNA聚合酶Ⅲ催化合成5S rRNA和tRNA。"]},{"q":"9． ______的结合位点，P 位点为与______的结合位点，E 位点为______的结合位点。","a":"氨酰-tRNA；延伸中的肽酰-tRNA；肽酰转移后与即将释放的 tRNA","src":"章节题库","oe":["第一空填氨酰-tRNA：A位点是新掺入氨酰-tRNA的结合位点。","第二空填延伸中的肽酰-tRNA：P位点是延伸中肽酰-tRNA的结合位点。","第三空填肽酰转移后与即将释放的tRNA：E位点是其释放位点。"]},{"q":"10．","a":"5S rRNA","src":"章节题库"},{"q":"11.","a":"rRNA","src":"章节题库"},{"q":"12. 特性。","a":"遗传信息载体功能酶的催化功能","src":"章节题库"},{"q":"13．","a":"rRNA","src":"章节题库"},{"q":"14．","a":"tRNA、5S rRNA","src":"章节题库"},{"q":"15．","a":"18S；5.8S；5S","src":"章节题库"},{"q":"16． ______，而核糖体则是蛋白质合成的______。","a":"模板；运载工具；装配场所","src":"章节题库","oe":["第一空填运载工具：tRNA是氨基酸的运载工具，将氨基酸运至核糖体。","第二空填装配场所：核糖体是蛋白质合成的装配场所。"]},{"q":"17.","a":"指导 RNA；mRNA；遗传信息量","src":"章节题库"},{"q":"18． 核糖体要解离；当 Mg2+浓度大于______时，两个核糖体聚合成 100S 的二聚体。","a":"1 mmol／L；10 mmol／L","src":"章节题库","oe":["该空填10 mmol/L：Mg2+大于此浓度时两核糖体聚合成100S二聚体，小于则解离。"]},{"q":"19．","a":"23S RNA","src":"章节题库"},{"q":"20．","a":"18S、5.8S、28S rRNA","src":"章节题库"},{"q":"21． 酸序列转变为多肽链中______序列。密码子是 mRNA 分子中每______个相邻的碱基决定合 成的多肽链中的一种氨基酸，故又称其为______体密码。遗传密码是所有 64 种密码子的总 称，包括______3 个终止密码子和 61 个分别编码______种氨基酸的密码子。其中______若 位于 mRNA 的起始端，则是肽链合成的“起步”信号，称为起始密码子；若出现在 mRNA 中 间则是______的密码子。 tRNA 是单链小分子，为三叶草状结构，有一个______环，其中______个碱基可以和 mRNA 上的密码子呈特异性互补，起识别 mRNA 密码子的作用。tRNA 上的这 3 个相邻碱基称为 ______。 在蛋白质的合成过程中 mRNA 起到______的作用，即根据 mRNA 分子中密码子的指令将合 成多肽链中氨基酸按相应顺序连接起来，密码子决定了多肽链合成的起始、______位置和其 上的氨基酸顺序。然而 mRNA 的密码子不能直接识别氨基酸，所以氨基酸必须先与相应的 tRNA 结合形成______，才能运到核糖体上。tRNA 以其______识别 mRNA 密码子，将相应 的氨基酸转运到核糖体上进行蛋白质合成。因此．通过密码子才能翻译出 mRNA 上的遗传 信息，翻译过程中需要既能携带氨基酸又能 识别密码子的 tRNA 作为连接器，将氨基酸转运到相应密码子的位置，完成蛋白质合成。","a":"mRNA；密码子；氨基酸；3；三联；UAA、UAG、UGA；20；AUG；甲硫氨酸；反密码 子；3；反密码子；合成模板；终止；氨酰 tRNA；反密码子","src":"章节题库","oe":["第1空填氨基酸：mRNA的核苷酸（密码子）序列决定多肽链的氨基酸序列。","第2空填3：密码子是mRNA上每3个相邻碱基决定一种氨基酸。","第3空填三联：因每3个碱基对应一种氨基酸，故称三联体密码。","第4空填UAA、UAG、UGA：64种密码子中这3个是终止密码子。","第5空填20：61个密码子分别编码20种氨基酸。","第6空填AUG：位于mRNA起始端的AUG是起始密码子。","第7空填甲硫氨酸：AUG既编码甲硫氨酸又作起始信号。","第8空填反密码子：tRNA三叶草结构中含有反密码子环。","第9空填3：反密码环中有3个碱基与mRNA密码子互补。","第10空填反密码子：tRNA上这3个相邻碱基称为反密码子。","第11空填合成模板：mRNA在蛋白质合成中起合成模板的作用。","第12空填终止：密码子决定肽链合成的起始、终止位置及氨基酸顺序。","第13空填氨酰-tRNA：氨基酸先与tRNA结合成氨酰-tRNA再运到核糖体。","第14空填反密码子：tRNA以其反密码子识别mRNA上的密码子。"]},{"q":"22．","a":"30S 小亚基；50S 大亚基；40S 小亚基；60S 大亚基","src":"章节题库"},{"q":"23． 有酶活性的生物大分子是______。","a":"rRNA；RNA","src":"章节题库","oe":["该空填RNA：具有酶活性的生物大分子是RNA（核酶），如rRNA可具催化活性。"]},{"q":"24．","a":"r 蛋白；rRNA","src":"章节题库"},{"q":"25． 域，分别是______、______、______和______。","a":"5’domain；3’major domain；major domain；central domain（或相应中文答案）查看 答案","src":"章节题库","oe":["第1空填5'domain：指16S rRNA 5'端形成的结构域。","第2空填3'major domain：指16S rRNA 3'端主要结构域。","第3空填major domain：指该rRNA的主要（中央）结构域。","第4空填central domain：指16S rRNA的中央结构域。"]},{"q":"26．","a":"与 mRNA 的结合位点；A 位点；P 位点；E 位点","src":"章节题库"},{"q":"27． 糖体的表面。","a":"RNA；蛋白质","src":"章节题库","oe":["第1空填RNA：核糖体由rRNA和蛋白质组成，rRNA是其主要成分之一。","第2空填蛋白质：蛋白质分布在核糖体表面，参与翻译。"]},{"q":"28． 然后与 tRNA 的 3’末端（3-羟基）的腺苷酸残基形成共价键，成为______。","a":"tRNA-氨酰基；羧基；氨酰基-tRNA","src":"章节题库","oe":["该空填氨酰基-tRNA：氨基酸与tRNA 3'端腺苷酸形成共价键后成为氨酰基-tRNA。"]},{"q":"29． 在真核生物起始复合物则是______。","a":"甲酰甲硫氨酸；甲硫氨酸（tRNAmet）","src":"章节题库","oe":["该空填甲硫氨酸（tRNAmet）：真核生物起始复合物的起始氨基酸为甲硫氨酸。"]},{"q":"1. 转录后加工修饰。","a":"hnRNA；rRNA","src":"名校考研真题","oe":["第1空填hnRNA：hnRNA（mRNA前体）需加帽、加尾和剪接等转录后加工。","第2空填rRNA：rRNA前体也需剪切加工成熟。"]},{"q":"2． 动部位是：_________、_________、_________和_________。","a":"真核；A 位点；P 位点；E 位点；肽酰转移酶催化中心","src":"名校考研真题","oe":["第1空填A位点：核糖体上结合氨酰-tRNA的活性部位。","第2空填P位点：核糖体上结合肽酰-tRNA的活性部位。","第3空填E位点：核糖体上释放空载tRNA的活性部位。","第4空填肽酰转移酶催化中心：催化肽键形成的活性部位。"]},{"q":"3． 后，__________才与之结合形成完整的核糖体。","a":"小亚基；大亚基","src":"名校考研真题","oe":["该空填大亚基：小亚基先与mRNA结合，随后大亚基与之结合形成完整核糖体。"]},{"q":"4． 东农业大学 2003 研]","a":"50；30","src":"名校考研真题","oe":["第1空填50：原核细胞核糖体大亚基的沉降系数为50S。","第2空填30：原核细胞核糖体小亚基的沉降系数为30S。"]}],"judge":[{"q":"1．","a":"错","src":"章节题库"},{"q":"2．","a":"错","src":"章节题库"},{"q":"3． 行。（    ）","a":"对","src":"章节题库"},{"q":"4． 成成熟的核糖体。（     ）","a":"错","src":"章节题库","oe":["若选“对”，等于认为核糖体在核仁内即成熟，忽视了大小亚基需在细胞质与mRNA结合才完整。","该说法错误。大小亚基在核仁组装后经核孔入细胞质，与mRNA结合才成有功能的核糖体。"]},{"q":"5．","a":"错","src":"章节题库"},{"q":"6．","a":"错","src":"章节题库"},{"q":"7．","a":"错","src":"章节题库"},{"q":"8． （    ）","a":"错","src":"章节题库"},{"q":"9．","a":"错","src":"章节题库"},{"q":"10．","a":"错","src":"章节题库"},{"q":"11．","a":"错","src":"章节题库"},{"q":"12．","a":"错","src":"章节题库"},{"q":"13． 然后边加工边装配核糖体的大、小两个亚基。（             ）","a":"错","src":"章节题库","oe":["若选“对”，等于认为在核内边加工边一次性装配成大、小两亚基，混淆了加工场所与分别装配。","该说法错误。rRNA前体在核仁加工，与r蛋白分别装配成大、小亚基，再各自经核孔入细胞质。"]},{"q":"2． 研]","a":"对","src":"名校考研真题"}]},"ch13":{"mcq":[{"q":"裂殖酵母中的 cdc2 基因在芽殖酵母中的同源物是（      ）。","o":["A．cdc2","B．cdc25","C．cdc28","D．cdc20"],"a":"C","e":"在芽殖酵母中的 cdc28 基因和裂殖酵母的 cdc2 基因产物为同源物，等同于 CDK1。","src":"章节题库","oe":["错误。cdc2是裂殖酵母的CDK1同源基因，不是芽殖酵母的。","错误。cdc25编码磷酸酶，并非细胞周期蛋白依赖性激酶。","正确。芽殖酵母cdc28产物与裂殖酵母cdc2同源，等同于CDK1。","错误。cdc20是APC的激活因子，不是CDK。"]},{"q":"与 PCNA 结合，直接抑制 DNA 复制的 CDK 激酶抑制物是（       ）。","o":["A．p27","B．P16","C．p18","D．p21"],"a":"D","e":"p21 为 CIP／KIP 类 CDK 激酶抑制物，PCNA 为 DNA 复制聚合酶δ的辅助因子， 为 DNA 复制所必需，p21 同 PCNA 结合后直接抑制 DNA 复制。","src":"章节题库","oe":["错误。p27属CIP/KIP类抑制物，但并非与PCNA结合抑制复制。","错误。p16属INK4类，抑制CDK4/6，不与PCNA结合。","错误。p18属INK4类CDK抑制物，与PCNA无关。","正确。p21与PCNA结合后直接抑制DNA复制，是本题答案。"]},{"q":"细胞合成新的组蛋白是在细胞周期的哪个阶段？（             ）","o":["A．G1","B．S","C．G2","D．M"],"a":"B","e":"在 DNA 复制的同时，组蛋白也被复制。","src":"章节题库","oe":["错误。G1期主要合成生长所需蛋白质等，组蛋白并非此时同步复制。","正确。组蛋白与DNA在S期同步复制，故为答案。","错误。G2期DNA已经复制完成，不再进行复制。","错误。M期染色体凝集并分裂，不进行DNA复制。"]},{"q":"在细胞周期的哪个时期，周期蛋白的浓缩程度最高？（               ）","o":["A．晚 G1 期和早 S 期","B．晚 G0 期和早 M 期","C．晚 G1 期和晚 G2 期","D．晚 M 期和晚 S 期"],"a":"C","e":"细胞中主要的周期蛋白分为周期蛋白 A 和周期蛋白 B 两种，周期蛋白 A 在 G1 期 的的早期开始表达并积累，到达 G1 /S 交界处含量达到最大值，并维持到 G2/ M 期。周期蛋 白 B 则是从 G1 期 晚期开始表达并逐渐积累到 G2 期后期阶段达到最大值，并一直维持到 M 期的中期阶段然后迅速降解。","src":"章节题库","oe":["错误。早S期不是周期蛋白B的峰值期。","错误。G0期无周期蛋白积累，早M期也非其峰值。","正确。周期蛋白A于晚G1（G1/S）达峰，周期蛋白B于晚G2达峰。","错误。晚M期周期蛋白B已降解，晚S期也不是峰值。"]},{"q":"5． 大部分的放射性将出现在（          ）。","o":["A．灯刷环上","B．沿着灯刷骨架","C．在灯刷环上与灯刷骨架上均有","D．与染色体无关"],"a":"A","e":"在很多动物尤其是鱼类、两栖类、爬行类和鸟类的雌性动物，染色体去凝集成一种 特殊的巨大的染色体结构，形似灯刷，称为灯刷染色体，在灯刷上有很多侧环结构，是进行 活跃转录 RNA 的部位。","src":"章节题库","oe":["正确。灯刷染色体的侧环是活跃转录RNA的部位，放射性最强。","错误。灯刷骨架（轴）转录不活跃，放射性弱。","错误。转录主要发生在侧环上，二者分布不均。","错误。灯刷染色体即染色体本身，转录在侧环上进行。"]},{"q":"细胞中 RNA 大量合成是在细胞周期中的（         ）。","o":["A．G1 期","B．S 期","C．G2 期","D．M 期"],"a":"A","e":"G1 期开始合成细胞生长所需要的各种蛋白质、糖类、脂质、RNA 等。","src":"章节题库","oe":["正确。G1期合成细胞生长所需的蛋白质、糖类、脂质和RNA等。","错误。S期主要进行DNA复制，不是生长物质合成的主要时期。","错误。G2期主要合成M期所需的结构蛋白等。","错误。M期主要进行染色质凝集与细胞分裂。"]},{"q":"1． 师范大学 2011 研]","o":["A．100%","B．50%","C．10%","D．0.3%"],"a":"D","e":"偶线期发生的重要事件：（1）同源染色体配对；（2）合成在 S 期未合成的约 0.3% 的 DNA（偶线期 DNA）。","src":"名校考研真题","oe":["错误。偶线期只合成约0.3%的DNA，并非全部100%。","错误。偶线期合成的DNA比例远低于50%。","错误。偶线期DNA只占约0.3%，不是10%。","正确。偶线期合成S期未合成的约0.3%的DNA（偶线期DNA）。"]},{"q":"染色体出现成倍状态发生于细胞周期中的（                ）[湖南大学 2007 研]","o":["A．G2 期和早 M 期","B．G1 期和 S 期","C．晚 M 期和 Gl 期","D．G0 期和 G1 期"],"a":"A","e":"S 期开始 DNA 的复制，同时染色体也在这个阶段完成复制。而 G2 与早 M 期是紧 接在 S 期之后的两个时期，其染色体同样保持成倍状态。","src":"名校考研真题","oe":["正确。S期复制后染色体成倍状态延续至G2期和早M期。","错误。G1期染色体尚未复制，不处于成倍状态。","错误。晚M期染色体已分离，G1期尚未复制。","错误。G0期和G1期均未完成DNA复制。"]}],"fill":[{"q":"1． ______。","a":"细线期；偶线期；粗线期；双线期；终变期","src":"章节题库","oe":["该空填减数分裂前期Ⅰ的五个时期：依次为细线期、偶线期、粗线期、双线期和终变期。"]},{"q":"2．","a":"周期中细胞；静止期细胞（G0 细胞）；终末分化细胞","src":"章节题库"},{"q":"3．","a":"不含中心体；以中间板形式进行胞质分裂","src":"章节题库"},{"q":"4． 开。到达______期，一对中心体开始分离，移向两极。","a":"G1 期；S 期；G2 期","src":"章节题库","oe":["该空填G2期：中心体在S期复制，到G2期一对中心体开始分离并移向两极。"]},{"q":"5．","a":"偶线期；双线期；粗线期","src":"章节题库"},{"q":"6．","a":"双线期","src":"章节题库"},{"q":"7． ______状。","a":"粉末","src":"章节题库","oe":["该空填粉末：间期核内染色质高度解螺旋、弥散分布，光镜下呈粉末状。"]},{"q":"8．","a":"启动期；DNA 合成期；细胞分裂期","src":"章节题库"},{"q":"9．","a":"无丝分裂；有丝分裂；减数分裂","src":"章节题库"},{"q":"10．","a":"分散；凝聚","src":"章节题库"},{"q":"11．","a":"秋水仙碱抑制了纺锤体的形成","src":"章节题库"},{"q":"12．","a":"染色质凝集成单条细线；细线与核膜相连；染色质线上有染色粒","src":"章节题库"},{"q":"13．","a":"20；100","src":"章节题库"},{"q":"14．","a":"S；M","src":"章节题库"},{"q":"15．","a":"周期中细胞；暂不增殖的细胞（G0 期细胞）；终末分化细胞","src":"章节题库"},{"q":"16．","a":"选择同步化；诱导同步化","src":"章节题库"},{"q":"17．","a":"减数分裂Ⅰ的前期","src":"章节题库"},{"q":"18．","a":"细线期；偶线期；粗线期；双线期；终变期","src":"章节题库"},{"q":"19． 的可长达数月之久，如______细胞和______细胞。","a":"胚胎；休眠；卵母","src":"章节题库","oe":["第一空填休眠：休眠细胞停留时间可长达数月。","第二空填卵母：卵母细胞停留时间也可长达数月甚至更久。"]},{"q":"20． 基继续培养。","a":"G1／s","src":"章节题库","oe":["该空填G1/S：细胞被同步化阻断在G1/S交界，撤除阻断后继续培养进入周期。"]},{"q":"21．","a":"有丝分裂器","src":"章节题库"},{"q":"22．","a":"主缢痕","src":"章节题库"},{"q":"2． 不同的概念，最本质的差别是：前者是_________，后者则是_________。","a":"蛋白质；DNA","src":"名校考研真题","oe":["第一空填蛋白质：前者在化学本质上属于蛋白质层次。","第二空填DNA：后者在化学本质上属于DNA层次，二者分子本质不同。"]},{"q":"4． 相连。","a":"着丝粒","src":"名校考研真题"},{"q":"5. 期细胞融合，则 S 期细胞__________，G2 期细胞_________。G1、S 和 G2 期细胞分别同 M 期细胞融合，则 Gl、S 及 G2 细胞均产生________。","a":"染色体凝聚；发生染色体复制；DNA 复制加快；保持不变；染色体超前凝聚查看 答案","src":"名校考研真题","oe":["第一空填DNA复制加快：S期细胞含高活性复制因子，融合后促进DNA复制加快。","第二空填保持不变：G2期DNA已复制完毕，融合后一般不发生再复制而保持原状。","第三空填染色体超前凝聚：G1、S、G2期细胞与M期细胞融合均被诱导产生PCC。"]},{"q":"6． DNA_______，随后_______。","a":"S；G2；先复制；线粒体分裂","src":"名校考研真题","oe":["第一空填先复制：线粒体分裂前其DNA先行复制。","第二空填线粒体分裂：DNA复制完成后线粒体随之分裂。"]}],"judge":[{"q":"1．","a":"对","src":"章节题库"},{"q":"2．","a":"错","src":"章节题库"},{"q":"3． （     ）","a":"对","src":"章节题库"},{"q":"4．","a":"错","src":"章节题库"},{"q":"5． 间分配。（     ）","a":"对","src":"章节题库","oe":["该说法正确。有丝分裂使复制后的染色体精确分离，遗传物质在子细胞间均等分配，保证遗传稳定。","若判为错则不当。复制后的染色体能精确分离并平均分配，正是细胞分裂维持遗传稳定的体现。"]},{"q":"6.","a":"错","src":"章节题库"},{"q":"7．","a":"对","src":"章节题库"},{"q":"8．","a":"对","src":"章节题库"},{"q":"9．","a":"错","src":"章节题库"},{"q":"10． （   ）","a":"错","src":"章节题库"},{"q":"1． （S 相）和分裂（M 相），而无生长现象，例如干细胞。（           ）","a":"错","src":"名校考研真题","oe":["若选“对”，等于认为存在只有S相和M相而无生长的细胞，与细胞周期含G1、S、G2、M不符。","错误。细胞周期含G1、S、G2、M各期，S与M间有生长期；干细胞亦有生长，非只复制分裂。"]},{"q":"2． 研]","a":"错","src":"名校考研真题"},{"q":"5． 大。（      ）","a":"对","src":"名校考研真题"}]},"ch14":{"mcq":[{"q":"MPF（CDK1）调控细胞周期中（         ）。","o":["A．G1 期向 M 期转换","B．G2 期向 M 期转换","C．G1 期向 S 期转换","D．S 期向 G2 期转换"],"a":"B","e":"MPF＝cdc2（CDK1）＋clyclin B，调控细胞由 G2 期向 M 期转换。","src":"章节题库","oe":["错误。MPF主要调控G2/M转换，不是由G1直接到M。","正确。MPF（CDK1+周期蛋白B）调控细胞由G2期向M期转换。","错误。G1/S转换主要由CDK2-周期蛋白E等调控。","错误。S/G2转换不由MPF调控。"]},{"q":"周期蛋白依赖性蛋白激酶中，充当调节亚基的是（              ）。","o":["A．周期蛋白","B．CDK 蛋白","C．MPF 蛋白","D．都不是"],"a":"A","e":"在 CDK-Cyclin 复合物中，CDK 为催化亚基，Cyclin 为调节亚基。","src":"章节题库","oe":["周期蛋白在CDK-Cyclin复合物中充当调节亚基，调控CDK活性，故选A。","CDK蛋白是该复合物的催化亚基，起催化磷酸化作用，而非调节亚基。","MPF是CDK与周期蛋白组成的复合物，并非单一的调节亚基。","A项周期蛋白正确，故D项“都不是”不成立。"]},{"q":"MPF 的功能有（     ）。","o":["A．催化组蛋白 H1 的磷酸化","B．催化核限层蛋白磷酸化","C．作用于微管蛋白，控制着细胞周期中微管的动力学变化","D．以上都正确"],"a":"D","e":"MPF 调控细胞由 G2 期向 M 期转换，其功能是催化靶蛋白磷酸化，为细胞由间期 进入分裂期做好准备。","src":"章节题库","oe":["MPF能催化组蛋白H1磷酸化，促进染色质凝集，故A正确。","MPF可催化核纤层蛋白磷酸化，导致核纤层解聚、核膜解体，B正确。","MPF作用于微管蛋白，调控M期微管的动力学变化，C正确。","A、B、C均为MPF的功能，故D“以上都正确”为答案。"]},{"q":"4． 哪种磷酸酶的催化（        ）。","o":["A．Weel","B．CAK","C．cdc25","D．cdc20"],"a":"C","e":"Weel 激酶使 Thr14 和 Tyr15 的磷酸化，CAK 催化 Thr161 的磷酸化。","src":"章节题库","oe":["Weel是激酶，催化Thr14、Tyr15磷酸化，抑制CDK活性，非磷酸酶。","CAK是激酶，催化Thr161磷酸化而激活CDK，不属于该磷酸酶。","cdc25是磷酸酶，可去除Thr14、Tyr15磷酸，激活CDK，故正确。","cdc20参与激活后期促进复合物，并非去除抑制性磷酸的磷酸酶。"]},{"q":"MPF 中的拍 p32 蛋白能被下列哪种蛋白的特异性抗体识别（             ）。","o":["A．p34","B．p56","C．cyclin B","D．p45"],"a":"A","e":"p32 同 p34 为同源物。","src":"章节题库","oe":["p34（cdc2）是MPF的催化亚基，p32与其同源，故选A。","p56不是MPF的催化亚基，与已知组成不符。","cyclin B是MPF的调节亚基，并非催化亚基。","p45不是MPF的催化亚基，该项错误。"]},{"q":"将有丝分裂中期细胞与 G1 细胞融合，可诱导 G1 细胞出现早熟染色体凝集其形态为（       ）。","o":["A．单线状","B．双线状","C．粉末状","D．都不是"],"a":"A","e":"G0 期的 PCC 呈单细丝状，S 期的呈粉末状，G2 期的呈双线状。","src":"章节题库","oe":["G0期与M期细胞融合产生的PCC呈单细丝状，故G0期对应单线状，选A。","双线状是G2期PCC的特征，与G0期不符。","粉末状是S期PCC的特征，与G0期不符。","A项符合G0期PCC形态，故D“都不是”错误。"]},{"q":"在癌基因所编码的五类主要的蛋白中，哪类蛋白的突变是细胞癌变的主要原因?（             ）。","o":["A．生长因子","B．转录因子","C．信号转导通路蛋白","D．细胞周期蛋白"],"a":"C","e":"信号转导通路蛋白突变是细胞癌变的主要原因，如人类各种癌症中约 30％的癌症 是信号通路中的 ras 基因突变引起的。","src":"章节题库","oe":["生长因子基因突变仅与少数肿瘤相关，不是癌变的主要原因。","转录因子异常虽可致瘤，但不是最主要的癌变原因类别。","信号转导通路蛋白突变是癌变主因，约30%癌症由ras突变引起，正确。","细胞周期蛋白异常可致增殖失控，但并非最主要的癌变原因。"]},{"q":"抑癌基因之一是（          ）。","o":["A．c-fos","B．v-jun","C．v-raf","D．p53"],"a":"D","e":"前三个基因均为细胞增殖的正性调控基因。","src":"章节题库","oe":["c-fos是原癌基因，正性调控细胞增殖，不属于抑癌基因。","v-jun是原癌基因，促进细胞增殖，非抑癌基因。","v-raf是原癌基因，经MAPK通路促进增殖，非抑癌基因。","p53是抑癌基因，负性调控增殖并诱导凋亡，故选D。"]}],"fill":[{"q":"1． 于调节亚基。","a":"周期蛋白；周期蛋白依赖的蛋白激酶；周期蛋白依赖的蛋白激酶；周期蛋白查看答 案","src":"章节题库","oe":["周期蛋白：在CDK-Cyclin复合物中作为调节亚基，故第一空填周期蛋白。","周期蛋白依赖的蛋白激酶：即CDK，作为催化亚基，故第二空填此。","周期蛋白依赖的蛋白激酶：CDK为催化亚基，需结合周期蛋白激活。","周期蛋白：周期蛋白为调节亚基，其含量随细胞周期波动，故填此。"]},{"q":"2.","a":"G2","src":"章节题库"},{"q":"3.","a":"激酶 CAK","src":"章节题库"},{"q":"4．","a":"泛素激活酶（E1）；泛素结合酶（E2）；泛素连接酶（E3）","src":"章节题库"},{"q":"5.","a":"后期促进因子；调节 M 期周期蛋白泛素化途径降解；cdc20 蛋白","src":"章节题库"},{"q":"6．","a":"P34cdc2 蛋白激酶；细胞周期蛋白","src":"章节题库"},{"q":"7.  成，后者由                 与______组成。","a":"周期蛋白 B；周期蛋白 A","src":"章节题库","oe":["前者含周期蛋白B（如MPF），后者由周期蛋白A组成，故填周期蛋白B与周期蛋白A。"]},{"q":"8.","a":"细胞周期蛋白","src":"章节题库"},{"q":"9.","a":"丝氨酸或苏氨酸","src":"章节题库"},{"q":"10．","a":"细线状；双线状；粉末状","src":"章节题库"},{"q":"11．","a":"P34cdc2","src":"章节题库"},{"q":"12.","a":"周期蛋白 B；CDKl 蛋白","src":"章节题库"},{"q":"13．","a":"周期蛋白；CDK 蛋白","src":"章节题库"},{"q":"14．","a":"G1／S 检验点；S 期检验点；G2／M 检验点；纺锤体装配检验点","src":"章节题库"},{"q":"15．","a":"泛素-蛋白酶体降解","src":"章节题库"},{"q":"16．","a":"病毒癌基因","src":"章节题库"},{"q":"17． 发生癌变。","a":"抑癌基因","src":"章节题库","oe":["抑癌基因：其突变或功能丧失使细胞失去生长抑制，进而发生癌变。"]},{"q":"18．","a":"生长因子；生长因子受体；胞内信号转导通路分子；转录因子；细胞周期蛋白； 凋亡蛋白； DNA 修复蛋白","src":"章节题库"},{"q":"19．","a":"通用转录因子；特异转录因子","src":"章节题库"},{"q":"20． 通过与其他蛋白作用而激活转录。","a":"DNA 结合结构域；转录激活结构域","src":"章节题库","oe":["DNA结合结构域：转录因子借此识别并结合靶基因的DNA序列。","转录激活结构域：通过与其他蛋白作用，招募辅激活因子激活转录。"]},{"q":"21.","a":"TATA","src":"章节题库"},{"q":"22． 它们编码的蛋白质抑制细胞生长，并阻止细胞癌变。癌基因则是细胞生长的______,它们编 码的蛋白质使细胞生长不受控制，并促进细胞癌变。","a":"制动器；加速器","src":"章节题库","oe":["加速器：癌基因是细胞生长的加速器，其产物促进增殖，与抑癌基因的制动器相反。"]},{"q":"23．","a":"Sanger","src":"章节题库"},{"q":"24. ______有关。","a":"转录调控区；5-C；阻抑","src":"章节题库","oe":["该空涉及转录调控区与DNA甲基化，5-甲基胞嘧啶对基因表达起阻抑作用。"]},{"q":"25． ______有关。","a":"3′UTR 微管；微丝","src":"章节题库","oe":["该空涉及3′UTR对mRNA稳定性的调控，以及微管、微丝等细胞骨架的参与。"]},{"q":"26． ______。","a":"肿瘤细胞；恶性肿瘤（癌症）","src":"章节题库","oe":["由肿瘤细胞恶变形成的即为恶性肿瘤（癌症），故填肿瘤细胞与恶性肿瘤。"]},{"q":"1． 期呈______状，G2 期的呈______状。","a":"粉末；双线","src":"名校考研真题","oe":["粉末：S期PCC呈粉末状，因染色质处于复制解凝状态。","双线：G2期PCC呈双线状，因染色质已复制为双份。"]},{"q":"2. 与 组成。","a":"cyclin B；cyclin A","src":"名校考研真题","oe":["cyclin B：MPF（成熟促进因子）的调节亚基为周期蛋白B。","cyclin A：S期促进因子等的调节亚基为周期蛋白A。"]}],"judge":[{"q":"1． 熟。（      ）","a":"错","src":"章节题库"},{"q":"2．","a":"对","src":"章节题库"},{"q":"3．","a":"错","src":"章节题库"},{"q":"4．","a":"对","src":"章节题库"},{"q":"5．","a":"错","src":"章节题库"},{"q":"6． 都会导致癌变。（       ）","a":"错","src":"章节题库","oe":["选“对”：题干“都会”过于绝对，并非所有改变都必然导致癌变。","选“错”：癌变需多种基因改变累积，并非全都致癌，故判断正确。"]},{"q":"7．","a":"错","src":"章节题库"},{"q":"8．","a":"错","src":"章节题库"},{"q":"9． （     ）","a":"错","src":"章节题库"},{"q":"1.","a":"错","src":"名校考研真题"},{"q":"2． 去抑癌作用。（           ）","a":"错","src":"名校考研真题","oe":["选“对”：题干所述机制与去抑癌作用不符，判对则错误。","选“错”：去抑癌作用需抑癌基因功能丧失，题干表述有误，故为错。"]},{"q":"3． 研]","a":"错","src":"名校考研真题"},{"q":"4. 胞的增殖。（          ）","a":"对","src":"名校考研真题","oe":["选“对”：抑癌基因产物可抑制细胞增殖，题干判断符合事实。","选“错”：若否认其抑制增殖作用则错误，抑癌基因确能抑制增殖。"]},{"q":"5． 抑制。（         ）","a":"错","src":"名校考研真题"},{"q":"6． 细胞分裂的信号。（            ）","a":"对","src":"名校考研真题","oe":["选“对”：MPF是驱动G2向M转换、启动细胞分裂的信号，判断正确。","选“错”：否认其为细胞分裂信号则错误，MPF正是启动分裂的关键。"]}]},"ch15":{"mcq":[{"q":"下列哪种蛋白不是管家基因的表达产物？（           ）","o":["A．微管蛋白","B．糖酵解酶系","C．核糖体蛋白","D．珠蛋白"],"a":"D","e":"管家基因是指所有细胞都表达的基因，其产物为维持细胞生命所必需，前三种蛋白 均为细胞正常生命过程所必需，而珠蛋白是红细胞中特异表达的蛋白。","src":"章节题库","oe":["微管蛋白由管家基因编码，为细胞生命活动所必需，属管家基因产物。","糖酵解酶系普遍表达，是维持基本代谢的管家基因产物。","核糖体蛋白在各细胞中均表达，属管家基因产物。","珠蛋白为红细胞特异表达，属奢侈基因产物，非管家基因，故选D。"]},{"q":"受精卵能发育成一个完整的个体，这种能使后代细胞形成完整个体的潜能为（          ）。","o":["A．单能性","B．多能性","C．全能性","D．发育性"],"a":"C","e":"细胞全能性是指细胞经分裂和分化后仍具有产生完整有机体的潜能或特性。受精卵、 早期的胚胎细胞、植物细胞具有全能性。","src":"章节题库","oe":["单能性只能分化为一种细胞，不能解释受精卵发育为完整个体。","多能性可分化多种细胞但不能发育为完整个体，表述不全面。","全能性指分裂分化后仍能产生完整个体的潜能，受精卵具全能性，正确。","发育性不是细胞分化潜能的规范分类说法。"]},{"q":"3． （   ）。","o":["A．分化程度相同","B．分化程度低","C．分化程度高","D．成为干细胞"],"a":"C","e":"分化程度较正常细胞分化程度低是肿瘤细胞的一个重要特征。细胞分化程度越低， 恶性程度越高。","src":"章节题库","oe":["肿瘤细胞与正常细胞分化程度存在差异，故“相同”不成立。","分化程度低提示恶性程度高，与本题所问不符。","该情形下细胞分化程度高（如高分化肿瘤），符合题意，故选C。","肿瘤细胞是分化异常而非成为干细胞，概念混淆。"]},{"q":"从体细胞克隆高等哺乳动物的成功说明了（      ）。","o":["A．体细胞的全能性","B．体细胞去分化还原性","C．体细胞核的全能性","D．体细胞核的去分化还原性"],"a":"C","e":"将体细胞核植入去核的受精卵细胞中，可以发育成为一个完整的机体，体现了细胞 核的全能性。","src":"章节题库","oe":["体细胞本身不能发育为完整个体，故非体细胞的全能性。","“去分化还原性”非规范概念，不能解释核移植实验。","将体细胞核植入去核受精卵可发育成完整个体，体现核的全能性，正确。","“去分化还原性”非标准表述，且非实验所得结论。"]},{"q":"5． 用力（    ）。","o":["A．范德华力","B．离子键","C．氢键","D．共价键"],"a":"D","e":"一般不形成共价键。","src":"章节题库","oe":["范德华力属弱作用力，参与细胞黏附。","离子键可提供静电吸引，参与黏附作用。","氢键参与黏附分子间的识别与结合。","细胞黏附一般不形成共价键，故选D。"]},{"q":"既能促进细胞的增殖，也能诱导细胞死亡的基因是（            ）。[复旦大学 2004 研]","o":["A．p53","B．Rb","C．Bax","D．c-myc","E．ras"],"a":"D","e":"AB 两项，p53、Rb 均属于抑癌基因，能够抑制细胞的增殖，且能诱导细胞凋亡。 C 项，Bax 基因能促进细胞凋亡。E 项，ras 基因能够诱导不同类型的分化和增殖。","src":"名校考研真题","oe":["p53属抑癌基因，抑制增殖并诱导凋亡，不符题意。","Rb属抑癌基因，抑制细胞增殖，不符题意。","Bax促进细胞凋亡，作用与题目所求相反。","c-myc属原癌基因，促进细胞增殖与分化，符合题意，故选D。","ras属原癌基因，经信号转导促进增殖，不是本题答案。"]}],"fill":[{"q":"1． 形成稳定性差异，产生各不相同的细胞类群的过程称为分化。","a":"形态；结构；功能","src":"章节题库","oe":["形态：细胞分化表现为形态上出现稳定性差异。","结构：分化也体现在细胞内部结构的差异。","功能：不同细胞类群功能各异，共同构成分化。"]},{"q":"2．","a":"一种关键性调节蛋白通过对其他调节蛋白的级联启动","src":"章节题库"},{"q":"3．","a":"高；低","src":"章节题库"},{"q":"4． 与卵细胞融合引起的，这样可快速阻止其他精子与卵细胞的融合，这一反应称为______。","a":"卵细胞质膜的快速去极化；多精受精的一级阻断","src":"章节题库","oe":["精卵融合引起卵膜快速去极化，立即阻止其余精子进入，称多精受精的一级阻断。"]},{"q":"5．","a":"40S 核糖体","src":"章节题库"},{"q":"6．","a":"细胞分化","src":"章节题库"},{"q":"7．","a":"全能向多能向专能逐步限制的","src":"章节题库"},{"q":"8． 经细胞、表皮细胞的胚层是______，能分化为毛发、牙齿、指甲等构造的胚层是______，可 分化为肌肉、骨骼、结缔组织的胚层是______，可分化为生殖系统的胚层是______。","a":"内胚层；外胚层；外胚层；中胚层；中胚层","src":"章节题库","oe":["外胚层：神经细胞、表皮细胞由外胚层分化而来。","外胚层：毛发、牙齿、指甲等由外胚层分化形成。","中胚层：肌肉、骨骼、结缔组织由中胚层分化而来。","中胚层：生殖系统主要由中胚层分化形成。"]},{"q":"9． 是特异性的。","a":"100","src":"章节题库","oe":["100：题干所问的特异性数量为100，属教材记忆性数值。"]},{"q":"10．","a":"受限而变窄；保持分化的全能性","src":"章节题库"},{"q":"11．","a":"细胞癌基因；病毒癌基因","src":"章节题库"},{"q":"12． 的。","a":"组织特异性基因在时间和空间上的差异表达","src":"章节题库"},{"q":"13．","a":"细胞形态结构；生理功能；生物学行为","src":"章节题库"},{"q":"1． 山大学 2008 研]","a":"美国科学家马里奥·卡佩奇（Mario Capecchi）和奥利弗·史密西斯（Oliver Smithies）、英国 科学家马丁·埃文斯（Martin Evans）；胚胎干细胞","src":"名校考研真题","oe":["马里奥·卡佩奇：2007年诺贝尔奖得主之一，基因敲除技术奠基人。","奥利弗·史密西斯与马丁·埃文斯：同为该奖得主，发展基因打靶技术。","胚胎干细胞：基因敲除以胚胎干细胞为载体，故第三空填此。"]},{"q":"2． _______，或称奢侈基因。","a":"管家基因；组织特异性基因","src":"名校考研真题","oe":["组织特异性基因仅在某些细胞表达，故又称奢侈基因；管家基因则普遍表达。"]}],"judge":[{"q":"1． 细胞，但是不可能诱发整个器官的形成。（          ）","a":"错","src":"章节题库","oe":["选“对”：题干断言不可能形成器官，与可诱导器官形成的事实矛盾。","选“错”：该细胞能诱发完整个器官，题干说法不成立，故判错正确。"]},{"q":"2． 段。（   ）","a":"错","src":"章节题库"},{"q":"3． 因。（   ）","a":"对","src":"章节题库"},{"q":"4．","a":"错","src":"章节题库"},{"q":"5．","a":"错","src":"章节题库"},{"q":"6．","a":"错","src":"章节题库"},{"q":"7．","a":"错","src":"章节题库"},{"q":"8． 基因所组成。（        ）","a":"错","src":"章节题库","oe":["选“对”：若认为题干所述组成关系成立，则与事实不符。","选“错”：基因组并非由题干所言的单一成分组成，故判断正确。"]},{"q":"9．","a":"错","src":"章节题库"},{"q":"10． 甲基化，18 d 的胚胎肝有 30％rDNA 甲基化，而成年的大鼠肝组织 rDNA 的甲基化程度高达 60％。（    ）","a":"对","src":"章节题库","oe":["选“对”：随发育rDNA甲基化程度升高，与题述数据相符，判断正确。","选“错”：若否认甲基化随龄升高则与实验数据不符。"]},{"q":"11．","a":"错","src":"章节题库"},{"q":"12．","a":"错","src":"章节题库"},{"q":"13．","a":"错","src":"章节题库"},{"q":"14．","a":"错","src":"章节题库"},{"q":"1．","a":"错","src":"名校考研真题"},{"q":"2． 组织。（      ）","a":"错","src":"名校考研真题"},{"q":"3． （     ）","a":"对","src":"名校考研真题"}]},"ch16":{"mcq":[{"q":"有关动物细胞凋亡最重要的特征，下列说法错误的是（        ）。","o":["A．整个过程中细胞质膜始终保持完整","B．细胞内含物不发生细胞外泄漏","C．不引发机体的炎症反应","D．细胞表面的特化结构消失"],"a":"D","e":"动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发 生细胞外泄漏，不引发机体的炎症反应。","src":"章节题库","oe":["凋亡全过程质膜保持完整，故A是凋亡特征的正确描述。","凋亡时细胞内含物不外泄，不会引起周围炎症，B正确。","不引发机体炎症反应是凋亡的典型特征，C正确。","细胞表面特化结构消失属坏死表现，不是凋亡特征，故选D。"]},{"q":"细胞凋亡的一个重要特点是（     ）。","o":["A．DNA 随机断裂","B．DNA 发生核小体间的断裂","C．70S 核糖体中的 rRNA 断裂","D．80S 核糖体中 rRNA 断裂"],"a":"B","e":"凋亡细胞 DNA 链断裂发生在核小体间，而不是随机的；C、D 两个选项并不是凋 亡细胞的特征。","src":"章节题库","oe":["DNA随机断裂是坏死的特征，凋亡时并非随机断裂。","凋亡时核酸酶切割核小体间DNA，形成梯状条带，故B正确。","70S核糖体rRNA断裂不是凋亡细胞的特征。","80S核糖体rRNA断裂也不是凋亡的特征性变化。"]},{"q":"细胞凋亡 DNA 双链的断裂的主要部位是（    ）。","o":["A．富含 AT 的区域","B．富含 GC 的区域","C．核小体之间的连接区","D．已经发生 DNA 损伤的部位"],"a":"C","e":"细胞凋亡发生的直接原因是细胞核内的核酸酶被激活，这种核酸酶的切割作用主要 发生在核小体间的 DNA 链。","src":"章节题库","oe":["凋亡核酸酶的主要切割位点并非富含AT区域。","富含GC区域也不是凋亡核酸酶的主要切割位点。","凋亡核酸酶主要切割核小体之间的连接区DNA，故C正确。","已损伤DNA部位是修复对象，非凋亡切割的特征位点。"]},{"q":"关于细胞凋亡与坏死的区别，下列说法错误的是（       ）。","o":["A．细胞凋亡和细胞坏死都是细胞程序性主动性死亡","B．凋亡细胞和坏死细胞 DNA 电泳都呈“梯状”","C．细胞凋亡时不伴有局部的炎症反应；而细胞坏死时伴有局部的炎症反应","D．细胞凋亡时，胞膜及细胞器相对完整；细胞坏死时，胞膜破裂细胞结构溶解"],"a":"B","e":"凋亡细胞 DNA 电泳呈“梯状”；坏死细胞 DNA 电泳呈不规则弥散状。","src":"章节题库","oe":["凋亡属程序性主动死亡，此表述（就凋亡而言）成立，非本题错误项。","凋亡DNA电泳呈梯状，坏死呈弥散状，二者并非都呈梯状，故B错误。","凋亡不伴局部炎症，坏死伴局部炎症，C叙述正确。","凋亡时胞膜及细胞器相对完整，坏死时胞膜破裂溶解，D叙述正确。"]},{"q":"下列哪个选项不是衰老细胞结构的变化？（      ）","o":["A．有序排列的内质网不复存在，内质网成分弥散性的分布于核周胞质中","B．线粒体的数量减少而体积增大，内容物呈现网状化并形成多囊体","C．致密体数量大大减少，几近消失","D．质膜处于凝胶相或固相；细胞间间隙连接减少"],"a":"C","e":"致密体是衰老细胞中常见的一种结构，绝大多数细胞在衰老时都会有致密体的积累。","src":"章节题库","oe":["衰老细胞内质网有序排列消失、成分弥散于核周，A叙述正确。","衰老时线粒体数量减少、体积增大、内容物网状化，B正确。","衰老细胞致密体增多，而C称其减少几近消失，故C错误，为答案。","衰老细胞质膜呈凝胶相、间隙连接减少，D叙述正确。"]},{"q":"对于体外培养的人二倍体细胞，决定其衰老的主要因素是（         ）。","o":["A．细胞培养的外环境","B．细胞核","C．细胞质","D．以上都不是"],"a":"B","e":"Hayflick 等的研究表明，决定细胞衰老的因素在细胞内部，而不在外部环境；是细 胞核而不是细胞质，决定细胞衰老的表达。","src":"章节题库","oe":["细胞培养的外环境不决定细胞衰老，错误。","决定细胞衰老的因素在细胞核，故B正确。","决定因素是核而非细胞质，该说法错误。","B项正确，故D“以上都不是”错误。"]},{"q":"7． 胞，其寿命比机体的寿命短；③快速更新的细胞。下列细胞中，属于第一类的细胞是（         ）。","o":["A．神经元、脂肪细胞、肌细胞","B．肝细胞、胃壁细胞","C．表皮细胞、红细胞和白细胞","D．肾皮质细胞、骨细胞、角膜上皮细胞"],"a":"A","e":"胃壁细胞属于更新较慢的细胞，角膜上皮细胞、表皮细胞、红细胞、白细胞属于快 速更新细胞。","src":"章节题库","oe":["神经元、脂肪细胞、肌细胞不再分裂、寿命与机体相当，属第一类，故选A。","肝细胞、胃壁细胞属更新较慢的第二类细胞，不符。","表皮细胞、红细胞和白细胞属快速更新的第三类，不符。","角膜上皮细胞属快速更新细胞，不符合第一类。"]},{"q":"下列哪一项不是 P53 的正常功能？（    ）","o":["A．激活细胞周期抑制因子的转录","B．在 Dy4A 修复中起作用","C．触发损伤细胞的凋亡","D．在小鼠胚胎发育中起基本作用"],"a":"D","e":"P53 是著名的肿瘤抑制因子，通过诱导细胞凋亡或生长停滞，避免细胞因为 DNA 的损伤而发生癌变。P53 能识别失去功能的端粒，继而诱导 P21 的表达，控制 CDK 的活化， 使得 Rb 不能被磷酸化，E2F 持续处于失活状态，最终引发衰老。P53 在 DNA 修复中也有 重要作用。","src":"章节题库","oe":["P53可诱导p21等细胞周期抑制因子转录，是其功能之一。","P53参与DNA修复，是该蛋白的功能。","P53可触发损伤细胞凋亡，是其功能。","P53敲除小鼠仍能正常发育，说明其非胚胎发育的基本作用，故选D。"]},{"q":"下列不属于细胞衰老的特征的是（      ）。","o":["A．线粒体数目减少，核膜皱襞","B．核明显变化为核固缩，常染色质减少","C．脂褐素减少，细胞代谢能力下降","D．原生质减少，细胞形状改变"],"a":"C","e":"细胞衰老的特征： （1）细胞内水分减少，致使细胞脱水收缩，体积变小； （2）细胞色素颗粒沉积增多，如脂褐素在胞浆中沉积随老年化过程而增加，如肝细胞、肌 细胞和神经细胞中的积聚更为明显； （3）细胞器的衰老变化：①细胞膜的流动性降低：衰老的细胞膜发生脂质过氧化反应，流 动性明显减弱，因而细胞的兴奋性降低；②线粒体的数量随着年龄的增大而减少，而其体积 则随着年龄的增大而增大；③高尔基复合体的分泌功能与囊泡运输功能下降；溶酶体酶活性 降低；内质网数量减少； （4）细胞核的变化：染色质固化，核膜内折； （5）化学组成与生化反应的改变：①蛋白质合成的速度下降；②细胞内酶的活性与含量改 变等。","src":"章节题库","oe":["衰老时线粒体数目减少、核膜皱襞，A叙述正确。","衰老时核固缩、常染色质减少，B正确。","衰老时脂褐素增多，而C称其减少，故C错误，为答案。","衰老时原生质减少、细胞形状改变，D叙述正确。"]}],"fill":[{"q":"1．","a":"凋亡；坏死；自噬","src":"章节题库"},{"q":"2.","a":"原癌；抑癌","src":"章节题库"},{"q":"3．","a":"形态学检测；DNA 电泳；TUNEL 测定法；彗星电泳法；流式细胞分析法","src":"章节题库"},{"q":"4．","a":"氧自由基理论；有丝分裂钟学说","src":"章节题库"},{"q":"5． 生的性质来说，有三种不同的类型：（1）______衰老；（2）______衰老；（3）______衰 老。","a":"生理性；病理性；心理性","src":"章节题库","oe":["生理性：按发生性质，自然衰老属生理性衰老。","病理性：由疾病等引起的衰老为病理性衰老。","心理性：因心理因素导致的衰老为心理性衰老。"]},{"q":"6． 造成的细胞崩溃裂解；后者是细胞在一定的______或______条件下按照自身的程序结束其生 存。","a":"坏死性；程序性；侵袭；生理；病理","src":"章节题库","oe":["生理：程序性死亡可在生理条件下按自身程序发生。","病理：也可在病理条件下按自身程序结束其生存。"]},{"q":"7．","a":"更新缓慢；快速更新","src":"章节题库"},{"q":"8． 维细胞分裂传代______次后开始衰老和死亡，而来自成年组织中的成纤维细胞只能培养 ______次就开始死亡。","a":"50；15～30","src":"章节题库","oe":["50：胚胎成纤维细胞约传代50次后衰老死亡，即Hayflick界限。","15～30：成年组织成纤维细胞仅能培养约15～30次即死亡。"]},{"q":"9． 奠基性贡献的三位科学家：英国的 Brenner、Sulston 和美国的 Horvitz。他们创造性地用______ 作为实验模型，实现了对器官发育过程中的______、______的原位观察，完成了______的绘 制，在此基础上发现并研究了调控器官发育______的关键基因。","a":"2002；线虫；细胞分裂；分化；细胞图谱；程序性细胞死亡","src":"章节题库","oe":["空1填线虫：以秀丽隐杆线虫为模型，细胞少且透明，便于活体追踪观察。","空2填细胞分裂：可原位观察器官发育中细胞的持续分裂过程。","空3填分化：同时原位观察细胞的分化过程。","空4填细胞图谱：据此完成了线虫细胞谱系（细胞图谱）的绘制。","空5填程序性细胞死亡：发现并研究调控凋亡的关键基因。"]},{"q":"10． 和 ces-2 基因；②______基因，即 ced-3、ced-4、ced-9 和 egl-1；③______基因，即 ced-1、 ced-2、ced-5、ced-6、ced-7、ced-10 和 ced-11；④______基因如核酸酶基因 1，即 muc-1 基 因。","a":"决定死亡的；执行死亡的；死亡细胞被吞噬细胞所吞噬的；死亡细胞在吞噬体中被 降解的","src":"章节题库","oe":["空1填执行死亡的：ced-3、ced-4、ced-9、egl-1 编码凋亡执行阶段的因子。","空2填死亡细胞被吞噬细胞所吞噬的：ced-1、2、5、6、7、10、11 参与吞噬。","空3填死亡细胞在吞噬体中被降解的：如核酸酶基因 nuc-1（muc-1）。"]},{"q":"11．","a":"复制衰老；胁迫诱导的早熟性衰老","src":"章节题库"},{"q":"12．","a":"物理性因子；化学及生物因子","src":"章节题库"},{"q":"13．","a":"自噬","src":"章节题库"},{"q":"14．","a":"ERC 的积累","src":"章节题库"},{"q":"15． ______相或______相。","a":"液晶；凝胶；固相","src":"章节题库","oe":["空1填凝胶：衰老或有缺陷的膜流动性降低，脂质排列趋于凝胶相。","空2填固相：膜进一步失去流动性则转为固相（健全膜为液晶相）。"]},{"q":"2． 2007 研]","a":"细胞凋亡；细胞自噬","src":"名校考研真题"}],"judge":[{"q":"1．","a":"对","src":"章节题库"},{"q":"2．","a":"错","src":"章节题库"},{"q":"3．","a":"错","src":"章节题库"},{"q":"4． （     ）","a":"错","src":"章节题库"},{"q":"5． （     ）","a":"对","src":"章节题库"},{"q":"6． 应物。caspase-9 属于调节物。（  ）","a":"错","src":"章节题库","oe":["选“对”：把caspase-9当作效应物是错的，它属于启动型caspase。","选“错”：caspase-9是启动型（调节物）caspase，题干把它误作效应物，故判断正确。"]},{"q":"7． 噬的信号，目前研究得最清楚的被吞噬信号是存在于程序性死亡细胞质膜脂双层外叶的磷脂 酰乙醇胺分子。（         ）","a":"错","src":"章节题库","oe":["选“对”：若判对则错，暴露于膜外叶的经典吞噬信号是磷脂酰丝氨酸。","选“错”：凋亡细胞外叶暴露磷脂酰丝氨酸而非磷脂酰乙醇胺，题述错误。"]},{"q":"8．","a":"错","src":"章节题库"},{"q":"9．","a":"错","src":"章节题库"},{"q":"1． 学 2008 研]","a":"错","src":"名校考研真题"},{"q":"2. 研]","a":"对","src":"名校考研真题"}]},"ch17":{"mcq":[{"q":"有关封闭连接，下列选项错误的是（  ）。","o":["A．紧密连接是封闭连接的主要形式，一般存在于上皮细胞之间","B．连接区域具有蛋白质焊接线，也称嵴线，由特殊的跨膜蛋白组成","C．使相邻细胞之间的质膜紧密结合，没有缝隙，阻止可溶性物质从质膜的一侧扩散到另一 侧","D．除形成渗漏屏障，起重要的封闭作用之外，它还有隔离和支持作用"],"a":"C","e":"封闭连接的封闭作用是：将相邻细胞的质膜密切联系在一起，阻止溶液中的分子沿 细胞间隙渗入体内，即阻止物质从上皮细胞层一侧扩散到另一侧，而并非阻止可溶性物质从 质膜的一侧扩散到另一侧。","src":"章节题库","oe":["正确。紧密连接即封闭连接的主要形式，多存在于上皮细胞之间。","正确。紧密连接区有跨膜蛋白构成的焊接线（嵴线）。","当选（错误项）。封闭作用阻止物质沿细胞间隙从上皮层一侧扩散到另一侧，非跨质膜扩散。","正确。紧密连接除形成渗漏屏障外，还有隔离和支持作用。"]},{"q":"有关黏合带与黏合斑，下列说法错误的是（  ）。","o":["A．黏合带中跨膜连接糖蛋白是钙黏蛋白家族","B．黏合带位于紧密连接下方，相邻细胞间形成一个连续的带状结构，因此它的主要功能是 与紧密连接起协同封闭作用","C．黏合斑是细胞通过肌动蛋白丝与细胞外基质之间的连接方式","D．黏合带与黏合斑均起着细胞附着与支持作用"],"a":"B","e":"黏合带，称带状桥粒，位于紧密连接下方，间隙约 15～20nm，它并不起封闭作用， 它的主要功能是起着细胞附着与支持作用。","src":"章节题库","oe":["正确。黏合带（带状桥粒）的跨膜连接糖蛋白属钙黏蛋白家族。","当选（错误项）。黏合带不参与封闭，主要起细胞附着与支持作用。","正确。黏合斑是细胞经肌动蛋白丝与细胞外基质相连的方式。","正确。黏合带与黏合斑均属锚定连接，起附着与支持作用。"]},{"q":"细胞外基质中含量最高，刚性及抗张力强度最大的成分是（    ）。","o":["A．胶原蛋白","B．氨基聚糖和蛋白聚糖","C．弹性蛋白","D．层粘连蛋白和纤连蛋白"],"a":"A","e":"由胶原装配成的纤维具有极高的抗张能力。","src":"章节题库","oe":["正确。胶原是含量最高、刚性和抗张强度最大的细胞外基质成分。","错误。氨基聚糖和蛋白聚糖高度水合，主要赋予抗压能力。","错误。弹性蛋白赋予网络弹性与回缩力，抗张强度不及胶原。","错误。层粘连蛋白和纤连蛋白主要介导细胞黏附，非抗张成分。"]},{"q":"植物细胞胞间连丝的形成与植物的（  ）有关。","o":["A．高尔基体","B．质膜","C．细胞核","D．内质网"],"a":"D","e":"胞间连丝穿越细胞壁，由相邻细胞的细胞质膜共同组成的管状结构，中央是由光面 内质网延伸形成的链样管。","src":"章节题库","oe":["错误。胞间连丝的形成与高尔基体无关。","错误。质膜参与构成管状结构外壁，但中央链样管来自内质网。","错误。胞间连丝的形成与细胞核无关。","正确。胞间连丝中央的链样管由光面内质网延伸形成。"]},{"q":"个体发育中出现最早的细胞外基质成分是（  ）。","o":["A．胶原","B．蛋白聚糖","C．层粘连蛋白","D．纤连蛋白"],"a":"C","e":"层粘连蛋白主要分布于各种动物胚胎及成体组织的基膜。","src":"章节题库","oe":["错误。胶原并非个体发育中出现最早的细胞外基质成分。","错误。蛋白聚糖不是发育中最早出现的细胞外基质成分。","正确。层粘连蛋白最早出现，主要分布于胚胎及成体组织的基膜。","错误。纤连蛋白不是个体发育中最早出现的基质成分。"]},{"q":"下列物质中除（  ）外，都是细胞外基质的组成部分。","o":["A．胶原","B．层黏连蛋白","C．整联蛋白","D．蛋白聚糖"],"a":"C","e":"细胞外基质包括胶原、弹性蛋白、糖胺聚糖和蛋白聚糖、纤连蛋白和层粘连蛋白。","src":"章节题库","oe":["属细胞外基质。胶原是其主要的纤维结构蛋白。","属细胞外基质。层黏连蛋白是基膜的重要成分。","当选（非基质）。整联蛋白是细胞膜上的受体，不属于细胞外基质。","属细胞外基质。蛋白聚糖是细胞外基质的重要成分。"]},{"q":"下列连接方式中，除（        ）外，都具有通讯作用。","o":["A．桥粒连接","B．间隙连接","C．胞间连丝","D．化学突触"],"a":"A","e":"通讯连接主要包括间隙连接（gap junction）、神经细胞间的化学突触（chemical synapse） 和植物细胞中的胞间连丝（plasmodesmata）。","src":"章节题库","oe":["当选（无通讯作用）。桥粒属锚定连接，主要起牢固连接作用。","有通讯作用。间隙连接是动物细胞主要的通讯连接。","有通讯作用。胞间连丝是植物细胞的通讯连接。","有通讯作用。化学突触是神经细胞间的通讯连接。"]}],"fill":[{"q":"1．","a":"封闭连接；锚定连接；通讯连接","src":"章节题库"},{"q":"2．","a":"间隙连接；化学突触；胞间连丝","src":"章节题库"},{"q":"3． 的细胞壁。","a":"初生壁；次生壁","src":"章节题库","oe":["空1填初生壁：生长中的植物细胞壁较薄，具有可伸展性。","空2填次生壁：大多数成熟植物细胞中发现的较厚细胞壁。"]},{"q":"4． 赋予的。","a":"胶原；弹性蛋白和蛋白多糖","src":"章节题库","oe":["空1填胶原：细胞外基质的抗拉力（抗张）特性主要由胶原赋予。","空2填弹性蛋白和蛋白多糖：细胞外基质的抗压力特性主要由它们赋予。"]},{"q":"5．","a":"连接子；6 个亚基；1.5","src":"章节题库"},{"q":"6．","a":"纤维素；胞壁酸","src":"章节题库"},{"q":"7．","a":"黏着带；黏着斑","src":"章节题库"},{"q":"8．","a":"Ⅳ型胶原；层黏连蛋白；蛋白聚糖","src":"章节题库"},{"q":"9．","a":"整联蛋白；胶原蛋白","src":"章节题库"},{"q":"10． 外基质中，透明质酸与______和核心蛋白组成软骨组织的蛋白聚糖复合物，称为透明质酸一 蛋自聚糖复合物。在这种复合物中，______作为一个长轴，将蛋白聚糖连接在一起，形成更 大的更复杂的蛋白聚糖，使细胞外基质具有更大的______。透明质酸是一种重要的糖胺聚糖， 是______细胞和______细胞的细胞外基质的主要成分，一旦______细胞停止移动，透明质酸 就会从______中消失，此时细胞间开始接触。","a":"蛋白聚糖；糖胺聚糖；透明质酸；抗压性；增殖；迁移；迁移；细胞外基质查看答 案","src":"章节题库","oe":["空1填糖胺聚糖：透明质酸与糖胺聚糖、核心蛋白组成软骨的蛋白聚糖复合物。","空2填透明质酸：在复合物中作为长轴，将蛋白聚糖连接成更大复合物。","空3填抗压性：复合物高度水合，使细胞外基质具有更大的抗压性。","空4填增殖：透明质酸是增殖细胞细胞外基质的主要成分。","空5填迁移：也是迁移细胞细胞外基质的主要成分。","空6填迁移：一旦迁移细胞停止移动，透明质酸便从基质中消失。","空7填细胞外基质：透明质酸从细胞外基质中消失，细胞间开始接触。"]},{"q":"11．","a":"抗压；抗张","src":"章节题库"},{"q":"12．","a":"糖胺聚糖；核心蛋白","src":"章节题库"},{"q":"13．","a":"细胞外基质；细胞外被；细胞质膜","src":"章节题库"},{"q":"14．","a":"胶原；25％","src":"章节题库"},{"q":"15．","a":"氨基己糖；糖醛酸","src":"章节题库"},{"q":"16．","a":"整联蛋白","src":"章节题库"},{"q":"17．","a":"高等植物","src":"章节题库"},{"q":"18．","a":"封闭蛋白；claudin","src":"章节题库"},{"q":"19． 长因子、转化生长因子β（TGF-β）等多种生长因子结合，因而可视为______，有利于激素 分子进一步与细胞表面受体结合，有效完成信号的传导。","a":"糖胺聚糖与核心蛋白；细胞外的激素富集与储存库","src":"章节题库","oe":["空填细胞外的激素富集与储存库：蛋白聚糖结合多种生长因子，利于激素与受体结合。"]},{"q":"20．","a":"整联蛋白；RGD 三肽序列","src":"章节题库"},{"q":"1． 有_________和_________。","a":"桥粒；半桥粒；黏着带；黏着斑","src":"名校考研真题","oe":["空1填桥粒：与中间纤维有关的细胞间锚定连接。","空2填半桥粒：与中间纤维有关的细胞—基质锚定连接。"]},{"q":"3． _________和_________。","a":"闭合蛋白（occludin）；密封蛋白（claudin）","src":"名校考研真题","oe":["空1填闭合蛋白（occludin）：从紧密连接嵴线中分离出的跨膜蛋白之一。","空2填密封蛋白（claudin）：另一类嵴线跨膜蛋白，是封闭链的主要成分。"]},{"q":"4．","a":"细胞内锚蛋白；跨膜黏附性蛋白","src":"名校考研真题"},{"q":"5． 的能力。","a":"抗压；抗张","src":"名校考研真题","oe":["空1填抗压：透明质酸高度水合，赋予细胞外基质抗压能力。","空2填抗张：胶原纤维使组织具有抗张（抗拉伸）能力。"]}],"judge":[{"q":"1． （    ）","a":"错","src":"章节题库"},{"q":"2．","a":"错","src":"章节题库"},{"q":"3．","a":"对","src":"章节题库"},{"q":"4．","a":"对","src":"章节题库"},{"q":"5．","a":"错","src":"章节题库"},{"q":"6． 由交换。（      ）","a":"错","src":"章节题库","oe":["选“对”错误：连接子通道并不能让物质自由交换，其开放具可调节性。","选“错”正确：连接子通道有选择性且可调节，不能进行物质自由交换。"]},{"q":"7．","a":"错","src":"章节题库"},{"q":"8．","a":"对","src":"章节题库"},{"q":"9．","a":"对","src":"章节题库"},{"q":"1． 强了抗压能力，水合胶的形成在于蛋白聚糖的糖基具有丰富的正电荷。（               ）","a":"错","src":"名校考研真题","oe":["选“对”错误：蛋白聚糖糖基带丰富的负电荷，并非正电荷。","选“错”正确：糖基带负电荷，静电吸引水与阳离子形成水合胶，增强抗压。"]}]}};